// Nuvemath — 5-sinf, I qism nazariyasi. Format: js/theory/GUIDE.md
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '5-1';

  // ---------- t1. 1 milliongacha bo'lgan sonlar ----------
  T.add(P, 't1', { sections: [
    { kind: 'intro', h: L('Million — bu qancha?', 'Миллион — это сколько?', 'How much is a million?'), p: [
      L('Tasavvur qiling: siz har soniyada bitta sonni aytasiz — «bir, ikki, uch…». Yuzgacha sanash uchun bir yarim daqiqa ketadi. Minggacha sanash uchun — qariyb 17 daqiqa. Milliongacha sanash uchun esa to‘xtamasdan <b>11 kun 14 soat</b> kerak bo‘ladi! Million — juda katta son, lekin biz uni yozishni, o‘qishni va u bilan ishlashni o‘rganamiz.', 'Представьте: вы называете по одному числу в секунду — «один, два, три…». Чтобы досчитать до ста, нужно полторы минуты. До тысячи — почти 17 минут. А чтобы досчитать до миллиона, понадобится <b>11 дней и 14 часов</b> без остановки! Миллион — очень большое число, но мы научимся его записывать, читать и работать с ним.', 'Imagine saying one number every second: “one, two, three…”. Counting to a hundred takes a minute and a half. Counting to a thousand takes almost 17 minutes. Counting to a million would take <b>11 days and 14 hours</b> without a break! A million is a huge number, but we will learn to write it, read it and work with it.'),
      L('Boshlang‘ich sinflarda siz minglik va yuz minglik sonlar bilan tanishgansiz. Endi bilimlarni tartibga solamiz: sonlar qanday <b>xonalar</b> va <b>sinflar</b>ga bo‘linadi, nima uchun 704 518 sonidagi 7 raqami «yetti» emas, balki «yetti yuz ming» degan ma’noni bildiradi.', 'В начальной школе вы уже встречали тысячи и сотни тысяч. Теперь приведём знания в порядок: на какие <b>разряды</b> и <b>классы</b> делится число и почему цифра 7 в числе 704 518 означает не «семь», а «семьсот тысяч».', 'In primary school you met thousands and hundreds of thousands. Now we put that knowledge in order: how a number splits into <b>places</b> and <b>periods</b>, and why the digit 7 in 704 518 does not mean “seven” but “seven hundred thousand”.'),
      L('Katta sonlar bizni hamma joyda kuchatadi: shahar aholisi, mashina narxi, stadiondagi tomoshabinlar soni, telefon xotirasidagi baytlar. Ularni to‘g‘ri o‘qiy olish — zamonaviy odam uchun savodxonlikning bir qismi.', 'Большие числа окружают нас повсюду: население города, цена машины, число зрителей на стадионе, байты в памяти телефона. Умение правильно их читать — часть грамотности современного человека.', 'Big numbers are everywhere: a city’s population, the price of a car, the crowd at a stadium, the bytes in a phone’s memory. Reading them correctly is part of being literate today.')
    ] },
    { kind: 'def', h: L('Xona va sinf', 'Разряд и класс', 'Place and period'), p: [
      L('Biz <b>o‘nlik sanoq sistemasi</b>da hisoblaymiz: o‘nta birlik — bitta o‘nlik, o‘nta o‘nlik — bitta yuzlik, o‘nta yuzlik — bitta minglik. Har safar birlik 10 marta kattalashadi. Sonning har bir raqami turgan o‘rin <b>xona</b> deb ataladi.', 'Мы считаем в <b>десятичной системе</b>: десять единиц — один десяток, десять десятков — одна сотня, десять сотен — одна тысяча. Каждый раз единица становится в 10 раз больше. Место, на котором стоит цифра, называется <b>разрядом</b>.', 'We count in the <b>decimal system</b>: ten ones make a ten, ten tens make a hundred, ten hundreds make a thousand. Each unit is 10 times bigger than the one before. The position a digit occupies is called its <b>place</b>.'),
      L('Xonalar o‘ngdan boshlab uchtadan guruhlanadi. Har bir uchlik <b>sinf</b> deyiladi:', 'Разряды группируют справа по три. Каждая такая тройка называется <b>классом</b>:', 'Places are grouped in threes from the right. Each group of three is called a <b>period</b>:')
    ], list: [
      L('<b>Birliklar sinfi</b> — birlik, o‘nlik, yuzlik xonalari (1-, 2-, 3-xonalar).', '<b>Класс единиц</b> — разряды единиц, десятков, сотен (1-й, 2-й, 3-й разряды).', '<b>Ones period</b> — ones, tens, hundreds (1st, 2nd, 3rd places).'),
      L('<b>Minglar sinfi</b> — ming birlik, ming o‘nlik, ming yuzlik xonalari (4-, 5-, 6-xonalar).', '<b>Класс тысяч</b> — разряды единиц тысяч, десятков тысяч, сотен тысяч (4-й, 5-й, 6-й разряды).', '<b>Thousands period</b> — thousands, ten thousands, hundred thousands (4th, 5th, 6th places).'),
      L('<b>Millionlar sinfi</b> — 7-xonadan boshlanadi. 1 000 000 — oltita nol bilan yoziladigan eng kichik yetti xonali son.', '<b>Класс миллионов</b> начинается с 7-го разряда. 1 000 000 — наименьшее семизначное число, в нём шесть нулей.', '<b>Millions period</b> starts at the 7th place. 1 000 000 is the smallest seven-digit number; it has six zeros.')
    ], after: [
      L('Bitta raqamning qiymati uning xonasiga bog‘liq. 555 555 sonida beshta ham 5 raqami bor, lekin ularning qiymati har xil: 500 000, 50 000, 5 000, 500, 50 va 5. Aynan shu g‘oya — <b>o‘rin qiymati</b> — butun sanoq sistemamizning asosidir.', 'Значение цифры зависит от её разряда. В числе 555 555 все цифры — пятёрки, но их значения разные: 500 000, 50 000, 5 000, 500, 50 и 5. Именно эта идея — <b>позиционное значение</b> — основа всей нашей системы счисления.', 'A digit’s value depends on its place. In 555 555 every digit is a five, but their values differ: 500 000, 50 000, 5 000, 500, 50 and 5. This idea, <b>place value</b>, is the foundation of our whole number system.')
    ] },
    { kind: 'history', h: L('Raqamlar qayerdan kelgan?', 'Откуда пришли цифры?', 'Where did the digits come from?'), p: [
      L('Biz ishlatadigan 0, 1, 2 … 9 raqamlari Hindistonda paydo bo‘lgan. Taxminan 1500 yil oldin hind olimlari o‘rin qiymatli yozuvni va <b>nol</b> belgisini qo‘llay boshlagan. Nol — buyuk kashfiyot: u «bu xonada hech narsa yo‘q» degan ma’noni bildiradi va 704 ni 74 dan farqlashga imkon beradi.', 'Цифры 0, 1, 2 … 9, которыми мы пользуемся, появились в Индии. Около 1500 лет назад индийские учёные стали применять позиционную запись и знак <b>нуля</b>. Нуль — великое изобретение: он означает «в этом разряде ничего нет» и позволяет отличить 704 от 74.', 'The digits 0, 1, 2 … 9 we use were born in India. About 1 500 years ago Indian scholars began using place-value notation and the sign for <b>zero</b>. Zero was a great invention: it means “nothing in this place” and lets us tell 704 from 74.'),
      L('IX asrda Xorazmda tug‘ilgan buyuk olim <b>Muhammad ibn Muso al-Xorazmiy</b> hind raqamlari va ular bilan hisoblash qoidalari haqida kitob yozdi. Bu kitob lotin tiliga tarjima qilinib, Yevropaga tarqaldi. Shuning uchun Yevropada bu raqamlar «arab raqamlari» deb atalgan, hisoblash usuli esa Xorazmiy nomidan «<b>algoritm</b>» deb nomlangan.', 'В IX веке великий учёный <b>Мухаммад ибн Муса аль-Хорезми</b>, родившийся в Хорезме, написал книгу об индийских цифрах и правилах счёта с ними. Книгу перевели на латынь, и она разошлась по Европе. Поэтому в Европе эти цифры назвали «арабскими», а способ вычислений — по имени Хорезми — «<b>алгоритмом</b>».', 'In the 9th century the great scholar <b>Muhammad ibn Musa al-Khwarizmi</b>, born in Khwarezm, wrote a book on the Indian digits and how to calculate with them. It was translated into Latin and spread across Europe. That is why Europeans called these digits “Arabic numerals”, and the method of calculation was named “<b>algorithm</b>” after al-Khwarizmi.'),
      L('Qadimgi rimliklar esa raqamlarni harflar bilan yozgan: M = 1000, D = 500, C = 100. Ularda million uchun alohida belgi yo‘q edi — ular raqam ustiga chiziq qo‘yib «ming marta» deb tushungan. O‘rin qiymatli yozuv ancha qulay: oltita nol — va million tayyor!', 'Древние римляне записывали числа буквами: M = 1000, D = 500, C = 100. Отдельного знака для миллиона у них не было — они ставили черту над числом, что означало «в тысячу раз больше». Позиционная запись гораздо удобнее: шесть нулей — и миллион готов!', 'The ancient Romans wrote numbers with letters: M = 1000, D = 500, C = 100. They had no separate sign for a million; a bar above a numeral meant “a thousand times more”. Place-value notation is far handier: six zeros and a million is written!')
    ] },
    { kind: 'rule', h: L('Katta sonni o‘qish qoidasi', 'Правило чтения большого числа', 'The rule for reading a big number'), p: [
      L('Katta sonni o‘qish uchun uni <b>o‘ngdan chapga</b> uchtadan sinflarga ajratamiz. Yozuvda sinflar orasida kichik bo‘sh joy qoldiriladi: 704 518. So‘ng <b>chapdan o‘ngga</b> har bir sinfni oddiy uch xonali son kabi o‘qib, sinf nomini qo‘shamiz.', 'Чтобы прочитать большое число, разбиваем его <b>справа налево</b> на классы по три цифры. В записи между классами оставляют небольшой пробел: 704 518. Затем <b>слева направо</b> читаем каждый класс как обычное трёхзначное число и добавляем название класса.', 'To read a big number, split it <b>from right to left</b> into periods of three digits. In writing we leave a small gap between periods: 704 518. Then, <b>from left to right</b>, read each period as an ordinary three-digit number and add the period’s name.'),
      L('704 518 → «704 ming» + «518» → <b>yetti yuz to‘rt ming besh yuz o‘n sakkiz</b>. Agar sinf butunlay nollardan iborat bo‘lsa, u o‘qilmaydi: 250 000 — «ikki yuz ellik ming».', '704 518 → «704 тысячи» + «518» → <b>семьсот четыре тысячи пятьсот восемнадцать</b>. Если класс состоит из одних нулей, его не читают: 250 000 — «двести пятьдесят тысяч».', '704 518 → “704 thousand” + “518” → <b>seven hundred and four thousand five hundred and eighteen</b>. If a period is all zeros it is not read: 250 000 is “two hundred and fifty thousand”.'),
      L('Sonni <b>xona qo‘shiluvchilari yig‘indisi</b> ko‘rinishida yozish mumkin: 704 518 = 700 000 + 4 000 + 500 + 10 + 8. Bu yozuv har bir raqamning haqiqiy qiymatini ko‘rsatadi.', 'Число можно записать в виде <b>суммы разрядных слагаемых</b>: 704 518 = 700 000 + 4 000 + 500 + 10 + 8. Такая запись показывает истинное значение каждой цифры.', 'A number can be written as a <b>sum of place values</b>: 704 518 = 700 000 + 4 000 + 500 + 10 + 8. This shows the true value of every digit.')
    ] },
    { kind: 'steps', h: L('Sonni so‘z bilan yozish: bosqichlar', 'Запись числа словами: шаги', 'Writing a number in words: steps'), list: [
      L('<b>1-qadam.</b> Sonni o‘ngdan uchtadan ajrating: 68 013 → 68 | 013.', '<b>Шаг 1.</b> Разбейте число справа по три цифры: 68 013 → 68 | 013.', '<b>Step 1.</b> Split the number in threes from the right: 68 013 → 68 | 013.'),
      L('<b>2-qadam.</b> Eng chap sinfdan boshlang: 68 — «oltmish sakkiz ming».', '<b>Шаг 2.</b> Начните с самого левого класса: 68 — «шестьдесят восемь тысяч».', '<b>Step 2.</b> Start with the leftmost period: 68 — “sixty-eight thousand”.'),
      L('<b>3-qadam.</b> Keyingi sinfni o‘qing, nolni o‘tkazib yuboring: 013 — «o‘n uch».', '<b>Шаг 3.</b> Прочитайте следующий класс, пропуская нули впереди: 013 — «тринадцать».', '<b>Step 3.</b> Read the next period, skipping leading zeros: 013 — “thirteen”.'),
      L('<b>4-qadam.</b> Birlashtiring: «oltmish sakkiz ming o‘n uch».', '<b>Шаг 4.</b> Соедините: «шестьдесят восемь тысяч тринадцать».', '<b>Step 4.</b> Join them: “sixty-eight thousand and thirteen”.'),
      L('<b>Teskari yo‘l.</b> So‘zdan raqamga o‘tganda har bir sinfga uchta o‘rin ajrating: «uch ming besh» → 3 | 005 → 3 005. Nollarni unutmang!', '<b>Обратный путь.</b> Переходя от слов к цифрам, отводите каждому классу три места: «три тысячи пять» → 3 | 005 → 3 005. Не забывайте нули!', '<b>The reverse.</b> Going from words to digits, give every period three places: “three thousand and five” → 3 | 005 → 3 005. Don’t forget the zeros!')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), p: [
      L('Avval o‘zingiz yeching, so‘ng javobni oching.', 'Сначала решите сами, потом откройте ответ.', 'Try first, then open the answer.')
    ], ex: [
      { q: L('306 040 sonini o‘qing va xona qo‘shiluvchilariga ajrating.', 'Прочитайте число 306 040 и разложите на разрядные слагаемые.', 'Read 306 040 and write it as a sum of place values.'), s: L('Sinflar: 306 | 040. «Uch yuz olti ming qirq». Yig‘indi: 300 000 + 6 000 + 40. Yuzlik, ming o‘nlik va birlik xonalarida nol turibdi — ular yig‘indida yozilmaydi.', 'Классы: 306 | 040. «Триста шесть тысяч сорок». Сумма: 300 000 + 6 000 + 40. В разрядах сотен, десятков тысяч и единиц стоят нули — в сумме их не пишут.', 'Periods: 306 | 040. “Three hundred and six thousand and forty”. Sum: 300 000 + 6 000 + 40. The hundreds, ten-thousands and ones places hold zeros, so they are left out of the sum.') },
      { q: L('«Besh yuz ming yetti» sonini raqamlar bilan yozing.', 'Запишите цифрами число «пятьсот тысяч семь».', 'Write “five hundred thousand and seven” in digits.'), s: L('Minglar sinfi: 500. Birliklar sinfi: faqat 7, demak 007. Javob: <b>500 007</b>. Ko‘p o‘quvchilar 5 007 yoki 500 7 deb yozib xato qiladi — har sinfda uchta o‘rin bo‘lishi shart.', 'Класс тысяч: 500. Класс единиц: только 7, значит 007. Ответ: <b>500 007</b>. Многие ошибаются и пишут 5 007 или 500 7 — в каждом классе должно быть три места.', 'Thousands period: 500. Ones period: just 7, so 007. Answer: <b>500 007</b>. Many pupils wrongly write 5 007 or 500 7 — every period needs three places.') },
      { q: L('482 719 sonida 8 va 1 raqamlarining qiymati qancha?', 'Каково значение цифр 8 и 1 в числе 482 719?', 'What are the values of the digits 8 and 1 in 482 719?'), s: L('8 raqami chapdan ikkinchi, ya’ni ming o‘nliklar xonasida: qiymati 80 000. 1 raqami o‘nliklar xonasida: qiymati 10. Tekshiruv: 400 000 + 80 000 + 2 000 + 700 + 10 + 9 = 482 719 ✓', 'Цифра 8 стоит второй слева, в разряде десятков тысяч: её значение 80 000. Цифра 1 — в разряде десятков: значение 10. Проверка: 400 000 + 80 000 + 2 000 + 700 + 10 + 9 = 482 719 ✓', 'The 8 is second from the left, in the ten-thousands place: value 80 000. The 1 is in the tens place: value 10. Check: 400 000 + 80 000 + 2 000 + 700 + 10 + 9 = 482 719 ✓') },
      { q: L('999 999 dan keyin qaysi son keladi? Undan oldin-chi?', 'Какое число следует за 999 999? А какое перед ним?', 'Which number comes after 999 999? And before it?'), s: L('999 999 + 1 = <b>1 000 000</b> — million, birinchi yetti xonali son. 999 999 − 1 = 999 998. Demak, 999 999 — eng katta olti xonali son.', '999 999 + 1 = <b>1 000 000</b> — миллион, первое семизначное число. 999 999 − 1 = 999 998. Значит, 999 999 — наибольшее шестизначное число.', '999 999 + 1 = <b>1 000 000</b>, a million, the first seven-digit number. 999 999 − 1 = 999 998. So 999 999 is the largest six-digit number.') }
    ] },
    { kind: 'table', h: L('Xonalar jadvali', 'Таблица разрядов', 'The place-value table'), p: [
      L('704 518 sonini jadvalga joylaymiz. Har bir ustun — bitta xona. Jadval sonni o‘qishda ham, yozishda ham yordam beradi.', 'Разместим число 704 518 в таблице. Каждый столбец — один разряд. Таблица помогает и читать, и записывать числа.', 'Let us place 704 518 in a table. Each column is one place. The table helps both in reading and in writing numbers.')
    ], table: { head: [L('Sinf', 'Класс', 'Period'), L('Minglar', 'Тысячи', 'Thousands'), '', '', L('Birliklar', 'Единицы', 'Ones'), '', ''], rows: [
      [L('Xona', 'Разряд', 'Place'), L('yuz ming', 'сотни тыс.', 'hundred th.'), L('o‘n ming', 'десятки тыс.', 'ten th.'), L('ming', 'тысячи', 'thousands'), L('yuzlik', 'сотни', 'hundreds'), L('o‘nlik', 'десятки', 'tens'), L('birlik', 'единицы', 'ones')],
      [L('Raqam', 'Цифра', 'Digit'), '7', '0', '4', '5', '1', '8'],
      [L('Qiymat', 'Значение', 'Value'), '700 000', '0', '4 000', '500', '10', '8']
    ] }, after: [
      L('Jadvaldan ko‘rinib turibdiki, 0 raqami ham muhim: u ming o‘nliklar xonasini «band qilib» turibdi. Agar uni olib tashlasak, 74 518 — butunlay boshqa son hosil bo‘ladi.', 'Из таблицы видно, что цифра 0 тоже важна: она «занимает» разряд десятков тысяч. Если её убрать, получится 74 518 — совсем другое число.', 'The table shows that the digit 0 matters too: it “holds” the ten-thousands place. Remove it and you get 74 518, a completely different number.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Nollarni tushirib qoldirish.</b> «To‘rt ming o‘n ikki» → 412 emas, <b>4 012</b>. Har bir sinfda uchta o‘rin bor.', '<b>Пропуск нулей.</b> «Четыре тысячи двенадцать» → не 412, а <b>4 012</b>. В каждом классе три места.', '<b>Dropping zeros.</b> “Four thousand and twelve” is not 412 but <b>4 012</b>. Every period has three places.'),
      L('<b>Sinflarni chapdan ajratish.</b> 70451 sonini 704 | 51 deb emas, o‘ngdan: 70 | 451 deb ajratamiz.', '<b>Разбиение классов слева.</b> Число 70451 делим не 704 | 51, а справа: 70 | 451.', '<b>Splitting periods from the left.</b> 70451 is split not as 704 | 51 but from the right: 70 | 451.'),
      L('<b>Raqam bilan qiymatni aralashtirish.</b> 350 000 sonida 5 raqamining qiymati 5 emas, 50 000.', '<b>Путаница цифры и значения.</b> В числе 350 000 значение цифры 5 — не 5, а 50 000.', '<b>Confusing digit with value.</b> In 350 000 the value of the digit 5 is not 5 but 50 000.'),
      L('<b>Million oldidagi songa xato.</b> 999 999 dan keyin 1 000 000 keladi, 10 000 00 yoki 100 000 emas.', '<b>Ошибка на границе миллиона.</b> После 999 999 идёт 1 000 000, а не 10 000 00 и не 100 000.', '<b>Slipping at the million boundary.</b> After 999 999 comes 1 000 000, not 10 000 00 or 100 000.'),
      L('<b>Xona o‘rnini noto‘g‘ri sanash.</b> Xonalar o‘ngdan sanaladi: birlik — 1-xona, o‘nlik — 2-xona va hokazo.', '<b>Неправильный счёт разрядов.</b> Разряды считают справа: единицы — 1-й, десятки — 2-й и так далее.', '<b>Counting places the wrong way.</b> Places are counted from the right: ones is 1st, tens is 2nd, and so on.')
    ] },
    { kind: 'life', h: L('Hayotda katta sonlar', 'Большие числа в жизни', 'Big numbers in real life'), p: [
      L('<b>Aholini sanash.</b> Samarqand shahrida 500 mingdan ortiq, Buxoroda 280 mingga yaqin kishi yashaydi. Statistika idoralari bunday sonlarni har yili hisoblab boradi va ular aynan ming va yuz minglik xonalar bilan yoziladi.', '<b>Перепись населения.</b> В Самарканде живёт более 500 тысяч человек, в Бухаре — около 280 тысяч. Статистические органы считают такие числа каждый год, и записываются они именно в разрядах тысяч и сотен тысяч.', '<b>Population counts.</b> More than 500 thousand people live in Samarkand and about 280 thousand in Bukhara. Statistics offices count such numbers every year, and they are written with thousands and hundred-thousands places.'),
      L('<b>Narxlar.</b> Do‘kondagi televizor 4 850 000 so‘m, velosiped 1 200 000 so‘m turadi. Chekni o‘qiganda sinflarga ajratish narxni darhol tushunishga yordam beradi: «to‘rt million sakkiz yuz ellik ming».', '<b>Цены.</b> Телевизор в магазине стоит 4 850 000 сумов, велосипед — 1 200 000 сумов. Разбиение на классы помогает сразу понять цену в чеке: «четыре миллиона восемьсот пятьдесят тысяч».', '<b>Prices.</b> A television costs 4 850 000 sum, a bicycle 1 200 000 sum. Splitting into periods helps you grasp the price on a receipt at once: “four million eight hundred and fifty thousand”.'),
      L('<b>Masofalar va vaqt.</b> Toshkentdan Nukusgacha avtomobil yo‘li taxminan 1 150 km, ya’ni 1 150 000 metr. Bir yilda 525 600 daqiqa bor. Kompyuter xotirasida 1 megabayt ≈ 1 000 000 bayt. Hamma joyda — xonalar va sinflar!', '<b>Расстояния и время.</b> Автодорога от Ташкента до Нукуса — около 1 150 км, то есть 1 150 000 метров. В году 525 600 минут. В памяти компьютера 1 мегабайт ≈ 1 000 000 байт. Всюду — разряды и классы!', '<b>Distances and time.</b> The road from Tashkent to Nukus is about 1 150 km, that is 1 150 000 metres. A year has 525 600 minutes. In a computer, 1 megabyte ≈ 1 000 000 bytes. Places and periods everywhere!')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Agar million dona 1 so‘mlik tangani ustma-ust tersak, ustun balandligi taxminan 1,5 km bo‘ladi — Toshkent teleminorasidan to‘rt marta baland!', 'Если сложить миллион монет по 1 суму стопкой, её высота будет около 1,5 км — в четыре раза выше Ташкентской телебашни!', 'A stack of a million 1-sum coins would be about 1.5 km tall — four times the height of the Tashkent TV tower!'),
      L('Million soniya — bu 11 kun 13 soat 46 daqiqa 40 soniya. Milliard soniya esa — 31 yildan ortiq!', 'Миллион секунд — это 11 дней 13 часов 46 минут 40 секунд. А миллиард секунд — больше 31 года!', 'A million seconds is 11 days, 13 hours, 46 minutes and 40 seconds. A billion seconds is more than 31 years!'),
      L('«Million» so‘zi italyancha «mille» (ming) so‘zidan kelib chiqqan va «katta ming» degan ma’noni bildiradi.', 'Слово «миллион» произошло от итальянского «mille» (тысяча) и означает «большая тысяча».', 'The word “million” comes from the Italian “mille” (thousand) and means “a big thousand”.'),
      L('Inson sochida o‘rtacha 100 000 ga yaqin tola bor. Million tola uchun o‘nta odam kerak bo‘lardi.', 'На голове человека в среднем около 100 000 волос. Чтобы набрать миллион, понадобилось бы десять человек.', 'A human head has on average about 100 000 hairs. You would need ten people to reach a million.'),
      L('Eng katta olti xonali son 999 999 va eng kichik olti xonali son 100 000 orasidagi farq 899 999 ga teng.', 'Разность между наибольшим шестизначным числом 999 999 и наименьшим 100 000 равна 899 999.', 'The difference between the largest six-digit number, 999 999, and the smallest, 100 000, is 899 999.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('Raqamlari 1, 0, 0, 5, 2, 0 bo‘lgan eng katta va eng kichik olti xonali sonlarni tuzing.', 'Составьте наибольшее и наименьшее шестизначные числа из цифр 1, 0, 0, 5, 2, 0.', 'Make the largest and the smallest six-digit numbers from the digits 1, 0, 0, 5, 2, 0.'),
      L('Qaysi sonda 7 raqamining qiymati kattaroq: 170 000 da yoki 700 100 da?', 'В каком числе значение цифры 7 больше: в 170 000 или в 700 100?', 'In which number is the digit 7 worth more: 170 000 or 700 100?'),
      L('Yuz mingdan milliongacha nechta son bor?', 'Сколько чисел от ста тысяч до миллиона?', 'How many numbers are there from one hundred thousand up to a million?'),
      L('20 000 so‘mlik pullardan million so‘m yig‘ish uchun nechta qog‘oz pul kerak?', 'Сколько купюр по 20 000 сумов нужно, чтобы собрать миллион сумов?', 'How many 20 000-sum notes are needed to make a million sum?')
    ], after: [
      L('Javoblar: eng katta — 521 000, eng kichik — 100 025 (olti xonali son nol bilan boshlanmaydi); 700 100 da (700 000 > 70 000); 900 001 ta son (100 000 dan 1 000 000 gacha, ikkalasi ham hisobga olinganda); 50 ta.', 'Ответы: наибольшее — 521 000, наименьшее — 100 025 (шестизначное число не начинается с нуля); в 700 100 (700 000 > 70 000); 900 001 число (от 100 000 до 1 000 000 включительно); 50 купюр.', 'Answers: largest 521 000, smallest 100 025 (a six-digit number cannot start with 0); in 700 100 (700 000 > 70 000); 900 001 numbers (from 100 000 to 1 000 000 inclusive); 50 notes.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Sonlar o‘nlik sanoq sistemasida yoziladi: har bir xona o‘ngdagisidan 10 marta katta.', 'Числа записываются в десятичной системе: каждый разряд в 10 раз больше соседнего справа.', 'Numbers are written in the decimal system: each place is 10 times the one to its right.'),
      L('Xonalar o‘ngdan uchtadan sinflarga bo‘linadi: birliklar, minglar, millionlar.', 'Разряды группируются справа по три в классы: единицы, тысячи, миллионы.', 'Places are grouped in threes from the right into periods: ones, thousands, millions.'),
      L('Sonni o‘qiganda har bir sinfni uch xonali son kabi o‘qib, sinf nomini qo‘shamiz.', 'Читая число, каждый класс читаем как трёхзначное число и добавляем название класса.', 'To read a number, read each period as a three-digit number and add the period’s name.'),
      L('Raqamning qiymati uning xonasiga bog‘liq: 704 518 da 7 → 700 000.', 'Значение цифры зависит от разряда: в 704 518 цифра 7 → 700 000.', 'A digit’s value depends on its place: in 704 518 the 7 → 700 000.'),
      L('Sonni xona qo‘shiluvchilari yig‘indisi ko‘rinishida yozish mumkin.', 'Число можно записать как сумму разрядных слагаемых.', 'A number can be written as a sum of place values.'),
      L('999 999 — eng katta olti xonali son; undan keyin 1 000 000 keladi.', '999 999 — наибольшее шестизначное число; за ним идёт 1 000 000.', '999 999 is the largest six-digit number; 1 000 000 comes next.')
    ] }
  ] });

  // ---------- t2. 10 milliongacha bo'lgan sonlar ----------
  T.add(P, 't2', { sections: [
    { kind: 'intro', h: L('Millionlar olamiga sayohat', 'Путешествие в мир миллионов', 'A journey into millions'), p: [
      L('2023-yilda Toshkent aholisi 3 000 000 kishidan oshdi. O‘zbekistonda 37 milliondan ortiq odam yashaydi. Tasavvur qiling — har bir kishi bitta raqam bo‘lsa, ularni yozish uchun qancha joy kerak bo‘lardi! Bu mavzuda biz 10 milliongacha bo‘lgan sonlar bilan ishlashni — ularni o‘qish, taqqoslash va yaxlitlashni o‘rganamiz.', 'В 2023 году население Ташкента превысило 3 000 000 человек. В Узбекистане живёт более 37 миллионов. Представьте — если бы каждый человек был одной цифрой, сколько места понадобилось бы для записи! В этой теме мы научимся работать с числами до 10 миллионов — читать, сравнивать и округлять их.', 'In 2023 the population of Tashkent passed 3 000 000. More than 37 million people live in Uzbekistan. Imagine — if every person were one digit, how much space would it take to write them all! In this topic we learn to work with numbers up to 10 million: reading, comparing and rounding them.'),
      L('Yetti xonali sonlar bizga notanish emas: ular avval o‘rganilgan qoidalar bo‘yicha o‘qiladi, faqat yangi sinf — <b>millionlar sinfi</b> qo‘shiladi. Lekin ikkita yangi ko‘nikma kerak: qaysi son kattaligini tez aniqlash va sonni qulay «yaxlit» songa almashtirish.', 'Семизначные числа нам не чужие: они читаются по уже знакомым правилам, только добавляется новый класс — <b>класс миллионов</b>. Но понадобятся два новых умения: быстро определять, какое число больше, и заменять число удобным «круглым».', 'Seven-digit numbers are not strangers: they are read by the rules we already know, with one new period added — the <b>millions period</b>. But two new skills are needed: quickly deciding which number is bigger, and replacing a number with a handy “round” one.'),
      L('Nega yaxlitlash kerak? Gazetada «Toshkentda 3 000 000 ga yaqin odam yashaydi» deyiladi, aniq son 2 980 000 bo‘lsa ham. Yaxlit sonni eslab qolish va taqqoslash osonroq. Olimlar, iqtisodchilar va jurnalistlar har kuni yaxlitlashdan foydalanadi.', 'Зачем округлять? В газете пишут «в Ташкенте живёт около 3 000 000 человек», даже если точное число 2 980 000. Круглое число легче запомнить и сравнить. Учёные, экономисты и журналисты пользуются округлением каждый день.', 'Why round? A newspaper says “about 3 000 000 people live in Tashkent” even if the exact figure is 2 980 000. A round number is easier to remember and compare. Scientists, economists and journalists round numbers every day.')
    ] },
    { kind: 'def', h: L('Millionlar sinfi. Taqqoslash. Yaxlitlash', 'Класс миллионов. Сравнение. Округление', 'The millions period. Comparing. Rounding'), p: [
      L('<b>Millionlar sinfi</b> — chapdan uchinchi sinf, u 7-, 8- va 9-xonalarni o‘z ichiga oladi. 10 milliongacha bo‘lgan sonlarda bu sinfda faqat bitta raqam bo‘ladi: 3 486 512 — «uch million to‘rt yuz sakson olti ming besh yuz o‘n ikki».', '<b>Класс миллионов</b> — третий класс слева, он включает 7-й, 8-й и 9-й разряды. В числах до 10 миллионов в этом классе только одна цифра: 3 486 512 — «три миллиона четыреста восемьдесят шесть тысяч пятьсот двенадцать».', 'The <b>millions period</b> is the third period from the left; it holds the 7th, 8th and 9th places. In numbers below 10 million this period has only one digit: 3 486 512 — “three million four hundred and eighty-six thousand five hundred and twelve”.'),
      L('<b>Sonlarni taqqoslash</b> — qaysi biri katta ekanini aniqlash. Natural sonlar uchun oddiy qoida bor: xonalari ko‘p bo‘lgan son katta. Xonalari teng bo‘lsa, chapdan birinchi farq qiladigan raqamga qaraymiz.', '<b>Сравнение чисел</b> — определение, какое из них больше. Для натуральных чисел есть простое правило: больше то число, в котором больше разрядов. Если разрядов поровну, смотрим на первую различающуюся цифру слева.', '<b>Comparing numbers</b> means deciding which is bigger. For whole numbers there is a simple rule: the number with more digits is bigger. With the same number of digits, look at the first digit from the left that differs.'),
      L('<b>Yaxlitlash</b> — sonni unga yaqin, lekin oxirida nollari bo‘lgan qulay son bilan almashtirish. Yaxlitlash <b>ma’lum bir xonagacha</b> bajariladi: o‘nliklargacha, yuzliklargacha, minglargacha va hokazo. Taqriban tenglik belgisi: <b>≈</b>. Masalan, 3 486 512 ≈ 3 487 000 (minglargacha).', '<b>Округление</b> — замена числа близким удобным числом с нулями на конце. Округляют <b>до определённого разряда</b>: до десятков, до сотен, до тысяч и так далее. Знак приближённого равенства: <b>≈</b>. Например, 3 486 512 ≈ 3 487 000 (до тысяч).', '<b>Rounding</b> replaces a number with a nearby convenient number ending in zeros. We round <b>to a certain place</b>: to tens, hundreds, thousands and so on. The sign for “approximately equal” is <b>≈</b>. For example, 3 486 512 ≈ 3 487 000 (to the nearest thousand).')
    ] },
    { kind: 'history', h: L('Katta sonlar tarixdan', 'Большие числа в истории', 'Big numbers through history'), p: [
      L('Qadimgi yunon olimi <b>Arximed</b> (miloddan avvalgi III asr) «Qum donalarini sanash» nomli asar yozgan. Unda u butun koinotni qum bilan to‘ldirsak, nechta dona kerak bo‘lishini hisoblagan! Buning uchun u o‘sha davrda mavjud bo‘lmagan, juda katta sonlarni yozish usulini o‘ylab topdi. Uning javobi 1 dan keyin 63 ta nol yoziladigan sondan kichik edi.', 'Древнегреческий учёный <b>Архимед</b> (III век до н. э.) написал сочинение «Исчисление песчинок». В нём он подсчитал, сколько песчинок понадобится, чтобы заполнить всю Вселенную! Для этого он придумал способ записи очень больших чисел, которого тогда не существовало. Его ответ был меньше числа, записываемого единицей с 63 нулями.', 'The ancient Greek scientist <b>Archimedes</b> (3rd century BC) wrote a work called “The Sand Reckoner”. In it he worked out how many grains of sand it would take to fill the whole universe! To do this he invented a way of writing enormous numbers that did not exist before. His answer was less than 1 followed by 63 zeros.'),
      L('O‘rta Osiyo olimi <b>Abu Rayhon Beruniy</b> (973–1048) Yer sharining aylanasini hisoblashda juda katta sonlar bilan ishlagan. Uning natijasi hozirgi o‘lchovlardan atigi bir necha foizga farq qiladi. Buyuk astronom <b>Mirzo Ulug‘bek</b> (1394–1449) Samarqanddagi rasadxonasida 1 018 yulduzning o‘rnini juda aniq o‘lchab, jadval tuzgan — hisoblashlar millionlab birlikka to‘g‘ri kelardi.', 'Среднеазиатский учёный <b>Абу Райхан Беруни</b> (973–1048) работал с очень большими числами, вычисляя окружность Земли. Его результат отличается от современных измерений всего на несколько процентов. Великий астроном <b>Мирзо Улугбек</b> (1394–1449) в своей обсерватории в Самарканде точно измерил положение 1 018 звёзд и составил таблицы — вычисления доходили до миллионов единиц.', 'The Central Asian scholar <b>Abu Rayhan Biruni</b> (973–1048) worked with very large numbers when calculating the circumference of the Earth. His result differs from modern measurements by only a few per cent. The great astronomer <b>Ulugh Beg</b> (1394–1449) measured the positions of 1 018 stars with great precision at his observatory in Samarkand and compiled tables; the calculations ran into millions of units.'),
      L('Yaxlitlash ham qadimdan ma’lum. Savdogarlar og‘irlikni, dehqonlar hosilni, hukmdorlar aholini taxminan — yaxlit sonlar bilan hisoblagan. Aniq hisob kerak bo‘lganda esa — barcha raqamlar saqlangan.', 'Округление тоже известно с древности. Торговцы считали вес, земледельцы — урожай, правители — население приблизительно, круглыми числами. Когда же нужен был точный счёт, сохраняли все цифры.', 'Rounding has also been known since ancient times. Merchants estimated weight, farmers their harvest, rulers their population, using round numbers. When an exact count was needed, every digit was kept.')
    ] },
    { kind: 'rule', h: L('Taqqoslash va yaxlitlash qoidalari', 'Правила сравнения и округления', 'Rules for comparing and rounding'), p: [
      L('<b>Taqqoslash qoidasi.</b> 1) Xonalar sonini solishtiring: 9 876 543 (7 xona) > 987 654 (6 xona). 2) Xonalar teng bo‘lsa, eng chap raqamdan boshlab solishtiring; birinchi farq hal qiladi: 5 040 000 va 5 400 000 — birinchi raqamlar teng (5), ikkinchilari 0 < 4, demak 5 040 000 < 5 400 000.', '<b>Правило сравнения.</b> 1) Сравните число разрядов: 9 876 543 (7 разрядов) > 987 654 (6 разрядов). 2) Если разрядов поровну, сравнивайте цифры с самой левой; первая разница решает: 5 040 000 и 5 400 000 — первые цифры равны (5), вторые 0 < 4, значит 5 040 000 < 5 400 000.', '<b>Comparing rule.</b> 1) Compare the number of digits: 9 876 543 (7 digits) > 987 654 (6 digits). 2) With equal lengths, compare digits from the left; the first difference decides: 5 040 000 and 5 400 000 — first digits equal (5), second digits 0 < 4, so 5 040 000 < 5 400 000.'),
      L('<b>Yaxlitlash qoidasi.</b> Qaysi xonagacha yaxlitlayotganingizni belgilang. Undan keyingi (o‘ngdagi) raqamga qarang: agar u <b>0, 1, 2, 3 yoki 4</b> bo‘lsa — belgilangan xonadagi raqam o‘zgarmaydi; agar <b>5, 6, 7, 8 yoki 9</b> bo‘lsa — belgilangan raqam 1 ga oshadi. Belgilangan xonadan o‘ngdagi barcha raqamlar nolga almashtiriladi.', '<b>Правило округления.</b> Отметьте разряд, до которого округляете. Посмотрите на следующую (правую) цифру: если она <b>0, 1, 2, 3 или 4</b> — цифра в отмеченном разряде не меняется; если <b>5, 6, 7, 8 или 9</b> — отмеченная цифра увеличивается на 1. Все цифры правее отмеченного разряда заменяются нулями.', '<b>Rounding rule.</b> Mark the place you are rounding to. Look at the next digit (to its right): if it is <b>0, 1, 2, 3 or 4</b>, the marked digit stays; if it is <b>5, 6, 7, 8 or 9</b>, the marked digit goes up by 1. All digits to the right of the marked place become zeros.'),
      L('3 486 <u>5</u>12 → minglargacha: minglar xonasida 6, keyingi raqam 5 → 6 ni 7 qilamiz → <b>3 487 000</b>. Yuz minglargacha: xonada 4, keyingi 8 → 5 → <b>3 500 000</b>. Millionlargacha: xonada 3, keyingi 4 → o‘zgarmaydi → <b>3 000 000</b>.', '3 486 <u>5</u>12 → до тысяч: в разряде тысяч 6, следующая цифра 5 → 6 становится 7 → <b>3 487 000</b>. До сотен тысяч: в разряде 4, следующая 8 → 5 → <b>3 500 000</b>. До миллионов: в разряде 3, следующая 4 → не меняется → <b>3 000 000</b>.', '3 486 <u>5</u>12 → to thousands: the thousands digit is 6, the next digit is 5 → 6 becomes 7 → <b>3 487 000</b>. To hundred thousands: digit 4, next 8 → 5 → <b>3 500 000</b>. To millions: digit 3, next 4 → unchanged → <b>3 000 000</b>.')
    ] },
    { kind: 'steps', h: L('Yaxlitlash: bosqichma-bosqich', 'Округление: шаг за шагом', 'Rounding step by step'), list: [
      L('<b>1-qadam.</b> Yaxlitlanadigan xonani toping va ostiga chizing: 7 2<u>6</u>4 819 (o‘n minglargacha).', '<b>Шаг 1.</b> Найдите нужный разряд и подчеркните его: 7 2<u>6</u>4 819 (до десятков тысяч).', '<b>Step 1.</b> Find the target place and underline it: 7 2<u>6</u>4 819 (to ten thousands).'),
      L('<b>2-qadam.</b> O‘ngdagi qo‘shni raqamga qarang: 4.', '<b>Шаг 2.</b> Посмотрите на соседнюю цифру справа: 4.', '<b>Step 2.</b> Look at the neighbour on the right: 4.'),
      L('<b>3-qadam.</b> 4 < 5, demak chizilgan raqam 6 ligicha qoladi.', '<b>Шаг 3.</b> 4 < 5, значит подчёркнутая цифра 6 остаётся.', '<b>Step 3.</b> 4 < 5, so the underlined 6 stays.'),
      L('<b>4-qadam.</b> Chizilgan xonadan o‘ngdagi hamma raqamni nol qiling: 7 260 000.', '<b>Шаг 4.</b> Все цифры правее подчёркнутой замените нулями: 7 260 000.', '<b>Step 4.</b> Replace every digit to the right with zero: 7 260 000.'),
      L('<b>5-qadam.</b> Javobni ≈ belgisi bilan yozing: 7 264 819 ≈ 7 260 000. Tekshiring: javob asl sondan 4 819 ga farq qiladi — bu 10 000 ning yarmidan kam, demak to‘g‘ri.', '<b>Шаг 5.</b> Запишите ответ со знаком ≈: 7 264 819 ≈ 7 260 000. Проверьте: ответ отличается от исходного на 4 819 — это меньше половины от 10 000, значит верно.', '<b>Step 5.</b> Write the answer with ≈: 7 264 819 ≈ 7 260 000. Check: the answer differs from the original by 4 819, less than half of 10 000, so it is right.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Taqqoslang: 8 099 999 va 8 100 000.', 'Сравните: 8 099 999 и 8 100 000.', 'Compare 8 099 999 and 8 100 000.'), s: L('Ikkalasi ham 7 xonali. Birinchi raqamlar teng: 8 va 8. Ikkinchi raqamlar: 0 < 1. Demak, <b>8 099 999 < 8 100 000</b>. Aslida bu ikki son qo‘shni: 8 099 999 + 1 = 8 100 000.', 'Оба числа семизначные. Первые цифры равны: 8 и 8. Вторые цифры: 0 < 1. Значит, <b>8 099 999 < 8 100 000</b>. На самом деле эти числа соседние: 8 099 999 + 1 = 8 100 000.', 'Both have 7 digits. First digits equal: 8 and 8. Second digits: 0 < 1. So <b>8 099 999 < 8 100 000</b>. In fact they are neighbours: 8 099 999 + 1 = 8 100 000.') },
      { q: L('4 975 300 sonini yuz minglargacha yaxlitlang.', 'Округлите 4 975 300 до сотен тысяч.', 'Round 4 975 300 to the nearest hundred thousand.'), s: L('Yuz minglar xonasida 9 turibdi, keyingi raqam 7 ≥ 5, demak 9 ni 1 ga oshiramiz. 9 + 1 = 10 — bu bitta xonaga sig‘maydi! Shuning uchun millionlar xonasiga 1 o‘tadi: 4 → 5, yuz minglar xonasida 0 qoladi. Javob: 4 975 300 ≈ <b>5 000 000</b>.', 'В разряде сотен тысяч стоит 9, следующая цифра 7 ≥ 5, значит 9 увеличиваем на 1. 9 + 1 = 10 — это не помещается в один разряд! Поэтому единица переходит в разряд миллионов: 4 → 5, а в сотнях тысяч остаётся 0. Ответ: 4 975 300 ≈ <b>5 000 000</b>.', 'The hundred-thousands digit is 9, the next digit is 7 ≥ 5, so we add 1 to 9. But 9 + 1 = 10 does not fit in one place! So 1 carries into the millions: 4 → 5, and the hundred-thousands digit becomes 0. Answer: 4 975 300 ≈ <b>5 000 000</b>.') },
      { q: L('Sonlarni o‘sish tartibida joylashtiring: 2 300 000; 980 000; 2 030 000; 2 299 999.', 'Расположите числа в порядке возрастания: 2 300 000; 980 000; 2 030 000; 2 299 999.', 'Put in increasing order: 2 300 000; 980 000; 2 030 000; 2 299 999.'), s: L('980 000 — olti xonali, u eng kichik. Qolgan uchtasi 2 bilan boshlanadi. Ikkinchi raqamlar: 3, 0, 2 → 2 030 000 < 2 299 999 < 2 300 000. Javob: <b>980 000 < 2 030 000 < 2 299 999 < 2 300 000</b>.', '980 000 — шестизначное, оно наименьшее. Остальные три начинаются с 2. Вторые цифры: 3, 0, 2 → 2 030 000 < 2 299 999 < 2 300 000. Ответ: <b>980 000 < 2 030 000 < 2 299 999 < 2 300 000</b>.', '980 000 has six digits, so it is the smallest. The other three start with 2. Second digits: 3, 0, 2 → 2 030 000 < 2 299 999 < 2 300 000. Answer: <b>980 000 < 2 030 000 < 2 299 999 < 2 300 000</b>.') },
      { q: L('Qaysi sonlar minglargacha yaxlitlanganda 6 000 bo‘ladi?', 'Какие числа при округлении до тысяч дают 6 000?', 'Which numbers round to 6 000 when rounded to thousands?'), s: L('Eng kichigi 5 500 (yuzlar xonasida 5 → yuqoriga). Eng kattasi 6 499 (yuzlar xonasida 4 → pastga). Demak, <b>5 500 dan 6 499 gacha</b> bo‘lgan barcha sonlar — jami 1 000 ta son.', 'Наименьшее — 5 500 (в разряде сотен 5 → вверх). Наибольшее — 6 499 (в сотнях 4 → вниз). Значит, все числа <b>от 5 500 до 6 499</b> — всего 1 000 чисел.', 'The smallest is 5 500 (hundreds digit 5 → up). The largest is 6 499 (hundreds digit 4 → down). So every number <b>from 5 500 to 6 499</b> — 1 000 numbers in all.') }
    ] },
    { kind: 'table', h: L('Bitta son — har xil yaxlitlash', 'Одно число — разные округления', 'One number, different roundings'), p: [
      L('3 486 512 sonini turli xonalargacha yaxlitlaymiz. E’tibor bering: xona qancha katta bo‘lsa, javob shuncha «qo‘polroq», lekin eslab qolish osonroq.', 'Округлим число 3 486 512 до разных разрядов. Обратите внимание: чем старше разряд, тем «грубее» ответ, но его легче запомнить.', 'Let us round 3 486 512 to different places. Notice: the higher the place, the “rougher” the answer, but the easier it is to remember.')
    ], table: { head: [L('Qaysi xonagacha', 'До какого разряда', 'Rounded to'), L('Keyingi raqam', 'Следующая цифра', 'Next digit'), L('Natija', 'Результат', 'Result')], rows: [
      [L('o‘nliklargacha', 'до десятков', 'tens'), '2', '3 486 510'],
      [L('yuzliklargacha', 'до сотен', 'hundreds'), '1', '3 486 500'],
      [L('minglargacha', 'до тысяч', 'thousands'), '5', '3 487 000'],
      [L('o‘n minglargacha', 'до десятков тысяч', 'ten thousands'), '6', '3 490 000'],
      [L('yuz minglargacha', 'до сотен тысяч', 'hundred thousands'), '8', '3 500 000'],
      [L('millionlargacha', 'до миллионов', 'millions'), '4', '3 000 000']
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Noto‘g‘ri raqamga qarash.</b> Yaxlitlashda faqat belgilangan xonadan <i>o‘ngdagi bitta</i> raqamga qaraymiz, eng oxirgi raqamga emas. 3 486 512 ni minglargacha yaxlitlashda 5 ga (yuzlik) qaraymiz, 2 ga emas.', '<b>Смотрят не на ту цифру.</b> При округлении смотрим только на <i>одну</i> цифру правее отмеченного разряда, а не на последнюю. Округляя 3 486 512 до тысяч, смотрим на 5 (сотни), а не на 2.', '<b>Looking at the wrong digit.</b> When rounding, look only at the <i>one</i> digit just right of the marked place, not the last digit. Rounding 3 486 512 to thousands we look at 5 (hundreds), not at 2.'),
      L('<b>Nollarni yozmaslik.</b> 3 486 512 ≈ 3 487 deb yozish xato — son kichrayib ketdi! To‘g‘risi: 3 487 000.', '<b>Не дописывают нули.</b> Запись 3 486 512 ≈ 3 487 ошибочна — число уменьшилось! Правильно: 3 487 000.', '<b>Leaving out zeros.</b> Writing 3 486 512 ≈ 3 487 is wrong — the number has shrunk! Correct: 3 487 000.'),
      L('<b>5 raqamini pastga yaxlitlash.</b> Keyingi raqam 5 bo‘lsa — har doim yuqoriga: 2 500 ≈ 3 000 (minglargacha).', '<b>Округляют 5 вниз.</b> Если следующая цифра 5 — всегда вверх: 2 500 ≈ 3 000 (до тысяч).', '<b>Rounding 5 down.</b> When the next digit is 5, always round up: 2 500 ≈ 3 000 (to thousands).'),
      L('<b>9 ga 1 qo‘shganda o‘tkazishni unutish.</b> 1 997 000 ≈ 2 000 000 (o‘n minglargacha), 1 9100 000 emas.', '<b>Забывают перенос при 9 + 1.</b> 1 997 000 ≈ 2 000 000 (до десятков тысяч), а не 1 9100 000.', '<b>Forgetting the carry at 9 + 1.</b> 1 997 000 ≈ 2 000 000 (to ten thousands), not 1 9100 000.'),
      L('<b>Taqqoslashda uzunlikni e’tiborsiz qoldirish.</b> 999 999 < 1 000 000, garchi birinchi son faqat 9 lardan iborat bo‘lsa ham: xonalar soni muhimroq.', '<b>Не учитывают длину при сравнении.</b> 999 999 < 1 000 000, хотя первое число состоит из одних девяток: число разрядов важнее.', '<b>Ignoring length when comparing.</b> 999 999 < 1 000 000 even though the first is all nines: the number of digits matters more.')
    ] },
    { kind: 'life', h: L('Hayotda taqqoslash va yaxlitlash', 'Сравнение и округление в жизни', 'Comparing and rounding in real life'), p: [
      L('<b>Yangiliklar va statistika.</b> «O‘zbekiston aholisi 37 milliondan oshdi», «Toshkentda 3 milliondan ortiq odam yashaydi» — bu yaxlitlangan sonlar. Aniq son 37 523 184 bo‘lishi mumkin, lekin yangilikda uni eslab qolish qiyin. Yaxlitlash ma’lumotni tushunarli qiladi.', '<b>Новости и статистика.</b> «Население Узбекистана превысило 37 миллионов», «в Ташкенте живёт более 3 миллионов» — это округлённые числа. Точное число может быть 37 523 184, но в новостях его трудно запомнить. Округление делает информацию понятной.', '<b>News and statistics.</b> “Uzbekistan’s population passed 37 million”, “more than 3 million people live in Tashkent” — these are rounded numbers. The exact figure might be 37 523 184, but that is hard to remember in the news. Rounding makes information clear.'),
      L('<b>Xarid va byudjet.</b> Oila bir oyda 4 860 000 so‘m sarflasa, «taxminan 5 million» deb rejalashtirish qulay. Do‘konlarda narxlar ko‘pincha 1 990 000 so‘m deb yoziladi — xaridor uni «2 milliondan kam» deb his qiladi, aslida farq atigi 10 ming!', '<b>Покупки и бюджет.</b> Если семья тратит в месяц 4 860 000 сумов, удобно планировать «примерно 5 миллионов». В магазинах цены часто пишут как 1 990 000 сумов — покупателю кажется, что это «меньше 2 миллионов», хотя разница всего 10 тысяч!', '<b>Shopping and budgets.</b> If a family spends 4 860 000 sum a month, it is handy to plan for “about 5 million”. Shops often price things at 1 990 000 sum — the buyer feels it is “under 2 million”, though the difference is only 10 thousand!'),
      L('<b>Geografiya va sport.</b> Orol dengizi 1960-yilda 68 000 km² edi — buni 70 000 deb yaxlitlab eslash oson. Stadionga 36 000 tomoshabin sig‘sa, 35 800 kishi kelganda «stadion to‘ldi» deyishadi. Taqqoslash esa reytinglarda kerak: 2 450 000 ovoz 2 405 000 dan ko‘p — ikkinchi raqamni solishtiring!', '<b>География и спорт.</b> Аральское море в 1960 году имело площадь 68 000 км² — легко запомнить, округлив до 70 000. Если стадион вмещает 36 000 зрителей, при 35 800 пришедших говорят «стадион полон». А сравнение нужно в рейтингах: 2 450 000 голосов больше, чем 2 405 000 — сравните вторые цифры!', '<b>Geography and sport.</b> The Aral Sea covered 68 000 km² in 1960 — easy to remember as 70 000. If a stadium holds 36 000 and 35 800 come, people say “the stadium is full”. Comparing is needed in rankings: 2 450 000 votes is more than 2 405 000 — compare the second digits!')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Yerdan Oygacha o‘rtacha masofa 384 400 km. Yaxlitlab aytganda — 400 000 km, ya’ni Yer ekvatori aylanasining 10 barobari.', 'Среднее расстояние от Земли до Луны — 384 400 км. Округлённо — 400 000 км, то есть в 10 раз больше длины экватора Земли.', 'The average distance from the Earth to the Moon is 384 400 km. Rounded, that is 400 000 km — ten times the length of the Earth’s equator.'),
      L('Inson yuragi bir kunda taxminan 100 000 marta uradi, bir yilda — 36 milliondan ortiq.', 'Сердце человека бьётся около 100 000 раз в день, а за год — более 36 миллионов раз.', 'A human heart beats about 100 000 times a day and more than 36 million times a year.'),
      L('10 million — bu 1 dan keyin yettita nol. Agar 10 million soniyani sanasak, 115 kundan ko‘proq vaqt ketadi.', '10 миллионов — это единица с семью нулями. Если считать 10 миллионов секунд, уйдёт больше 115 дней.', 'Ten million is 1 followed by seven zeros. Counting 10 million seconds would take more than 115 days.'),
      L('O‘zbekistonning maydoni 448 978 km². Yuz minglargacha yaxlitlasak — 400 000 km², o‘n minglargacha — 450 000 km². Ikkinchisi aniqroq!', 'Площадь Узбекистана — 448 978 км². Округлим до сотен тысяч — 400 000 км², до десятков тысяч — 450 000 км². Второе точнее!', 'Uzbekistan’s area is 448 978 km². Rounded to hundred thousands it is 400 000 km², to ten thousands 450 000 km². The second is more accurate!'),
      L('Yaxlitlashning «5 — yuqoriga» qoidasi hisoblashda xatoni iloji boricha kamaytirish uchun tanlangan: ikkala tomonga bir xil uzoqlikdagi son yuqoriga yaxlitlanadi.', 'Правило «5 — вверх» выбрано, чтобы ошибка округления была как можно меньше: число, равноудалённое от соседей, округляют вверх.', 'The “5 rounds up” rule was chosen to keep the rounding error as small as possible: a number exactly halfway is sent up.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('1 234 567 sonini uchta usulda yaxlitlang: minglargacha, yuz minglargacha, millionlargacha.', 'Округлите 1 234 567 тремя способами: до тысяч, до сотен тысяч, до миллионов.', 'Round 1 234 567 three ways: to thousands, to hundred thousands, to millions.'),
      L('★ o‘rniga qanday raqam qo‘yilsa, 6 ★50 000 ≈ 7 000 000 (millionlargacha) bo‘ladi?', 'Какую цифру поставить вместо ★, чтобы 6 ★50 000 ≈ 7 000 000 (до миллионов)?', 'What digit replaces ★ so that 6 ★50 000 ≈ 7 000 000 (to millions)?'),
      L('Yetti xonali sonlar orasida eng kichigi va eng kattasi qaysi? Ular orasida nechta son bor?', 'Какое наименьшее и наибольшее семизначные числа? Сколько чисел между ними?', 'What are the smallest and largest seven-digit numbers? How many numbers lie between them?'),
      L('Ikki son o‘n minglargacha yaxlitlanganda ikkalasi ham 1 230 000 bo‘ldi. Ular orasidagi farq eng ko‘pi bilan qancha bo‘lishi mumkin?', 'Два числа при округлении до десятков тысяч дали 1 230 000. Какой наибольшей может быть разность между ними?', 'Two numbers both round to 1 230 000 when rounded to ten thousands. What is the greatest possible difference between them?')
    ], after: [
      L('Javoblar: 1 235 000; 1 200 000; 1 000 000. ★ = 5, 6, 7, 8 yoki 9. Eng kichigi 1 000 000, eng kattasi 9 999 999, ular orasida 8 999 998 ta son. Eng katta farq 9 999 (1 225 000 va 1 234 999).', 'Ответы: 1 235 000; 1 200 000; 1 000 000. ★ = 5, 6, 7, 8 или 9. Наименьшее 1 000 000, наибольшее 9 999 999, между ними 8 999 998 чисел. Наибольшая разность 9 999 (1 225 000 и 1 234 999).', 'Answers: 1 235 000; 1 200 000; 1 000 000. ★ = 5, 6, 7, 8 or 9. Smallest 1 000 000, largest 9 999 999, with 8 999 998 numbers between them. Greatest difference 9 999 (1 225 000 and 1 234 999).')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Millionlar sinfi — chapdan uchinchi sinf; 10 milliongacha sonlar yetti xonali.', 'Класс миллионов — третий класс слева; числа до 10 миллионов — семизначные.', 'The millions period is the third from the left; numbers below 10 million have seven digits.'),
      L('Taqqoslash: avval xonalar soni, so‘ng chapdan birinchi farq qiladigan raqam.', 'Сравнение: сначала число разрядов, потом первая различающаяся цифра слева.', 'Comparing: first the number of digits, then the first differing digit from the left.'),
      L('Yaxlitlash: belgilangan xonadan keyingi raqam 0–4 bo‘lsa — o‘zgarmaydi, 5–9 bo‘lsa — 1 qo‘shiladi.', 'Округление: если следующая цифра 0–4 — разряд не меняется, 5–9 — прибавляем 1.', 'Rounding: next digit 0–4 keeps the place, 5–9 adds 1 to it.'),
      L('Belgilangan xonadan o‘ngdagi barcha raqamlar nolga aylanadi; ≈ belgisi ishlatiladi.', 'Все цифры правее отмеченного разряда становятся нулями; используется знак ≈.', 'All digits right of the marked place become zeros; the sign ≈ is used.'),
      L('9 + 1 = 10 bo‘lsa, birlik chap xonaga o‘tadi: 4 975 300 ≈ 5 000 000.', 'Если 9 + 1 = 10, единица переходит в левый разряд: 4 975 300 ≈ 5 000 000.', 'If 9 + 1 = 10, the 1 carries to the left: 4 975 300 ≈ 5 000 000.'),
      L('Yaxlit sonlar eslab qolish va taqqoslash uchun qulay, aniq sonlar esa hisob-kitob uchun kerak.', 'Круглые числа удобны для запоминания и сравнения, точные — для расчётов.', 'Round numbers are handy for remembering and comparing; exact numbers are needed for calculations.')
    ] }
  ] });
})(this);
(function (root) { 'use strict'; var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '5-1';

  // ---------- t3. 10, 100, 1000 ga ko'paytirish va bo'lish ----------
  T.add(P, 't3', { sections: [
    { kind: 'intro', h: L('Eng tez hisoblash', 'Самый быстрый счёт', 'The fastest calculation'), p: [
      L('Bitta daftar 3 750 so‘m tursa, 10 ta daftar qancha turadi? Ustun usulida ko‘paytirish shart emas — javob bir soniyada tayyor: 37 500 so‘m. Buning siri juda oddiy: 10 ga ko‘paytirganda sonning oxiriga bitta nol yoziladi. Bu mavzuda shu «sehrli» usul nima uchun ishlashini tushunib olamiz.', 'Если одна тетрадь стоит 3 750 сумов, сколько стоят 10 тетрадей? Умножать столбиком не нужно — ответ готов за секунду: 37 500 сумов. Секрет очень прост: при умножении на 10 к числу справа приписывают один нуль. В этой теме мы поймём, почему этот «волшебный» приём работает.', 'If a notebook costs 3 750 sum, how much do 10 notebooks cost? No need for long multiplication — the answer is ready in a second: 37 500 sum. The secret is simple: multiplying by 10 adds one zero to the end. In this topic we find out why this “magic” trick works.'),
      L('10, 100, 1000 — bu <b>xona birliklari</b>. Ularga ko‘paytirish va bo‘lish o‘nlik sanoq sistemasining eng qulay xossasidir. Sotuvchi, muhandis, bankir — hammasi bu usuldan har kuni foydalanadi: metrni santimetrga, kilogrammni grammga, so‘mni minglarga aylantirishda.', '10, 100, 1000 — это <b>разрядные единицы</b>. Умножение и деление на них — самое удобное свойство десятичной системы. Продавец, инженер, банкир — все пользуются этим приёмом каждый день: переводя метры в сантиметры, килограммы в граммы, сумы в тысячи.', '10, 100 and 1000 are <b>place-value units</b>. Multiplying and dividing by them is the handiest property of the decimal system. Sellers, engineers and bankers use it every day: converting metres to centimetres, kilograms to grams, sum to thousands.'),
      L('Mavzu oxirida siz katta sonlarni yozuv bilan emas, xayolda hisoblay olasiz va natijani tekshirishning oson yo‘lini bilib olasiz.', 'К концу темы вы сможете считать с большими числами в уме, без записи, и узнаете простой способ проверить результат.', 'By the end of the topic you will be able to work with big numbers in your head and you will know an easy way to check the result.')
    ] },
    { kind: 'def', h: L('Xona birliklari va siljish', 'Разрядные единицы и сдвиг', 'Place-value units and shifting'), p: [
      L('<b>Xona birligi</b> — 1, 10, 100, 1000, 10 000 … kabi sonlar. Har biri oldingisidan 10 marta katta. 10 = 10, 100 = 10 · 10, 1000 = 10 · 10 · 10. Nollar soni nechta o‘nlikni ko‘paytirganimizni ko‘rsatadi.', '<b>Разрядная единица</b> — числа 1, 10, 100, 1000, 10 000 … Каждое в 10 раз больше предыдущего. 10 = 10, 100 = 10 · 10, 1000 = 10 · 10 · 10. Число нулей показывает, сколько десяток перемножено.', 'A <b>place-value unit</b> is one of 1, 10, 100, 1000, 10 000 … Each is 10 times the one before. 10 = 10, 100 = 10 · 10, 1000 = 10 · 10 · 10. The number of zeros tells how many tens were multiplied.'),
      L('Sonni 10 ga ko‘paytirsak, har bir birlik o‘nlikka, har bir o‘nlik yuzlikka, har bir yuzlik minglikka aylanadi. Ya’ni har bir raqam bir xona <b>chapga siljiydi</b>, bo‘shab qolgan birliklar xonasiga esa 0 yoziladi. 375 = 3 yuzlik 7 o‘nlik 5 birlik; 375 · 10 = 3 minglik 7 yuzlik 5 o‘nlik = 3 750.', 'Если число умножить на 10, каждая единица становится десятком, каждый десяток — сотней, каждая сотня — тысячей. То есть каждая цифра <b>сдвигается на разряд влево</b>, а в освободившийся разряд единиц пишется 0. 375 = 3 сотни 7 десятков 5 единиц; 375 · 10 = 3 тысячи 7 сотен 5 десятков = 3 750.', 'Multiplying by 10 turns every one into a ten, every ten into a hundred, every hundred into a thousand. So each digit <b>shifts one place left</b>, and 0 fills the empty ones place. 375 = 3 hundreds 7 tens 5 ones; 375 · 10 = 3 thousands 7 hundreds 5 tens = 3 750.'),
      L('Bo‘lish esa teskari amal: 10 ga bo‘lganda har bir raqam bir xona <b>o‘ngga siljiydi</b>. Agar son nol bilan tugasa, bu nol «chiqib ketadi»: 4 800 : 10 = 480. Agar son nol bilan tugamasa, natural sonlarda bo‘linma qoldiqli bo‘ladi: 487 : 10 = 48 (qoldiq 7).', 'Деление — обратное действие: при делении на 10 каждая цифра <b>сдвигается на разряд вправо</b>. Если число оканчивается нулём, этот нуль «уходит»: 4 800 : 10 = 480. Если нуля на конце нет, в натуральных числах получится деление с остатком: 487 : 10 = 48 (ост. 7).', 'Division is the reverse: dividing by 10 shifts each digit <b>one place right</b>. If the number ends in zero, that zero “drops off”: 4 800 : 10 = 480. If it does not end in zero, with whole numbers we get a remainder: 487 : 10 = 48 (rem. 7).')
    ] },
    { kind: 'history', h: L('Nima uchun aynan 10?', 'Почему именно 10?', 'Why exactly 10?'), p: [
      L('Odamlarning qo‘lida 10 ta barmoq bor — shuning uchun deyarli barcha xalqlar o‘ntalab sanashni boshlagan. Qadimgi Misrda 10, 100, 1000 uchun alohida belgilar bo‘lgan: 1000 — nilufar guli, 10 000 — barmoq, 100 000 — qurbaqa, 1 000 000 — qo‘llarini ko‘targan odam (hayratlangan!) shaklida chizilgan.', 'У людей 10 пальцев на руках — поэтому почти все народы начали считать десятками. В Древнем Египте были отдельные знаки для 10, 100, 1000: 1000 изображали цветком лотоса, 10 000 — пальцем, 100 000 — лягушкой, 1 000 000 — человеком с поднятыми руками (от удивления!).', 'People have 10 fingers, which is why almost every nation began counting in tens. Ancient Egypt had separate signs for 10, 100 and 1000: 1000 was drawn as a lotus flower, 10 000 as a finger, 100 000 as a frog, and 1 000 000 as a man with raised arms (in amazement!).'),
      L('Lekin misrliklarda 10 ga ko‘paytirish oson emas edi — har bir belgini boshqasiga almashtirish kerak bo‘lardi. Hind raqamlari va nol paydo bo‘lgach, 10 ga ko‘paytirish shunchaki nol qo‘shishga aylandi. Bu usulni <b>al-Xorazmiy</b> o‘z kitobida tushuntirib bergan va u butun dunyoga tarqalgan.', 'Но египтянам умножать на 10 было непросто — каждый знак приходилось заменять другим. Когда появились индийские цифры и нуль, умножение на 10 превратилось в простое приписывание нуля. Этот приём объяснил в своей книге <b>аль-Хорезми</b>, и он распространился по всему миру.', 'But for the Egyptians multiplying by 10 was not easy — each sign had to be swapped for another. Once Indian digits and zero appeared, multiplying by 10 became simply adding a zero. <b>Al-Khwarizmi</b> explained this method in his book and it spread across the world.'),
      L('1795-yilda Fransiyada <b>metrik tizim</b> qabul qilindi: 1 m = 100 cm, 1 km = 1000 m, 1 kg = 1000 g. Uning g‘oyasi aynan shu mavzuga asoslangan — birliklar 10, 100, 1000 marta farq qilsa, ularni aylantirish juda oson. Bugun dunyoning deyarli barcha mamlakatlari, jumladan O‘zbekiston ham, metrik tizimdan foydalanadi.', 'В 1795 году во Франции приняли <b>метрическую систему</b>: 1 м = 100 см, 1 км = 1000 м, 1 кг = 1000 г. Её идея основана именно на этой теме — если единицы отличаются в 10, 100, 1000 раз, переводить их очень легко. Сегодня метрической системой пользуются почти все страны мира, в том числе Узбекистан.', 'In 1795 France adopted the <b>metric system</b>: 1 m = 100 cm, 1 km = 1000 m, 1 kg = 1000 g. Its idea rests on exactly this topic — if units differ by 10, 100 or 1000 times, converting them is very easy. Today almost every country in the world, including Uzbekistan, uses the metric system.')
    ] },
    { kind: 'rule', h: L('Qoidalar', 'Правила', 'The rules'), p: [
      L('<b>Ko‘paytirish.</b> Natural sonni 10, 100, 1000 ga ko‘paytirish uchun uning o‘ng tomoniga mos ravishda bitta, ikkita, uchta nol yoziladi: 375 · 10 = 3 750; 375 · 100 = 37 500; 375 · 1000 = 375 000.', '<b>Умножение.</b> Чтобы умножить натуральное число на 10, 100, 1000, нужно приписать к нему справа соответственно один, два, три нуля: 375 · 10 = 3 750; 375 · 100 = 37 500; 375 · 1000 = 375 000.', '<b>Multiplying.</b> To multiply a whole number by 10, 100 or 1000, write one, two or three zeros on its right: 375 · 10 = 3 750; 375 · 100 = 37 500; 375 · 1000 = 375 000.'),
      L('<b>Bo‘lish.</b> Oxiri nollar bilan tugaydigan sonni 10, 100, 1000 ga bo‘lish uchun uning oxiridan mos ravishda bitta, ikkita, uchta nol olib tashlanadi: 48 000 : 10 = 4 800; 48 000 : 100 = 480; 48 000 : 1000 = 48.', '<b>Деление.</b> Чтобы разделить число, оканчивающееся нулями, на 10, 100, 1000, нужно отбросить у него справа соответственно один, два, три нуля: 48 000 : 10 = 4 800; 48 000 : 100 = 480; 48 000 : 1000 = 48.', '<b>Dividing.</b> To divide a number ending in zeros by 10, 100 or 1000, remove one, two or three zeros from its end: 48 000 : 10 = 4 800; 48 000 : 100 = 480; 48 000 : 1000 = 48.'),
      L('<b>Nima uchun?</b> 100 = 10 · 10, demak 100 ga ko‘paytirish — ikki marta 10 ga ko‘paytirish, ya’ni ikki marta chapga siljish. Nechta nol — shuncha siljish. Bo‘lish ko‘paytirishni «bekor qiladi»: (48 · 1000) : 1000 = 48.', '<b>Почему?</b> 100 = 10 · 10, значит умножить на 100 — это дважды умножить на 10, то есть дважды сдвинуть влево. Сколько нулей — столько сдвигов. Деление «отменяет» умножение: (48 · 1000) : 1000 = 48.', '<b>Why?</b> 100 = 10 · 10, so multiplying by 100 is multiplying by 10 twice — two shifts to the left. As many zeros, as many shifts. Division “undoes” multiplication: (48 · 1000) : 1000 = 48.')
    ] },
    { kind: 'steps', h: L('Qanday hisoblaymiz', 'Как считаем', 'How to calculate'), list: [
      L('<b>1-qadam.</b> Ko‘paytuvchi (yoki bo‘luvchi) da nechta nol borligini sanang: 1000 → 3 ta nol.', '<b>Шаг 1.</b> Посчитайте, сколько нулей в множителе (или делителе): 1000 → 3 нуля.', '<b>Step 1.</b> Count the zeros in the multiplier (or divisor): 1000 → 3 zeros.'),
      L('<b>2-qadam (ko‘paytirish).</b> Sonning o‘ng tomoniga shuncha nol yozing: 207 · 1000 → 207 000.', '<b>Шаг 2 (умножение).</b> Припишите справа столько же нулей: 207 · 1000 → 207 000.', '<b>Step 2 (multiplying).</b> Write that many zeros on the right: 207 · 1000 → 207 000.'),
      L('<b>2-qadam (bo‘lish).</b> Bo‘linuvchining oxirida yetarli nol borligini tekshiring va shuncha nolni olib tashlang: 207 000 : 1000 → 207.', '<b>Шаг 2 (деление).</b> Проверьте, что у делимого на конце достаточно нулей, и отбросьте столько же: 207 000 : 1000 → 207.', '<b>Step 2 (dividing).</b> Check the dividend ends in enough zeros and remove that many: 207 000 : 1000 → 207.'),
      L('<b>3-qadam.</b> Sonni sinflarga ajratib yozing va o‘qing: 207 000 — «ikki yuz yetti ming».', '<b>Шаг 3.</b> Запишите число по классам и прочитайте: 207 000 — «двести семь тысяч».', '<b>Step 3.</b> Write the number in periods and read it: 207 000 — “two hundred and seven thousand”.'),
      L('<b>4-qadam — tekshiruv.</b> Teskari amalni bajaring: 207 000 : 1000 = 207 ✓. Yoki taqriban baholang: 207 ni mingga ko‘paytirsak, javob yuz mingdan ko‘p bo‘lishi kerak.', '<b>Шаг 4 — проверка.</b> Выполните обратное действие: 207 000 : 1000 = 207 ✓. Или оцените: если 207 умножить на тысячу, ответ должен быть больше ста тысяч.', '<b>Step 4 — check.</b> Do the inverse: 207 000 : 1000 = 207 ✓. Or estimate: 207 times a thousand must be over a hundred thousand.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Hisoblang: 4 060 · 100.', 'Вычислите: 4 060 · 100.', 'Calculate 4 060 · 100.'), s: L('100 da ikkita nol bor. 4 060 ning o‘ng tomoniga ikkita nol yozamiz: <b>406 000</b>. Sonning ichidagi nol (4 060) o‘z joyida qoladi — u ham chapga siljiydi.', 'В 100 два нуля. Приписываем к 4 060 справа два нуля: <b>406 000</b>. Нуль внутри числа (4 060) остаётся на месте — он тоже сдвигается влево.', '100 has two zeros. Write two zeros after 4 060: <b>406 000</b>. The zero inside 4 060 stays — it shifts left along with everything else.') },
      { q: L('Hisoblang: 930 000 : 1000.', 'Вычислите: 930 000 : 1000.', 'Calculate 930 000 : 1000.'), s: L('1000 da uchta nol. 930 000 ning oxiridan uchta nolni olib tashlaymiz: <b>930</b>. Tekshiruv: 930 · 1000 = 930 000 ✓. E’tibor bering: 930 dagi nol olib tashlanmaydi — biz faqat 3 ta nolni olamiz.', 'В 1000 три нуля. Отбрасываем у 930 000 три нуля справа: <b>930</b>. Проверка: 930 · 1000 = 930 000 ✓. Заметьте: нуль в 930 не отбрасываем — убираем только 3 нуля.', '1000 has three zeros. Remove three zeros from the end of 930 000: <b>930</b>. Check: 930 · 1000 = 930 000 ✓. Note: the zero in 930 stays — we remove only 3 zeros.') },
      { q: L('5 m necha santimetr? 45 000 g necha kilogramm?', 'Сколько сантиметров в 5 м? Сколько килограммов в 45 000 г?', 'How many centimetres in 5 m? How many kilograms in 45 000 g?'), s: L('1 m = 100 cm, demak 5 m = 5 · 100 = <b>500 cm</b>. 1 kg = 1000 g, demak 45 000 g = 45 000 : 1000 = <b>45 kg</b>. Kichik birlikdan kattasiga o‘tganda bo‘lamiz, kattasidan kichigiga o‘tganda ko‘paytiramiz.', '1 м = 100 см, значит 5 м = 5 · 100 = <b>500 см</b>. 1 кг = 1000 г, значит 45 000 г = 45 000 : 1000 = <b>45 кг</b>. Переходя от мелкой единицы к крупной, делим; от крупной к мелкой — умножаем.', '1 m = 100 cm, so 5 m = 5 · 100 = <b>500 cm</b>. 1 kg = 1000 g, so 45 000 g = 45 000 : 1000 = <b>45 kg</b>. Going from a small unit to a big one we divide; from big to small we multiply.') },
      { q: L('Bitta qalam 2 500 so‘m. 100 ta qalam qancha turadi? 1000 tasi-chi?', 'Карандаш стоит 2 500 сумов. Сколько стоят 100 карандашей? А 1000?', 'A pencil costs 2 500 sum. How much are 100 pencils? And 1000?'), s: L('2 500 · 100 = <b>250 000 so‘m</b>. 2 500 · 1000 = <b>2 500 000 so‘m</b> — ikki yarim million. Bunday hisob maktab uchun ulgurji xarid qilishda kerak bo‘ladi.', '2 500 · 100 = <b>250 000 сумов</b>. 2 500 · 1000 = <b>2 500 000 сумов</b> — два с половиной миллиона. Такой расчёт нужен при оптовой закупке для школы.', '2 500 · 100 = <b>250 000 sum</b>. 2 500 · 1000 = <b>2 500 000 sum</b> — two and a half million. This kind of sum is needed when buying in bulk for a school.') }
    ] },
    { kind: 'table', h: L('O‘lchov birliklari va 10, 100, 1000', 'Единицы измерения и 10, 100, 1000', 'Units of measure and 10, 100, 1000'), p: [
      L('Metrik tizimdagi birliklar bir-biridan 10, 100 yoki 1000 marta farq qiladi. Shuning uchun aylantirishda shu mavzu qoidalari ishlaydi.', 'Единицы метрической системы отличаются друг от друга в 10, 100 или 1000 раз. Поэтому при переводе работают правила этой темы.', 'Metric units differ from each other by 10, 100 or 1000 times. So the rules of this topic work for converting them.')
    ], table: { head: [L('Katta birlik', 'Крупная единица', 'Big unit'), L('Kichik birlikda', 'В мелких единицах', 'In small units'), L('Misol', 'Пример', 'Example')], rows: [
      ['1 cm', '10 mm', '7 cm = 70 mm'],
      ['1 m', '100 cm', '12 m = 1 200 cm'],
      ['1 km', '1 000 m', '35 km = 35 000 m'],
      ['1 kg', '1 000 g', '8 kg = 8 000 g'],
      [L('1 t', '1 т', '1 t'), L('1 000 kg', '1 000 кг', '1 000 kg'), L('6 t = 6 000 kg', '6 т = 6 000 кг', '6 t = 6 000 kg')],
      [L('1 l', '1 л', '1 l'), L('1 000 ml', '1 000 мл', '1 000 ml'), L('2 l = 2 000 ml', '2 л = 2 000 мл', '2 l = 2 000 ml')],
      [L('1 sr (sentner)', '1 ц (центнер)', '1 quintal'), L('100 kg', '100 кг', '100 kg'), L('4 sr = 400 kg', '4 ц = 400 кг', '4 q = 400 kg')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Nollar sonini adashtirish.</b> 56 · 1000 = 56 000, 5 600 emas. Avval ko‘paytuvchidagi nollarni sanang.', '<b>Путают число нулей.</b> 56 · 1000 = 56 000, а не 5 600. Сначала посчитайте нули в множителе.', '<b>Miscounting zeros.</b> 56 · 1000 = 56 000, not 5 600. Count the zeros in the multiplier first.'),
      L('<b>Ichki nolni olib tashlash.</b> 7 050 : 10 = 705, lekin 7 050 : 100 = 70 (qoldiq 50), 75 emas! Faqat oxiridagi nollarni olib tashlash mumkin.', '<b>Отбрасывают внутренний нуль.</b> 7 050 : 10 = 705, но 7 050 : 100 = 70 (ост. 50), а не 75! Отбрасывать можно только нули на конце.', '<b>Removing an inner zero.</b> 7 050 : 10 = 705, but 7 050 : 100 = 70 (rem. 50), not 75! Only trailing zeros may be removed.'),
      L('<b>Birliklarda adashish.</b> 3 km = 3 000 m (1000 ga ko‘paytiramiz), 300 m emas. Har bir birlik uchun jadvalni eslang.', '<b>Путаница в единицах.</b> 3 км = 3 000 м (умножаем на 1000), а не 300 м. Помните таблицу для каждой единицы.', '<b>Mixing up units.</b> 3 km = 3 000 m (multiply by 1000), not 300 m. Remember the table for each unit.'),
      L('<b>Amalni adashtirish.</b> Grammni kilogrammga o‘tkazganda ko‘paytirish emas, bo‘lish kerak: kilogramm kattaroq birlik, demak son kichrayadi.', '<b>Путают действие.</b> Переводя граммы в килограммы, нужно делить, а не умножать: килограмм — более крупная единица, значит число уменьшается.', '<b>Choosing the wrong operation.</b> Converting grams to kilograms means dividing, not multiplying: a kilogram is a bigger unit, so the number gets smaller.'),
      L('<b>Sinflarni noto‘g‘ri ajratish.</b> 4 060 · 100 natijasini 40 6000 deb yozmang. Natijani yana o‘ngdan uchtadan ajrating: 406 000.', '<b>Неверное разбиение на классы.</b> Не пишите результат 4 060 · 100 как 40 6000. Снова разбейте справа по три: 406 000.', '<b>Wrong grouping.</b> Don’t write 4 060 · 100 as 40 6000. Regroup in threes from the right: 406 000.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Uses in everyday life'), p: [
      L('<b>Bozorda.</b> Bir kilogramm olma 12 000 so‘m. Ulgurji savdogar 100 kg olsa, 12 000 · 100 = 1 200 000 so‘m to‘laydi. Yaxlit miqdorlar bilan hisoblash vaqtni tejaydi va xatoni kamaytiradi.', '<b>На базаре.</b> Килограмм яблок стоит 12 000 сумов. Оптовик берёт 100 кг и платит 12 000 · 100 = 1 200 000 сумов. Счёт с круглыми количествами экономит время и уменьшает ошибки.', '<b>At the market.</b> A kilogram of apples costs 12 000 sum. A wholesaler buying 100 kg pays 12 000 · 100 = 1 200 000 sum. Working with round quantities saves time and reduces errors.'),
      L('<b>Xaritada.</b> Xaritadagi 1 cm haqiqatda 1 000 m (1 km) ga teng bo‘lsa, xaritadagi 25 cm yo‘l 25 000 m = 25 km bo‘ladi. Masshtab — 10, 100, 1000 ga ko‘paytirishning amaliy qo‘llanishi.', '<b>На карте.</b> Если 1 см на карте соответствует 1 000 м (1 км) на местности, то дорога 25 см на карте — это 25 000 м = 25 км. Масштаб — практическое применение умножения на 10, 100, 1000.', '<b>On a map.</b> If 1 cm on a map stands for 1 000 m (1 km), a 25 cm road on the map is 25 000 m = 25 km. Scale is a practical use of multiplying by 10, 100 and 1000.'),
      L('<b>Oshxonada va qurilishda.</b> Retseptda 2 kg un yozilgan, tarozida esa faqat grammlar: 2 · 1000 = 2 000 g. Quruvchi 45 m sim kerakligini biladi, do‘konda esa santimetrlarda sotiladi: 45 · 100 = 4 500 cm. Pul almashtirishda ham: 500 000 so‘mni 1000 so‘mlik pullarda olsangiz, 500 000 : 1000 = 500 ta pul bo‘ladi.', '<b>На кухне и на стройке.</b> В рецепте 2 кг муки, а весы показывают граммы: 2 · 1000 = 2 000 г. Строителю нужно 45 м провода, а в магазине продают в сантиметрах: 45 · 100 = 4 500 см. И при размене денег: 500 000 сумов купюрами по 1000 — это 500 000 : 1000 = 500 купюр.', '<b>In the kitchen and on a building site.</b> A recipe says 2 kg of flour but the scale shows grams: 2 · 1000 = 2 000 g. A builder needs 45 m of wire, but the shop sells by the centimetre: 45 · 100 = 4 500 cm. And for change: 500 000 sum in 1000-sum notes is 500 000 : 1000 = 500 notes.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('1 ga 100 ta nol qo‘shilgan son «gugol» deb ataladi. Mashhur Google kompaniyasi nomi aynan shu so‘zdan olingan.', 'Число, записанное единицей со 100 нулями, называется «гугол». Название компании Google произошло именно от этого слова.', 'The number written as 1 followed by 100 zeros is called a “googol”. The company Google took its name from this word.'),
      L('Toshbaqa 10 marta, chumoli 100 marta, quyosh nuri esa 1000 marta… yo‘q, million marta tezroq! Yorug‘lik bir soniyada taxminan 300 000 km yo‘l bosadi.', 'Черепаха в 10 раз, муравей в 100 раз, а солнечный луч в 1000 раз… нет, в миллионы раз быстрее! Свет за секунду проходит около 300 000 км.', 'A tortoise is 10 times, an ant 100 times, and a sunbeam 1000 times… no, millions of times faster! Light travels about 300 000 km in one second.'),
      L('Kompyuterlarda «kilo» doim ham 1000 emas: 1 kilobayt ba’zan 1024 bayt deb olinadi, chunki kompyuter 10 lik emas, 2 lik sistemada ishlaydi.', 'В компьютерах «кило» не всегда 1000: 1 килобайт иногда считают равным 1024 байтам, потому что компьютер работает в двоичной, а не десятичной системе.', 'In computers “kilo” is not always 1000: 1 kilobyte is sometimes 1024 bytes, because computers work in binary, not decimal.'),
      L('«Kilo» yunoncha «ming», «senti» lotincha «yuz», «milli» lotincha «ming» (mingdan bir) so‘zlaridan olingan.', '«Кило» происходит от греческого «тысяча», «санти» — от латинского «сто», «милли» — от латинского «тысяча» (одна тысячная).', '“Kilo” comes from Greek “thousand”, “centi” from Latin “hundred”, and “milli” from Latin “thousand” (one thousandth).')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('Qaysi songa ko‘paytirsak, 47 dan 47 000 hosil bo‘ladi?', 'На какое число нужно умножить 47, чтобы получить 47 000?', 'What must 47 be multiplied by to give 47 000?'),
      L('Hisoblang: 3 600 : 100 · 1000.', 'Вычислите: 3 600 : 100 · 1000.', 'Calculate 3 600 : 100 · 1000.'),
      L('8 t 50 kg necha kilogramm?', 'Сколько килограммов в 8 т 50 кг?', 'How many kilograms is 8 t 50 kg?'),
      L('Sonni 10 ga ko‘paytirib, so‘ng 100 ga bo‘lsak, 72 chiqdi. Qaysi son edi?', 'Число умножили на 10, затем разделили на 100 и получили 72. Какое было число?', 'A number was multiplied by 10, then divided by 100, giving 72. What was the number?')
    ], after: [
      L('Javoblar: 1000 ga; 3 600 : 100 = 36, 36 · 1000 = 36 000; 8 · 1000 + 50 = 8 050 kg; teskaridan: 72 · 100 = 7 200, 7 200 : 10 = 720.', 'Ответы: на 1000; 3 600 : 100 = 36, 36 · 1000 = 36 000; 8 · 1000 + 50 = 8 050 кг; с конца: 72 · 100 = 7 200, 7 200 : 10 = 720.', 'Answers: by 1000; 3 600 : 100 = 36, 36 · 1000 = 36 000; 8 · 1000 + 50 = 8 050 kg; working back: 72 · 100 = 7 200, 7 200 : 10 = 720.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('10, 100, 1000 — xona birliklari; nollar soni — chapga siljishlar soni.', '10, 100, 1000 — разрядные единицы; число нулей — число сдвигов влево.', '10, 100, 1000 are place-value units; the number of zeros is the number of shifts left.'),
      L('Ko‘paytirishda o‘ng tomonga shuncha nol yoziladi: 375 · 100 = 37 500.', 'При умножении справа приписывают столько же нулей: 375 · 100 = 37 500.', 'To multiply, write that many zeros on the right: 375 · 100 = 37 500.'),
      L('Bo‘lishda oxiridan shuncha nol olib tashlanadi: 48 000 : 100 = 480.', 'При делении справа отбрасывают столько же нулей: 48 000 : 100 = 480.', 'To divide, remove that many zeros from the end: 48 000 : 100 = 480.'),
      L('Faqat oxiridagi nollarni olib tashlash mumkin; ichki nollar o‘z joyida qoladi.', 'Отбрасывать можно только нули на конце; внутренние нули остаются.', 'Only trailing zeros may be removed; inner zeros stay.'),
      L('Metrik birliklarni aylantirish shu qoidalarga asoslanadi: kattadan kichikka — ko‘paytiramiz, kichikdan kattaga — bo‘lamiz.', 'Перевод метрических единиц основан на этих правилах: от крупной к мелкой — умножаем, от мелкой к крупной — делим.', 'Converting metric units rests on these rules: big to small — multiply; small to big — divide.'),
      L('Natijani teskari amal bilan tekshiring.', 'Проверяйте результат обратным действием.', 'Check the result with the inverse operation.')
    ] }
  ] });

  // ---------- t4. O'nlik, yuzlik, mingliklarga ko'paytirish va bo'lish ----------
  T.add(P, 't4', { sections: [
    { kind: 'intro', h: L('Nollar bilan do‘st bo‘lamiz', 'Дружим с нулями', 'Making friends with zeros'), p: [
      L('Maktab oshxonasi har kuni 300 ta bulochka buyurtma qiladi. 34 kunda nechta bulochka kerak? Avvalgi mavzuda 10, 100, 1000 ga ko‘paytirishni o‘rgandik. Endi bir qadam oldinga yuramiz: 300, 4 000, 70 kabi «yaxlit» sonlarga ko‘paytirish va bo‘lishni o‘rganamiz.', 'Школьная столовая каждый день заказывает 300 булочек. Сколько булочек нужно на 34 дня? В прошлой теме мы научились умножать на 10, 100, 1000. Теперь шагнём дальше: научимся умножать и делить на «круглые» числа вроде 300, 4 000, 70.', 'The school canteen orders 300 buns every day. How many buns are needed for 34 days? In the last topic we learned to multiply by 10, 100 and 1000. Now we go one step further: multiplying and dividing by “round” numbers like 300, 4 000 and 70.'),
      L('Bunday sonlar ikki qismdan iborat: oddiy raqam va xona birligi. 300 = 3 · 100. Shu g‘oya tufayli murakkab ko‘rinadigan 34 · 300 ni ikki oson qadamga bo‘lamiz: avval 34 · 3 = 102, so‘ng 102 · 100 = 10 200.', 'Такие числа состоят из двух частей: обычной цифры и разрядной единицы. 300 = 3 · 100. Благодаря этой идее сложное на вид 34 · 300 разбиваем на два простых шага: сначала 34 · 3 = 102, потом 102 · 100 = 10 200.', 'Such numbers have two parts: an ordinary digit and a place-value unit. 300 = 3 · 100. Thanks to this idea, the scary-looking 34 · 300 breaks into two easy steps: first 34 · 3 = 102, then 102 · 100 = 10 200.'),
      L('Bu usul og‘zaki hisoblashning asosi. U bilan siz kalkulyatorsiz ham do‘konda, sayohatda yoki imtihonda tez va to‘g‘ri hisoblaysiz.', 'Этот приём — основа устного счёта. С ним вы будете быстро и правильно считать без калькулятора — в магазине, в поездке или на экзамене.', 'This method is the basis of mental arithmetic. With it you will calculate quickly and correctly without a calculator — in a shop, on a trip or in an exam.')
    ] },
    { kind: 'def', h: L('Yaxlit son va uning qismlari', 'Круглое число и его части', 'A round number and its parts'), p: [
      L('<b>Yaxlit son</b> deb oxiri bir yoki bir nechta nol bilan tugaydigan sonni aytamiz: 20, 300, 4 000, 560, 7 200. Har qanday yaxlit sonni «nolsiz qism» va xona birligi ko‘paytmasi shaklida yozish mumkin: 4 000 = 4 · 1000; 560 = 56 · 10; 7 200 = 72 · 100.', '<b>Круглым числом</b> называем число, оканчивающееся одним или несколькими нулями: 20, 300, 4 000, 560, 7 200. Любое круглое число можно записать как произведение «части без нулей» и разрядной единицы: 4 000 = 4 · 1000; 560 = 56 · 10; 7 200 = 72 · 100.', 'A <b>round number</b> ends in one or more zeros: 20, 300, 4 000, 560, 7 200. Any round number can be written as its “zero-free part” times a place-value unit: 4 000 = 4 · 1000; 560 = 56 · 10; 7 200 = 72 · 100.'),
      L('Bu yozuv ikki muhim xossaga tayanadi. <b>Guruhlash (assotsiativlik) xossasi:</b> ko‘paytuvchilarni istalgan tartibda guruhlash mumkin: (a · b) · c = a · (b · c). <b>O‘rin almashtirish xossasi:</b> a · b = b · a. Shuning uchun 34 · (3 · 100) = (34 · 3) · 100.', 'Эта запись опирается на два важных свойства. <b>Сочетательное свойство:</b> множители можно группировать как угодно: (a · b) · c = a · (b · c). <b>Переместительное свойство:</b> a · b = b · a. Поэтому 34 · (3 · 100) = (34 · 3) · 100.', 'This rests on two important laws. The <b>associative law</b>: factors can be grouped any way: (a · b) · c = a · (b · c). The <b>commutative law</b>: a · b = b · a. So 34 · (3 · 100) = (34 · 3) · 100.'),
      L('Bo‘lishda esa <b>bo‘linmaning xossasi</b> ishlaydi: bo‘linuvchi va bo‘luvchini bir xil songa (nolga emas) bo‘lsak, bo‘linma o‘zgarmaydi. 8 400 : 70 = (8 400 : 10) : (70 : 10) = 840 : 7 = 120.', 'При делении работает <b>свойство частного</b>: если делимое и делитель разделить на одно и то же число (не нуль), частное не изменится. 8 400 : 70 = (8 400 : 10) : (70 : 10) = 840 : 7 = 120.', 'For division the <b>quotient property</b> works: dividing both the dividend and the divisor by the same (non-zero) number does not change the quotient. 8 400 : 70 = (8 400 : 10) : (70 : 10) = 840 : 7 = 120.')
    ] },
    { kind: 'history', h: L('Xayolda hisoblash ustalari', 'Мастера устного счёта', 'Masters of mental arithmetic'), p: [
      L('Qadimgi Bobil va Misrda savdogarlar katta sonlarni ko‘paytirishda sonlarni qismlarga ajratishgan. Misrliklar ko‘paytirishni ikkilantirish orqali bajargan: 34 · 300 ni topish uchun 34 ni qayta-qayta ikki barobar oshirib, kerakli qismlarni qo‘shishgan. Bu uzoq, ammo ishonchli usul edi.', 'В Древнем Вавилоне и Египте торговцы при умножении больших чисел разбивали их на части. Египтяне умножали через удвоение: чтобы найти 34 · 300, они снова и снова удваивали 34 и складывали нужные части. Это был долгий, но надёжный способ.', 'In ancient Babylon and Egypt merchants split big numbers into parts when multiplying. The Egyptians multiplied by doubling: to find 34 · 300 they doubled 34 again and again and added the right pieces. It was slow but reliable.'),
      L('O‘rta asrlarda Samarqand va Buxoro madrasalarida «hisob ilmi» alohida fan sifatida o‘qitilgan. XV asrda <b>Jamshid al-Koshiy</b> — Ulug‘bek rasadxonasining yetakchi olimlaridan biri — «Arifmetika kaliti» nomli kitob yozgan. Unda u yaxlit sonlar bilan tez hisoblash usullarini batafsil tushuntirgan va o‘nli kasrlarni qo‘llagan.', 'В Средние века в медресе Самарканда и Бухары «наука счёта» преподавалась как отдельный предмет. В XV веке <b>Джамшид аль-Каши</b> — один из ведущих учёных обсерватории Улугбека — написал книгу «Ключ арифметики». В ней он подробно объяснил приёмы быстрого счёта с круглыми числами и применял десятичные дроби.', 'In the Middle Ages the “science of reckoning” was taught as a subject in the madrasas of Samarkand and Bukhara. In the 15th century <b>Jamshid al-Kashi</b>, one of the leading scientists at Ulugh Beg’s observatory, wrote “The Key to Arithmetic”. In it he explained in detail how to calculate quickly with round numbers, and he used decimal fractions.'),
      L('Bugun ham og‘zaki hisoblash bo‘yicha xalqaro musobaqalar o‘tkaziladi. G‘oliblar o‘nlab xonali sonlarni bir necha soniyada ko‘paytiradi — va ular ham aynan sonni qismlarga ajratish usulidan foydalanadi.', 'И сегодня проводятся международные соревнования по устному счёту. Победители перемножают многозначные числа за несколько секунд — и тоже пользуются разбиением чисел на части.', 'Today there are still international mental-arithmetic contests. Winners multiply many-digit numbers in seconds — and they too rely on splitting numbers into parts.')
    ] },
    { kind: 'rule', h: L('Qoidalar', 'Правила', 'The rules'), p: [
      L('<b>Yaxlit songa ko‘paytirish.</b> Sonni yaxlit songa ko‘paytirish uchun uni nolsiz qismga ko‘paytiring, so‘ng natijaning o‘ng tomoniga yaxlit sondagi nollarni yozing: 34 · 300 = (34 · 3) · 100 = 102 · 100 = 10 200.', '<b>Умножение на круглое число.</b> Чтобы умножить число на круглое, умножьте его на часть без нулей, а потом припишите к результату справа нули круглого числа: 34 · 300 = (34 · 3) · 100 = 102 · 100 = 10 200.', '<b>Multiplying by a round number.</b> Multiply by the zero-free part, then write the round number’s zeros after the result: 34 · 300 = (34 · 3) · 100 = 102 · 100 = 10 200.'),
      L('<b>Ikkala ko‘paytuvchi ham yaxlit bo‘lsa</b>, nolsiz qismlarni ko‘paytirib, ikkala sondagi barcha nollarni qo‘shamiz: 250 · 40 = (25 · 4) va 1 + 1 = 2 ta nol → 100 · 100 = 10 000. Diqqat: 25 · 4 = 100 ning o‘zida ham nollar bor — ular ham hisobga olinadi!', '<b>Если оба множителя круглые</b>, перемножаем части без нулей и приписываем все нули обоих чисел: 250 · 40 = (25 · 4) и 1 + 1 = 2 нуля → 100 и ещё 00 → 10 000. Внимание: в самом 25 · 4 = 100 тоже есть нули — они учитываются!', '<b>If both factors are round</b>, multiply the zero-free parts and add all the zeros of both: 250 · 40 = (25 · 4) and 1 + 1 = 2 zeros → 100 then 00 → 10 000. Careful: 25 · 4 = 100 already has zeros of its own — they count too!'),
      L('<b>Yaxlit songa bo‘lish.</b> Bo‘linuvchi va bo‘luvchining oxiridan bir xil sondagi nolni olib tashlaymiz, so‘ng odatdagidek bo‘lamiz: 8 400 : 70 = 840 : 7 = 120; 36 000 : 400 = 360 : 4 = 90.', '<b>Деление на круглое число.</b> Отбрасываем у делимого и делителя одинаковое число нулей справа, затем делим как обычно: 8 400 : 70 = 840 : 7 = 120; 36 000 : 400 = 360 : 4 = 90.', '<b>Dividing by a round number.</b> Remove the same number of trailing zeros from the dividend and the divisor, then divide as usual: 8 400 : 70 = 840 : 7 = 120; 36 000 : 400 = 360 : 4 = 90.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich', 'Шаг за шагом', 'Step by step'), list: [
      L('<b>1-qadam.</b> Yaxlit sonni ikki qismga ajrating: 6 000 = 6 · 1000.', '<b>Шаг 1.</b> Разложите круглое число на две части: 6 000 = 6 · 1000.', '<b>Step 1.</b> Split the round number into two parts: 6 000 = 6 · 1000.'),
      L('<b>2-qadam.</b> Nolsiz qismlar bilan amalni bajaring: 125 · 6 = 750.', '<b>Шаг 2.</b> Выполните действие с частями без нулей: 125 · 6 = 750.', '<b>Step 2.</b> Work with the zero-free parts: 125 · 6 = 750.'),
      L('<b>3-qadam.</b> Nollarni qaytaring: 750 · 1000 = 750 000. Demak, 125 · 6 000 = 750 000.', '<b>Шаг 3.</b> Верните нули: 750 · 1000 = 750 000. Значит, 125 · 6 000 = 750 000.', '<b>Step 3.</b> Put the zeros back: 750 · 1000 = 750 000. So 125 · 6 000 = 750 000.'),
      L('<b>Bo‘lishda:</b> 1) ikkala sondagi oxirgi nollarni sanang; 2) kichik sonini olib tashlang; 3) qolgan sonlarni bo‘ling. 54 000 : 900 → 540 : 9 = 60.', '<b>При делении:</b> 1) посчитайте нули на конце обоих чисел; 2) отбросьте меньшее их количество у обоих; 3) разделите оставшиеся числа. 54 000 : 900 → 540 : 9 = 60.', '<b>For division:</b> 1) count the trailing zeros in both numbers; 2) remove the smaller count from both; 3) divide what is left. 54 000 : 900 → 540 : 9 = 60.'),
      L('<b>Tekshiruv:</b> 60 · 900 = 54 · 1000 = 54 000 ✓.', '<b>Проверка:</b> 60 · 900 = 54 · 1000 = 54 000 ✓.', '<b>Check:</b> 60 · 900 = 54 · 1000 = 54 000 ✓.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Hisoblang: 46 · 2 000.', 'Вычислите: 46 · 2 000.', 'Calculate 46 · 2 000.'), s: L('2 000 = 2 · 1000. 46 · 2 = 92. 92 · 1000 = <b>92 000</b>.', '2 000 = 2 · 1000. 46 · 2 = 92. 92 · 1000 = <b>92 000</b>.', '2 000 = 2 · 1000. 46 · 2 = 92. 92 · 1000 = <b>92 000</b>.') },
      { q: L('Hisoblang: 1 500 · 60.', 'Вычислите: 1 500 · 60.', 'Calculate 1 500 · 60.'), s: L('Nolsiz qismlar: 15 va 6. 15 · 6 = 90. Nollar: 1 500 da ikkita, 60 da bitta — jami uchta. 90 ning o‘ng tomoniga 000 yozamiz: <b>90 000</b>. Tekshiruv: 1 500 · 60 = 1 500 · 6 · 10 = 9 000 · 10 = 90 000 ✓.', 'Части без нулей: 15 и 6. 15 · 6 = 90. Нули: в 1 500 два, в 60 один — всего три. Приписываем к 90 справа 000: <b>90 000</b>. Проверка: 1 500 · 60 = 1 500 · 6 · 10 = 9 000 · 10 = 90 000 ✓.', 'Zero-free parts: 15 and 6. 15 · 6 = 90. Zeros: two in 1 500, one in 60 — three in all. Write 000 after 90: <b>90 000</b>. Check: 1 500 · 60 = 1 500 · 6 · 10 = 9 000 · 10 = 90 000 ✓.') },
      { q: L('Hisoblang: 72 000 : 800.', 'Вычислите: 72 000 : 800.', 'Calculate 72 000 : 800.'), s: L('72 000 da uchta, 800 da ikkita nol. Ikkalasidan ikkitadan nol olib tashlaymiz: 720 : 8 = <b>90</b>. Tekshiruv: 90 · 800 = 72 000 ✓.', 'В 72 000 три нуля, в 800 — два. Отбрасываем у обоих по два нуля: 720 : 8 = <b>90</b>. Проверка: 90 · 800 = 72 000 ✓.', '72 000 has three zeros, 800 has two. Remove two from each: 720 : 8 = <b>90</b>. Check: 90 · 800 = 72 000 ✓.') },
      { q: L('Avtobus 1 soatda 60 km yuradi. 3 000 km yo‘lni necha soatda bosib o‘tadi?', 'Автобус проезжает 60 км за 1 час. За сколько часов он проедет 3 000 км?', 'A bus travels 60 km in 1 hour. How many hours does it need for 3 000 km?'), s: L('3 000 : 60 = 300 : 6 = <b>50 soat</b>. Ya’ni ikki kundan ham ko‘proq — haydovchiga dam olish kerak bo‘ladi!', '3 000 : 60 = 300 : 6 = <b>50 часов</b>. То есть больше двух суток — водителю понадобится отдых!', '3 000 : 60 = 300 : 6 = <b>50 hours</b>. That is more than two days — the driver will need rest!') },
      { q: L('Maktab oshxonasi kuniga 300 ta bulochka oladi. 34 kunda nechta?', 'Школьная столовая берёт 300 булочек в день. Сколько за 34 дня?', 'The canteen takes 300 buns a day. How many in 34 days?'), s: L('34 · 300 = 34 · 3 · 100 = 102 · 100 = <b>10 200 ta</b> bulochka.', '34 · 300 = 34 · 3 · 100 = 102 · 100 = <b>10 200</b> булочек.', '34 · 300 = 34 · 3 · 100 = 102 · 100 = <b>10 200</b> buns.') }
    ] },
    { kind: 'table', h: L('Xayolda hisoblash uchun foydali juftliklar', 'Полезные пары для устного счёта', 'Handy pairs for mental arithmetic'), p: [
      L('Ba’zi juftliklar ko‘paytmasi yaxlit son beradi. Ularni yodlab olsangiz, hisoblash ancha tezlashadi.', 'Произведение некоторых пар даёт круглое число. Если их запомнить, счёт заметно ускорится.', 'Some pairs multiply to a round number. Learn them and your calculations will speed up a lot.')
    ], table: { head: [L('Juftlik', 'Пара', 'Pair'), L('Ko‘paytma', 'Произведение', 'Product'), L('Qo‘llanishi', 'Применение', 'Use')], rows: [
      ['2 · 5', '10', '2 · 37 · 5 = 370'],
      ['4 · 25', '100', '4 · 19 · 25 = 1 900'],
      ['8 · 125', '1 000', '8 · 7 · 125 = 7 000'],
      ['20 · 50', '1 000', '20 · 13 · 50 = 13 000'],
      ['40 · 25', '1 000', '40 · 6 · 25 = 6 000'],
      ['200 · 500', '100 000', '200 · 3 · 500 = 300 000']
    ] }, after: [
      L('Bu usul o‘rin almashtirish va guruhlash xossalariga asoslangan: ko‘paytuvchilarning o‘rnini almashtirib, qulay juftlikni avval ko‘paytiramiz.', 'Приём основан на переместительном и сочетательном свойствах: меняем множители местами и сначала перемножаем удобную пару.', 'This trick rests on the commutative and associative laws: rearrange the factors and multiply the handy pair first.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Nolsiz qism ko‘paytmasidagi nollarni unutish.</b> 50 · 40: 5 · 4 = 20 (bu yerda ham nol bor!), so‘ng yana ikkita nol → 2 000. 200 deb yozish xato.', '<b>Забывают нули в произведении частей.</b> 50 · 40: 5 · 4 = 20 (здесь тоже есть нуль!), потом ещё два нуля → 2 000. Ответ 200 — ошибка.', '<b>Forgetting zeros inside the product.</b> 50 · 40: 5 · 4 = 20 (that has a zero too!), then two more zeros → 2 000. Writing 200 is wrong.'),
      L('<b>Bo‘lishda nollarni teng olib tashlamaslik.</b> 8 400 : 70 da faqat bo‘linuvchidan nol olib tashlansa (840 : 70), javob 12 bo‘lib qoladi — xato! Ikkalasidan bir xil miqdorda olib tashlanadi.', '<b>При делении отбрасывают нули неравно.</b> Если в 8 400 : 70 убрать нуль только у делимого (840 : 70), получится 12 — ошибка! Отбрасывают поровну у обоих.', '<b>Removing zeros unevenly in division.</b> If in 8 400 : 70 the zero is removed only from the dividend (840 : 70), you get 12 — wrong! Remove the same number from both.'),
      L('<b>Bo‘linmadagi nolni yo‘qotish.</b> 4 800 : 6 = 800, 80 emas. Bo‘lgandan keyin bo‘linuvchining ortiqcha nollari javobda qoladi.', '<b>Теряют нуль в частном.</b> 4 800 : 6 = 800, а не 80. Лишние нули делимого после деления остаются в ответе.', '<b>Losing a zero in the quotient.</b> 4 800 : 6 = 800, not 80. Any extra zeros of the dividend remain in the answer.'),
      L('<b>Qo‘shishda shu usulni qo‘llash.</b> 300 + 400 = 700, lekin 3 + 4 = 7 ga 0000 qo‘shish noto‘g‘ri. Nollarni qo‘shish qoidasi faqat ko‘paytirish uchun!', '<b>Применяют приём к сложению.</b> 300 + 400 = 700, а приписывать к 3 + 4 = 7 четыре нуля неверно. Правило сложения нулей — только для умножения!', '<b>Using this trick for addition.</b> 300 + 400 = 700; adding four zeros to 3 + 4 = 7 is wrong. Counting up zeros works only for multiplication!')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Uses in everyday life'), p: [
      L('<b>Sayohat.</b> Toshkentdan Samarqandgacha poyezd «Afrosiyob» taxminan 300 km ni 2 soatda bosib o‘tadi: 300 : 2 = 150 km/soat. 40 marta borib kelgan kishi 2 · 300 · 40 = 24 000 km yo‘l yuradi — Yer ekvatorining qariyb 60 foizi!', '<b>Путешествия.</b> Поезд «Афросиаб» проезжает от Ташкента до Самарканда около 300 км за 2 часа: 300 : 2 = 150 км/ч. Человек, съездивший туда и обратно 40 раз, проедет 2 · 300 · 40 = 24 000 км — почти 60 процентов экватора Земли!', '<b>Travel.</b> The Afrosiyob train covers about 300 km from Tashkent to Samarkand in 2 hours: 300 : 2 = 150 km/h. Someone making the round trip 40 times travels 2 · 300 · 40 = 24 000 km — almost 60 per cent of the Earth’s equator!'),
      L('<b>Maktab va xo‘jalik.</b> Maktabda 1 200 o‘quvchi bor, har biriga 40 varaqli daftar kerak: 1 200 · 40 = 48 000 varaq. Fermer 600 ta daraxtdan har biridan 30 kg olma tersa: 600 · 30 = 18 000 kg = 18 tonna.', '<b>Школа и хозяйство.</b> В школе 1 200 учеников, каждому нужна тетрадь на 40 листов: 1 200 · 40 = 48 000 листов. Фермер собрал с каждого из 600 деревьев по 30 кг яблок: 600 · 30 = 18 000 кг = 18 тонн.', '<b>School and farming.</b> A school has 1 200 pupils, each needing a 40-sheet notebook: 1 200 · 40 = 48 000 sheets. A farmer picks 30 kg of apples from each of 600 trees: 600 · 30 = 18 000 kg = 18 tonnes.'),
      L('<b>Pul.</b> Oyiga 50 000 so‘m tejasangiz, bir yilda 50 000 · 12 = 600 000 so‘m yig‘asiz. 900 000 so‘mlik velosiped uchun 900 000 : 50 000 = 90 : 5 = 18 oy kerak.', '<b>Деньги.</b> Если откладывать 50 000 сумов в месяц, за год накопится 50 000 · 12 = 600 000 сумов. На велосипед за 900 000 сумов понадобится 900 000 : 50 000 = 90 : 5 = 18 месяцев.', '<b>Money.</b> Saving 50 000 sum a month gives 50 000 · 12 = 600 000 sum in a year. A 900 000-sum bicycle needs 900 000 : 50 000 = 90 : 5 = 18 months.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Bir sutkada 24 · 60 = 1 440 daqiqa va 1 440 · 60 = 86 400 soniya bor.', 'В сутках 24 · 60 = 1 440 минут и 1 440 · 60 = 86 400 секунд.', 'A day has 24 · 60 = 1 440 minutes and 1 440 · 60 = 86 400 seconds.'),
      L('Asalari bir qoshiq asal yig‘ish uchun taxminan 4 000 ta gulga qo‘nadi. Bir kilogramm asal uchun esa millionlab gul kerak!', 'Чтобы собрать ложку мёда, пчела садится примерно на 4 000 цветков. А на килограмм мёда нужны миллионы цветов!', 'To make a spoonful of honey, a bee visits about 4 000 flowers. A kilogram of honey takes millions!'),
      L('Rim raqamlari bilan 34 · 300 ni hisoblash juda qiyin: XXXIV · CCC. Hind-arab raqamlari va nol tufayli bu bir qatorda bajariladi.', 'Римскими цифрами вычислить 34 · 300 очень трудно: XXXIV · CCC. Благодаря индийско-арабским цифрам и нулю это делается в одну строку.', 'With Roman numerals 34 · 300 is very hard: XXXIV · CCC. With Hindu-Arabic numerals and zero it takes one line.'),
      L('Inson yuragi bir daqiqada taxminan 70 marta uradi: bir soatda 70 · 60 = 4 200 marta.', 'Сердце человека бьётся примерно 70 раз в минуту: за час это 70 · 60 = 4 200 раз.', 'A human heart beats about 70 times a minute: 70 · 60 = 4 200 times an hour.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('Hisoblang: 25 · 17 · 4.', 'Вычислите: 25 · 17 · 4.', 'Calculate 25 · 17 · 4.'),
      L('Hisoblang: 560 000 : 7 000.', 'Вычислите: 560 000 : 7 000.', 'Calculate 560 000 : 7 000.'),
      L('Qaysi son katta: 400 · 50 yoki 2 000 · 9?', 'Что больше: 400 · 50 или 2 000 · 9?', 'Which is bigger: 400 · 50 or 2 000 · 9?'),
      L('1 200 ta tuxumni 30 tadan qutilarga joylashdi. Nechta quti kerak?', '1 200 яиц разложили в коробки по 30 штук. Сколько нужно коробок?', '1 200 eggs are packed 30 to a box. How many boxes are needed?')
    ], after: [
      L('Javoblar: 25 · 4 = 100, 100 · 17 = 1 700; 560 : 7 = 80; 400 · 50 = 20 000 > 18 000; 1 200 : 30 = 120 : 3 = 40 quti.', 'Ответы: 25 · 4 = 100, 100 · 17 = 1 700; 560 : 7 = 80; 400 · 50 = 20 000 > 18 000; 1 200 : 30 = 120 : 3 = 40 коробок.', 'Answers: 25 · 4 = 100, 100 · 17 = 1 700; 560 : 7 = 80; 400 · 50 = 20 000 > 18 000; 1 200 : 30 = 120 : 3 = 40 boxes.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Yaxlit son = nolsiz qism · xona birligi: 300 = 3 · 100.', 'Круглое число = часть без нулей · разрядная единица: 300 = 3 · 100.', 'Round number = zero-free part · place-value unit: 300 = 3 · 100.'),
      L('Ko‘paytirish: nolsiz qismlarni ko‘paytiring, so‘ng barcha nollarni qo‘shing.', 'Умножение: перемножьте части без нулей, затем припишите все нули.', 'Multiplying: multiply the zero-free parts, then append all the zeros.'),
      L('Bo‘lish: ikkala sondan bir xil sondagi nolni olib tashlang, so‘ng bo‘ling.', 'Деление: отбросьте у обоих чисел одинаковое число нулей, затем делите.', 'Dividing: remove the same number of zeros from both, then divide.'),
      L('Usul guruhlash va o‘rin almashtirish xossalariga hamda bo‘linma xossasiga asoslanadi.', 'Приём основан на сочетательном и переместительном свойствах и свойстве частного.', 'The method rests on the associative and commutative laws and the quotient property.'),
      L('Nolsiz qismlar ko‘paytmasida paydo bo‘lgan nollarni yo‘qotmang: 50 · 40 = 2 000.', 'Не теряйте нули, появившиеся в произведении частей: 50 · 40 = 2 000.', 'Don’t lose zeros that appear in the product of parts: 50 · 40 = 2 000.'),
      L('2 · 5, 4 · 25, 8 · 125 juftliklari xayolda hisoblashni tezlashtiradi.', 'Пары 2 · 5, 4 · 25, 8 · 125 ускоряют устный счёт.', 'The pairs 2 · 5, 4 · 25, 8 · 125 speed up mental arithmetic.')
    ] }
  ] });
})(this);
(function (root) { 'use strict'; var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '5-1';

  // ---------- t5. Amallarni bajarish tartibi ----------
  T.add(P, 't5', { sections: [
    { kind: 'intro', h: L('Bitta misol — ikki xil javob?', 'Один пример — два ответа?', 'One problem, two answers?'), p: [
      L('Ikki do‘st 20 + 80 : 4 ni hisobladi. Aziz: «20 + 80 = 100, 100 : 4 = 25». Malika: «80 : 4 = 20, 20 + 20 = 40». Kim haq? Agar har kim amallarni o‘zi xohlagan tartibda bajarsa, bitta ifoda ikki xil javob beradi — matematikada esa bunday bo‘lmasligi kerak.', 'Двое друзей вычислили 20 + 80 : 4. Азиз: «20 + 80 = 100, 100 : 4 = 25». Малика: «80 : 4 = 20, 20 + 20 = 40». Кто прав? Если каждый выполняет действия в своём порядке, одно выражение даёт два ответа, а в математике так быть не должно.', 'Two friends worked out 20 + 80 : 4. Aziz: “20 + 80 = 100, 100 : 4 = 25”. Malika: “80 : 4 = 20, 20 + 20 = 40”. Who is right? If everyone does the operations in their own order, one expression gives two answers, and in maths that must not happen.'),
      L('Shuning uchun matematiklar barcha uchun yagona <b>amallarni bajarish tartibi</b>ni kelishib olishgan. Unga ko‘ra Malika haq: javob 40. Bu mavzuda shu qoidani, qavslarning rolini va murakkab ifodalarni xatosiz hisoblash usulini o‘rganamiz.', 'Поэтому математики договорились о едином для всех <b>порядке действий</b>. По нему права Малика: ответ 40. В этой теме изучим это правило, роль скобок и способ без ошибок вычислять сложные выражения.', 'So mathematicians agreed on a single <b>order of operations</b> for everyone. By it, Malika is right: the answer is 40. In this topic we learn the rule, the role of brackets and how to work out long expressions without mistakes.'),
      L('Bu qoida kalkulyatorlar va kompyuter dasturlarida ham ishlaydi. Dasturchi uni bilmasa, bank hisobi yoki raketa traektoriyasi xato hisoblanishi mumkin!', 'Это правило действует и в калькуляторах, и в компьютерных программах. Если программист его не знает, банковский счёт или траектория ракеты могут быть посчитаны неверно!', 'This rule also works in calculators and computer programs. A programmer who ignores it could miscalculate a bank balance or a rocket’s path!')
    ] },
    { kind: 'def', h: L('Ifoda va amallar bosqichlari', 'Выражение и ступени действий', 'Expressions and levels of operations'), p: [
      L('<b>Sonli ifoda</b> — sonlar, amal belgilari va qavslardan tuzilgan yozuv: 600 − (120 + 30) · 4. Ifodani hisoblash natijasida hosil bo‘lgan son <b>ifodaning qiymati</b> deyiladi.', '<b>Числовое выражение</b> — запись из чисел, знаков действий и скобок: 600 − (120 + 30) · 4. Число, полученное в результате вычисления, называется <b>значением выражения</b>.', 'A <b>numerical expression</b> is made of numbers, operation signs and brackets: 600 − (120 + 30) · 4. The number you get by working it out is the <b>value of the expression</b>.'),
      L('To‘rt amal ikki <b>bosqich</b>ga bo‘linadi. <b>Birinchi bosqich amallari</b> — qo‘shish va ayirish. <b>Ikkinchi bosqich amallari</b> — ko‘paytirish va bo‘lish. Ikkinchi bosqich «kuchliroq»: u birinchi bosqichdan oldin bajariladi.', 'Четыре действия делятся на две <b>ступени</b>. <b>Действия первой ступени</b> — сложение и вычитание. <b>Действия второй ступени</b> — умножение и деление. Вторая ступень «сильнее»: её выполняют раньше первой.', 'The four operations form two <b>levels</b>. <b>First-level operations</b> are addition and subtraction. <b>Second-level operations</b> are multiplication and division. The second level is “stronger”: it is done before the first.'),
      L('<b>Qavslar</b> — ( ) — tartibni o‘zgartiradigan belgi. Qavs ichidagi ifoda har doim birinchi hisoblanadi, u «bitta son»ga aylanadi. Ba’zan qavs ichida yana qavs bo‘ladi: unda eng ichkisidan boshlaymiz.', '<b>Скобки</b> — ( ) — знак, меняющий порядок. Выражение в скобках всегда вычисляют первым, оно превращается в «одно число». Иногда внутри скобок есть ещё скобки: тогда начинаем с самых внутренних.', '<b>Brackets</b> ( ) change the order. The expression in brackets is always worked out first and turns into “one number”. Sometimes brackets sit inside brackets: then start with the innermost.')
    ] },
    { kind: 'history', h: L('Belgilar va qavslar tarixi', 'История знаков и скобок', 'A history of signs and brackets'), p: [
      L('Qadimda ifodalar so‘z bilan yozilgan: «yigirmaga sakson qo‘shib, to‘rtga bo‘l». <b>Al-Xorazmiy</b> ham o‘z masalalarini so‘zlar bilan bayon qilgan. Bunday yozuvda tartib gapning o‘zidan tushunilardi, lekin uzun hisob-kitoblar juda og‘ir edi.', 'В древности выражения записывали словами: «к двадцати прибавь восемьдесят и раздели на четыре». <b>Аль-Хорезми</b> тоже излагал свои задачи словами. В такой записи порядок понятен из самого предложения, но длинные вычисления были очень громоздкими.', 'Long ago expressions were written in words: “add eighty to twenty and divide by four”. <b>Al-Khwarizmi</b> also stated his problems in words. The order was clear from the sentence, but long calculations were very clumsy.'),
      L('«+» va «−» belgilari XV asr oxirida Germaniyada paydo bo‘lgan. «×» belgisini 1631-yilda ingliz matematigi Uilyam Otred, nuqtani (·) esa nemis olimi Gotfrid Leybnits taklif qilgan. Qavslar XVI–XVII asrlarda keng tarqalgan.', 'Знаки «+» и «−» появились в конце XV века в Германии. Знак «×» в 1631 году предложил английский математик Уильям Отред, а точку (·) — немецкий учёный Готфрид Лейбниц. Скобки широко распространились в XVI–XVII веках.', 'The signs “+” and “−” appeared in Germany at the end of the 15th century. The sign “×” was proposed in 1631 by the English mathematician William Oughtred, and the dot (·) by the German scholar Gottfried Leibniz. Brackets spread widely in the 16th–17th centuries.'),
      L('Amallar tartibi qoidasi asta-sekin, kitoblardan kitoblarga o‘tib shakllangan. XX asrda kalkulyator va kompyuterlar paydo bo‘lgach, u qat’iy standartga aylandi: barcha dasturlash tillari aynan shu tartibga amal qiladi.', 'Правило порядка действий складывалось постепенно, переходя из книги в книгу. В XX веке с появлением калькуляторов и компьютеров оно стало строгим стандартом: все языки программирования следуют именно этому порядку.', 'The order-of-operations rule took shape gradually, passed from book to book. In the 20th century, with calculators and computers, it became a strict standard: every programming language follows exactly this order.')
    ] },
    { kind: 'rule', h: L('Amallar tartibi qoidasi', 'Правило порядка действий', 'The order-of-operations rule'), list: [
      L('<b>1.</b> Avval <b>qavs ichidagi</b> amallar bajariladi (ichkisidan tashqarisiga).', '<b>1.</b> Сначала выполняют действия <b>в скобках</b> (от внутренних к внешним).', '<b>1.</b> First do what is <b>inside brackets</b> (innermost first).'),
      L('<b>2.</b> So‘ng <b>ko‘paytirish va bo‘lish</b> — chapdan o‘ngga, qaysi biri oldin kelsa.', '<b>2.</b> Затем <b>умножение и деление</b> — слева направо, в порядке следования.', '<b>2.</b> Then <b>multiplication and division</b> — left to right, in the order they appear.'),
      L('<b>3.</b> Oxirida <b>qo‘shish va ayirish</b> — chapdan o‘ngga.', '<b>3.</b> В конце <b>сложение и вычитание</b> — слева направо.', '<b>3.</b> Finally <b>addition and subtraction</b> — left to right.'),
      L('<b>4.</b> Agar ifodada faqat bir bosqich amallari bo‘lsa, ular yozilgan tartibda — chapdan o‘ngga bajariladi: 100 − 30 + 20 = 90, 50 emas.', '<b>4.</b> Если в выражении действия только одной ступени, их выполняют по порядку — слева направо: 100 − 30 + 20 = 90, а не 50.', '<b>4.</b> If the expression has only one level, work left to right as written: 100 − 30 + 20 = 90, not 50.')
    ], after: [
      L('Qisqa eslatma: <b>( ) → · : → + −</b>. Muhim: ko‘paytirish bo‘lishdan «kuchli» emas — ular teng huquqli. 48 : 6 · 2 = 8 · 2 = 16, 48 : 12 = 4 emas! Xuddi shunday qo‘shish va ayirish ham teng huquqli.', 'Краткая памятка: <b>( ) → · : → + −</b>. Важно: умножение не «сильнее» деления — они равноправны. 48 : 6 · 2 = 8 · 2 = 16, а не 48 : 12 = 4! Так же равноправны сложение и вычитание.', 'Short reminder: <b>( ) → · : → + −</b>. Important: multiplication is not “stronger” than division — they are equal. 48 : 6 · 2 = 8 · 2 = 16, not 48 : 12 = 4! Likewise addition and subtraction are equal.')
    ] },
    { kind: 'steps', h: L('Murakkab ifodani hisoblash rejasi', 'План вычисления сложного выражения', 'A plan for a long expression'), list: [
      L('<b>1-qadam.</b> Ifodani diqqat bilan o‘qing va qavslarni toping.', '<b>Шаг 1.</b> Внимательно прочитайте выражение и найдите скобки.', '<b>Step 1.</b> Read the expression carefully and find the brackets.'),
      L('<b>2-qadam.</b> Har bir amal belgisi ustiga uning tartib raqamini yozing: 1, 2, 3…', '<b>Шаг 2.</b> Над каждым знаком действия напишите его порядковый номер: 1, 2, 3…', '<b>Step 2.</b> Write the order number above each operation sign: 1, 2, 3…'),
      L('<b>3-qadam.</b> Amallarni raqamlar bo‘yicha bajaring, har birining natijasini alohida yozing.', '<b>Шаг 3.</b> Выполняйте действия по номерам, записывая результат каждого отдельно.', '<b>Step 3.</b> Carry out the operations by number, writing each result separately.'),
      L('<b>4-qadam.</b> Yoki «zanjir» usulidan foydalaning: har qadamda ifodani qayta yozib, bajarilgan qismni natija bilan almashtiring: 600 − (120 + 30) · 4 = 600 − 150 · 4 = 600 − 600 = 0.', '<b>Шаг 4.</b> Или используйте «цепочку»: на каждом шаге переписывайте выражение, заменяя выполненную часть результатом: 600 − (120 + 30) · 4 = 600 − 150 · 4 = 600 − 600 = 0.', '<b>Step 4.</b> Or use a “chain”: at each step rewrite the expression, replacing the finished part with its result: 600 − (120 + 30) · 4 = 600 − 150 · 4 = 600 − 600 = 0.'),
      L('<b>5-qadam.</b> Javobni taxminiy hisob bilan tekshiring: u mantiqan to‘g‘ri keladimi?', '<b>Шаг 5.</b> Проверьте ответ прикидкой: разумен ли он?', '<b>Step 5.</b> Check the answer with an estimate: does it make sense?')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Hisoblang: 20 + 80 : 4.', 'Вычислите: 20 + 80 : 4.', 'Calculate 20 + 80 : 4.'), s: L('Qavs yo‘q. Bo‘lish qo‘shishdan oldin: 80 : 4 = 20. So‘ng 20 + 20 = <b>40</b>.', 'Скобок нет. Деление раньше сложения: 80 : 4 = 20. Затем 20 + 20 = <b>40</b>.', 'No brackets. Division before addition: 80 : 4 = 20. Then 20 + 20 = <b>40</b>.') },
      { q: L('Hisoblang: (20 + 80) : 4.', 'Вычислите: (20 + 80) : 4.', 'Calculate (20 + 80) : 4.'), s: L('Qavs birinchi: 20 + 80 = 100. So‘ng 100 : 4 = <b>25</b>. Qavslar javobni butunlay o‘zgartirdi!', 'Сначала скобки: 20 + 80 = 100. Затем 100 : 4 = <b>25</b>. Скобки полностью изменили ответ!', 'Brackets first: 20 + 80 = 100. Then 100 : 4 = <b>25</b>. The brackets changed the answer completely!') },
      { q: L('Hisoblang: 720 : 8 − 6 · 12 + 35.', 'Вычислите: 720 : 8 − 6 · 12 + 35.', 'Calculate 720 : 8 − 6 · 12 + 35.'), s: L('1) 720 : 8 = 90; 2) 6 · 12 = 72; 3) 90 − 72 = 18; 4) 18 + 35 = <b>53</b>. Ikkinchi bosqich amallari avval, so‘ng ayirish va qo‘shish chapdan o‘ngga.', '1) 720 : 8 = 90; 2) 6 · 12 = 72; 3) 90 − 72 = 18; 4) 18 + 35 = <b>53</b>. Сначала действия второй ступени, затем вычитание и сложение слева направо.', '1) 720 : 8 = 90; 2) 6 · 12 = 72; 3) 90 − 72 = 18; 4) 18 + 35 = <b>53</b>. Second-level operations first, then subtraction and addition left to right.') },
      { q: L('Hisoblang: 1 000 − (45 + 5 · (36 − 28)) · 10.', 'Вычислите: 1 000 − (45 + 5 · (36 − 28)) · 10.', 'Calculate 1 000 − (45 + 5 · (36 − 28)) · 10.'), s: L('Ichki qavs: 36 − 28 = 8. Tashqi qavs: 45 + 5 · 8 = 45 + 40 = 85. Ko‘paytirish: 85 · 10 = 850. Ayirish: 1 000 − 850 = <b>150</b>.', 'Внутренние скобки: 36 − 28 = 8. Внешние скобки: 45 + 5 · 8 = 45 + 40 = 85. Умножение: 85 · 10 = 850. Вычитание: 1 000 − 850 = <b>150</b>.', 'Inner brackets: 36 − 28 = 8. Outer brackets: 45 + 5 · 8 = 45 + 40 = 85. Multiply: 85 · 10 = 850. Subtract: 1 000 − 850 = <b>150</b>.') },
      { q: L('Qavs qo‘yib, tenglikni to‘g‘ri qiling: 6 + 4 · 5 − 2 = 48.', 'Расставьте скобки, чтобы равенство стало верным: 6 + 4 · 5 − 2 = 48.', 'Insert brackets to make it true: 6 + 4 · 5 − 2 = 48.'), s: L('Qavssiz: 6 + 20 − 2 = 24. Sinab ko‘ramiz: (6 + 4) · 5 − 2 = 48 ✓. Javob: <b>(6 + 4) · 5 − 2 = 48</b>.', 'Без скобок: 6 + 20 − 2 = 24. Пробуем: (6 + 4) · 5 − 2 = 48 ✓. Ответ: <b>(6 + 4) · 5 − 2 = 48</b>.', 'Without brackets: 6 + 20 − 2 = 24. Try: (6 + 4) · 5 − 2 = 48 ✓. Answer: <b>(6 + 4) · 5 − 2 = 48</b>.') }
    ] },
    { kind: 'table', h: L('Bir xil sonlar — har xil qavslar', 'Одни и те же числа — разные скобки', 'Same numbers, different brackets'), p: [
      L('2, 3, 4 sonlari va «+», «·» belgilari bilan qavslarni har xil qo‘yib ko‘ramiz. Qavslar natijaga qanchalik ta’sir qilishini ko‘ring.', 'Возьмём числа 2, 3, 4 и знаки «+», «·» и расставим скобки по-разному. Посмотрите, как сильно скобки влияют на результат.', 'Take 2, 3, 4 with “+” and “·” and place brackets differently. See how much brackets change the result.')
    ], table: { head: [L('Ifoda', 'Выражение', 'Expression'), L('Tartib', 'Порядок', 'Order'), L('Qiymat', 'Значение', 'Value')], rows: [
      ['2 + 3 · 4', L('· keyin +', '· потом +', '· then +'), '14'],
      ['(2 + 3) · 4', L('( ) keyin ·', '( ) потом ·', '( ) then ·'), '20'],
      ['2 · 3 + 4', L('· keyin +', '· потом +', '· then +'), '10'],
      ['2 · (3 + 4)', L('( ) keyin ·', '( ) потом ·', '( ) then ·'), '14'],
      ['24 : 4 · 2', L('chapdan o‘ngga', 'слева направо', 'left to right'), '12'],
      ['24 : (4 · 2)', L('( ) keyin :', '( ) потом :', '( ) then :'), '3']
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Chapdan o‘ngga ko‘r-ko‘rona hisoblash.</b> 5 + 3 · 2 = 16 emas, 11. Avval ko‘paytirish!', '<b>Слепой счёт слева направо.</b> 5 + 3 · 2 = не 16, а 11. Сначала умножение!', '<b>Blindly going left to right.</b> 5 + 3 · 2 is not 16 but 11. Multiply first!'),
      L('<b>Ko‘paytirishni bo‘lishdan oldin qilish.</b> 60 : 5 · 3 = 12 · 3 = 36, lekin 60 : 15 = 4 emas. Ular teng huquqli — chapdan o‘ngga.', '<b>Умножают раньше деления.</b> 60 : 5 · 3 = 12 · 3 = 36, а не 60 : 15 = 4. Они равноправны — слева направо.', '<b>Multiplying before dividing.</b> 60 : 5 · 3 = 12 · 3 = 36, not 60 : 15 = 4. They are equal — left to right.'),
      L('<b>Qo‘shishni ayirishdan oldin qilish.</b> 50 − 20 + 10 = 40, 20 emas.', '<b>Складывают раньше вычитания.</b> 50 − 20 + 10 = 40, а не 20.', '<b>Adding before subtracting.</b> 50 − 20 + 10 = 40, not 20.'),
      L('<b>Qavsni «yo‘qotib qo‘yish».</b> Zanjirda qayta yozganda qavs ichidagi amal bajarilmay qolib ketadi. Har qadamda faqat bitta yoki bir nechta mustaqil amalni bajaring va qolganini o‘zgartirmay ko‘chiring.', '<b>«Теряют» скобки.</b> При переписывании в цепочке забывают выполнить действие в скобках. На каждом шаге выполняйте одно или несколько независимых действий, а остальное переписывайте без изменений.', '<b>“Losing” brackets.</b> When rewriting a chain, the bracket operation gets skipped. At each step do one or a few independent operations and copy the rest unchanged.'),
      L('<b>Natijani noto‘g‘ri qo‘llash.</b> «20 + 80 = 100 : 4 = 25» kabi zanjir yozish noto‘g‘ri: 20 + 80 100 ga teng, 25 ga emas. Tenglik belgisi faqat teng narsalar orasida turadi.', '<b>Неверная запись цепочки.</b> Писать «20 + 80 = 100 : 4 = 25» нельзя: 20 + 80 равно 100, а не 25. Знак равенства ставят только между равными величинами.', '<b>Writing a false chain.</b> “20 + 80 = 100 : 4 = 25” is wrong: 20 + 80 equals 100, not 25. The equals sign goes only between equal things.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Uses in everyday life'), p: [
      L('<b>Do‘konda.</b> 3 ta daftar 4 000 so‘mdan va 1 ta ruchka 2 500 so‘m. Jami: 3 · 4 000 + 2 500 = 12 000 + 2 500 = 14 500 so‘m. Agar kassir avval qo‘shib, so‘ng ko‘paytirsa — (4 000 + 2 500) · 3 = 19 500 — siz 5 000 so‘m ortiqcha to‘laysiz!', '<b>В магазине.</b> 3 тетради по 4 000 сумов и 1 ручка за 2 500. Всего: 3 · 4 000 + 2 500 = 12 000 + 2 500 = 14 500 сумов. Если кассир сначала сложит, а потом умножит — (4 000 + 2 500) · 3 = 19 500 — вы переплатите 5 000 сумов!', '<b>In a shop.</b> 3 notebooks at 4 000 sum and 1 pen at 2 500. Total: 3 · 4 000 + 2 500 = 12 000 + 2 500 = 14 500 sum. If the cashier added first and then multiplied — (4 000 + 2 500) · 3 = 19 500 — you would overpay 5 000 sum!'),
      L('<b>Jadvallar va dasturlar.</b> Excel jadvalida yoki dasturda =20+80/4 formulasi 40 beradi. O‘rtacha bahoni hisoblash uchun =(5+4+5)/3 deb qavs qo‘yish kerak — aks holda natija noto‘g‘ri bo‘ladi.', '<b>Таблицы и программы.</b> В Excel или в программе формула =20+80/4 даёт 40. Чтобы найти средний балл, нужно писать со скобками =(5+4+5)/3 — иначе результат будет неверным.', '<b>Spreadsheets and programs.</b> In Excel or code the formula =20+80/4 gives 40. To find an average mark you must write =(5+4+5)/3 with brackets — otherwise the result is wrong.'),
      L('<b>Sport.</b> Futbol jadvalida ochkolar: g‘alaba — 3, durang — 1. Jamoa 8 marta yutib, 4 marta durang o‘ynasa: 8 · 3 + 4 · 1 = 24 + 4 = 28 ochko. Bu ifodada ham ko‘paytirish avval bajariladi.', '<b>Спорт.</b> В футбольной таблице: победа — 3 очка, ничья — 1. Команда 8 раз выиграла и 4 раза сыграла вничью: 8 · 3 + 4 · 1 = 24 + 4 = 28 очков. И здесь умножение выполняется первым.', '<b>Sport.</b> In a football table a win is 3 points and a draw 1. A team with 8 wins and 4 draws has 8 · 3 + 4 · 1 = 24 + 4 = 28 points. Multiplication comes first here too.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Ijtimoiy tarmoqlarda «6 : 2(1 + 2) = ?» degan masala millionlab odamni bahslashtirgan. Muammo ifodaning noaniq yozilganida: aniqlik uchun qavslarni to‘liq qo‘yish kerak.', 'В соцсетях задача «6 : 2(1 + 2) = ?» вызвала споры у миллионов людей. Проблема в неоднозначной записи: для ясности скобки нужно ставить полностью.', 'Online, the puzzle “6 : 2(1 + 2) = ?” set millions arguing. The trouble is the ambiguous writing: for clarity, use full brackets.'),
      L('Oddiy (arzon) kalkulyatorlar ba’zan amallarni kiritilgan tartibda bajaradi va 2 + 3 · 4 = 20 deb ko‘rsatadi. Ilmiy kalkulyator esa to‘g‘ri — 14 javob beradi.', 'Простые (дешёвые) калькуляторы иногда выполняют действия в порядке ввода и показывают 2 + 3 · 4 = 20. А инженерный калькулятор даёт правильный ответ — 14.', 'Simple (cheap) calculators sometimes work in the order you type and show 2 + 3 · 4 = 20. A scientific calculator gives the correct answer, 14.'),
      L('To‘rtta 4 raqami, amal belgilari va qavslar yordamida 0 dan 10 gacha har bir sonni hosil qilish mumkin. Masalan, (4 + 4) : (4 + 4) = 1, 4 : 4 + 4 : 4 = 2.', 'С помощью четырёх четвёрок, знаков действий и скобок можно получить каждое число от 0 до 10. Например, (4 + 4) : (4 + 4) = 1, 4 : 4 + 4 : 4 = 2.', 'Using four 4s, operation signs and brackets you can make every number from 0 to 10. For example, (4 + 4) : (4 + 4) = 1, 4 : 4 + 4 : 4 = 2.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('Hisoblang: 90 − 30 : 3 · 2.', 'Вычислите: 90 − 30 : 3 · 2.', 'Calculate 90 − 30 : 3 · 2.'),
      L('Qavs qo‘ying: 36 : 6 − 2 = 9.', 'Расставьте скобки: 36 : 6 − 2 = 9.', 'Insert brackets: 36 : 6 − 2 = 9.'),
      L('To‘rtta 4 bilan 3 ni hosil qiling.', 'Получите 3 с помощью четырёх четвёрок.', 'Make 3 from four 4s.'),
      L('Ifoda tuzing va hisoblang: 5 ta qalam 1 200 so‘mdan va 2 ta o‘chirg‘ich 800 so‘mdan.', 'Составьте выражение и вычислите: 5 карандашей по 1 200 сумов и 2 ластика по 800 сумов.', 'Write and work out an expression: 5 pencils at 1 200 sum and 2 erasers at 800 sum.')
    ], after: [
      L('Javoblar: 30 : 3 = 10, 10 · 2 = 20, 90 − 20 = 70; 36 : (6 − 2) = 9; (4 + 4 + 4) : 4 = 3; 5 · 1 200 + 2 · 800 = 6 000 + 1 600 = 7 600 so‘m.', 'Ответы: 30 : 3 = 10, 10 · 2 = 20, 90 − 20 = 70; 36 : (6 − 2) = 9; (4 + 4 + 4) : 4 = 3; 5 · 1 200 + 2 · 800 = 6 000 + 1 600 = 7 600 сумов.', 'Answers: 30 : 3 = 10, 10 · 2 = 20, 90 − 20 = 70; 36 : (6 − 2) = 9; (4 + 4 + 4) : 4 = 3; 5 · 1 200 + 2 · 800 = 6 000 + 1 600 = 7 600 sum.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Amallar tartibi hamma uchun bir xil, shuning uchun ifodaning qiymati yagona.', 'Порядок действий одинаков для всех, поэтому значение выражения единственно.', 'The order of operations is the same for everyone, so an expression has one value.'),
      L('Tartib: ( ) → · va : → + va −.', 'Порядок: ( ) → · и : → + и −.', 'Order: ( ) → · and : → + and −.'),
      L('Bir bosqich amallari chapdan o‘ngga bajariladi.', 'Действия одной ступени выполняют слева направо.', 'Operations of the same level go left to right.'),
      L('Ichma-ich qavslarda eng ichkisidan boshlanadi.', 'Во вложенных скобках начинают с самых внутренних.', 'With nested brackets, start with the innermost.'),
      L('Amallarni raqamlab chiqing yoki zanjir usulida yozing.', 'Нумеруйте действия или записывайте цепочкой.', 'Number the operations or write a chain.'),
      L('Qavslar natijani tubdan o‘zgartirishi mumkin: 2 + 3 · 4 = 14, (2 + 3) · 4 = 20.', 'Скобки могут сильно изменить результат: 2 + 3 · 4 = 14, (2 + 3) · 4 = 20.', 'Brackets can change the result completely: 2 + 3 · 4 = 14, (2 + 3) · 4 = 20.')
    ] }
  ] });

  // ---------- t6. Matnli masalalar ----------
  T.add(P, 't6', { sections: [
    { kind: 'intro', h: L('Masala — bu hikoya', 'Задача — это история', 'A problem is a story'), p: [
      L('Har bir matnli masala — kichik hikoya. Unda qahramonlar (oyi, Ali, do‘kon, avtobus), sonlar va savol bor. Bizning vazifamiz — hikoyani matematika tiliga «tarjima» qilish: qaysi amallarni qaysi tartibda bajarish kerakligini aniqlash.', 'Каждая текстовая задача — маленькая история. В ней есть герои (мама, Али, магазин, автобус), числа и вопрос. Наша задача — «перевести» историю на язык математики: понять, какие действия и в каком порядке выполнять.', 'Every word problem is a little story. It has characters (Mum, Ali, a shop, a bus), numbers and a question. Our job is to “translate” the story into the language of maths: decide which operations to do and in what order.'),
      L('Ko‘p o‘quvchilar masalani o‘qib, darhol sonlarni qo‘shib yoki ko‘paytirib yuboradi. Bu — xatolarning asosiy sababi. Yaxshi yechuvchi avval o‘ylaydi, reja tuzadi, keyin hisoblaydi va oxirida tekshiradi. Bu mavzuda ana shu to‘rt bosqichli usulni o‘rganamiz.', 'Многие ученики, прочитав задачу, сразу начинают складывать или умножать числа. Это главная причина ошибок. Хороший решатель сначала думает, составляет план, потом считает и в конце проверяет. В этой теме изучим этот способ из четырёх шагов.', 'Many pupils read a problem and immediately start adding or multiplying the numbers. That is the main cause of mistakes. A good solver thinks first, makes a plan, then calculates and finally checks. In this topic we learn this four-step method.'),
      L('Masala yechish ko‘nikmasi faqat matematika uchun emas: u hayotdagi har qanday muammoni hal qilishga — xarid rejalashtirish, vaqtni taqsimlash, sayohat tayyorlashga yordam beradi.', 'Умение решать задачи нужно не только в математике: оно помогает решать любые жизненные проблемы — планировать покупки, распределять время, готовить поездку.', 'Problem-solving is not only for maths: it helps with any problem in life — planning shopping, sharing out time, preparing a trip.')
    ] },
    { kind: 'def', h: L('Masalaning qismlari', 'Части задачи', 'Parts of a problem'), p: [
      L('Har bir masalada uchta qism bor: <b>shart</b> — nima ma’lum (berilgan sonlar va ular orasidagi bog‘lanish); <b>savol</b> — nimani topish kerak; <b>yechim</b> — shartdan savolga olib boradigan amallar zanjiri. Yechim oxirida <b>javob</b> yoziladi — o‘lchov birligi bilan!', 'В каждой задаче три части: <b>условие</b> — что известно (данные числа и связи между ними); <b>вопрос</b> — что нужно найти; <b>решение</b> — цепочка действий от условия к вопросу. В конце пишется <b>ответ</b> — с единицами измерения!', 'Every problem has three parts: the <b>condition</b> — what is known (the given numbers and how they are linked); the <b>question</b> — what to find; and the <b>solution</b> — a chain of operations from condition to question. At the end comes the <b>answer</b> — with units!'),
      L('<b>Sodda masala</b> bitta amal bilan yechiladi: «60 km/soat tezlikda 3 soat — necha km?» → 60 · 3 = 180 km. <b>Murakkab (tarkibli) masala</b> bir necha amalni talab qiladi: avval yordamchi savolga javob topiladi, so‘ng asosiy savolga.', '<b>Простая задача</b> решается одним действием: «3 часа со скоростью 60 км/ч — сколько км?» → 60 · 3 = 180 км. <b>Составная задача</b> требует нескольких действий: сначала отвечаем на вспомогательный вопрос, потом на главный.', 'A <b>simple problem</b> takes one operation: “3 hours at 60 km/h — how many km?” → 60 · 3 = 180 km. A <b>multi-step problem</b> needs several: first answer a helper question, then the main one.'),
      L('Muhim bog‘lanishlar: <b>narx · miqdor = qiymat</b>; <b>tezlik · vaqt = masofa</b>; <b>ish unumdorligi · vaqt = ish hajmi</b>. Ulardan biri noma’lum bo‘lsa, qolganlari orqali topiladi: masofa : vaqt = tezlik.', 'Важные связи: <b>цена · количество = стоимость</b>; <b>скорость · время = расстояние</b>; <b>производительность · время = объём работы</b>. Если одна из величин неизвестна, её находят через другие: расстояние : время = скорость.', 'Key links: <b>price · quantity = cost</b>; <b>speed · time = distance</b>; <b>rate of work · time = amount of work</b>. If one is unknown, find it from the others: distance : time = speed.')
    ] },
    { kind: 'history', h: L('Qadimiy masalalar', 'Древние задачи', 'Ancient problems'), p: [
      L('Eng qadimgi matnli masalalar Misrning <b>Rind papirusida</b> (taxminan miloddan avvalgi 1650-yil) saqlangan. Unda 84 ta masala bor: nonni ishchilar o‘rtasida taqsimlash, don omborining hajmini topish, piramida qiyaligini hisoblash. Mirzo kotib Ahmes ularni «barcha sirli narsalarni bilish yo‘li» deb atagan.', 'Самые древние текстовые задачи сохранились в египетском <b>папирусе Ринда</b> (около 1650 года до н. э.). В нём 84 задачи: разделить хлеб между рабочими, найти объём зернохранилища, вычислить наклон пирамиды. Писец Ахмес назвал их «путём к знанию всех тёмных вещей».', 'The oldest word problems survive in Egypt’s <b>Rhind Papyrus</b> (about 1650 BC). It has 84 problems: sharing bread among workers, finding a granary’s volume, working out a pyramid’s slope. The scribe Ahmes called them “the way to know all obscure things”.'),
      L('<b>Al-Xorazmiy</b>ning «Al-jabr val-muqobala» kitobida meros taqsimlash, savdo va yer o‘lchash haqida yuzlab masalalar bor. U har bir masalani bosqichma-bosqich yechish usulini ko‘rsatgan — aynan biz o‘rganayotgan reja asosida. <b>Beruniy</b> ham o‘z asarlarida taqvim, savdo va astronomiyaga oid amaliy masalalarni yechgan.', 'В книге <b>аль-Хорезми</b> «Аль-джабр валь-мукабала» сотни задач о разделе наследства, торговле и измерении земли. Он показал, как решать каждую задачу пошагово — именно по тому плану, который мы изучаем. <b>Беруни</b> тоже решал в своих трудах практические задачи о календаре, торговле и астрономии.', '<b>Al-Khwarizmi</b>’s book “Al-jabr wa’l-muqabala” contains hundreds of problems on dividing inheritances, trade and land measurement. He showed how to solve each step by step — exactly the plan we are learning. <b>Biruni</b> also solved practical problems on calendars, trade and astronomy in his works.'),
      L('XX asrda vengriyalik matematik <b>Dyord Poya</b> «Masalani qanday yechish kerak» kitobini yozdi. U ham to‘rt bosqichni taklif qilgan: masalani tushunish, reja tuzish, rejani bajarish va orqaga nazar tashlash (tekshirish).', 'В XX веке венгерский математик <b>Дьёрдь Пойа</b> написал книгу «Как решать задачу». Он тоже предложил четыре этапа: понять задачу, составить план, выполнить план и оглянуться назад (проверить).', 'In the 20th century the Hungarian mathematician <b>George Pólya</b> wrote “How to Solve It”. He too proposed four stages: understand the problem, make a plan, carry out the plan, and look back (check).')
    ] },
    { kind: 'rule', h: L('To‘rt bosqichli reja', 'План из четырёх шагов', 'The four-step plan'), list: [
      L('<b>1. Tushunish.</b> Masalani ikki marta o‘qing. Nima berilgan? Nima so‘ralgan? Qisqa shart yozing yoki chizma chizing.', '<b>1. Понять.</b> Прочитайте задачу дважды. Что дано? Что спрашивается? Запишите краткое условие или сделайте рисунок.', '<b>1. Understand.</b> Read the problem twice. What is given? What is asked? Write a short summary or draw a sketch.'),
      L('<b>2. Reja.</b> Savolga javob berish uchun nima bilish kerak? Agar bu ma’lum bo‘lmasa — yordamchi savol qo‘ying. Savoldan shartga qarab «orqaga» fikrlash ham foydali.', '<b>2. План.</b> Что нужно знать, чтобы ответить на вопрос? Если это неизвестно — поставьте вспомогательный вопрос. Полезно рассуждать и «от вопроса к условию».', '<b>2. Plan.</b> What must you know to answer the question? If it is unknown, ask a helper question. Thinking “backwards” from the question to the condition also helps.'),
      L('<b>3. Hisob.</b> Har bir amalni alohida yozing va uning ma’nosini tushuntiring: «1) 3 kg go‘sht narxi: 45 000 · 3 = 135 000 so‘m».', '<b>3. Вычисление.</b> Записывайте каждое действие отдельно и поясняйте его смысл: «1) стоимость 3 кг мяса: 45 000 · 3 = 135 000 сумов».', '<b>3. Calculate.</b> Write each step separately and explain it: “1) cost of 3 kg of meat: 45 000 · 3 = 135 000 sum”.'),
      L('<b>4. Tekshiruv.</b> Javob savolga mosmi? Mantiqan to‘g‘rimi (masalan, qolgan pul boshlang‘ichdan ko‘p bo‘lmasligi kerak)? Teskari masala tuzib tekshiring. Javobni birlik bilan yozing.', '<b>4. Проверка.</b> Отвечает ли ответ на вопрос? Разумен ли он (например, остаток денег не может быть больше начальной суммы)? Проверьте обратной задачей. Запишите ответ с единицами.', '<b>4. Check.</b> Does the answer fit the question? Is it sensible (money left cannot exceed the money at the start)? Check with an inverse problem. Write the answer with units.')
    ] },
    { kind: 'steps', h: L('Qisqa shart yozish', 'Как записать краткое условие', 'Writing a short summary'), p: [
      L('Masala: «Oyimning 400 000 so‘mi bor edi. U 45 000 so‘mdan 3 kg go‘sht va 8 000 so‘mdan 5 kg sabzavot oldi. Qancha pul qoldi?»', 'Задача: «У мамы было 400 000 сумов. Она купила 3 кг мяса по 45 000 сумов и 5 кг овощей по 8 000 сумов. Сколько денег осталось?»', 'Problem: “Mum had 400 000 sum. She bought 3 kg of meat at 45 000 sum and 5 kg of vegetables at 8 000 sum. How much money is left?”')
    ], list: [
      L('Bor edi — 400 000 so‘m.', 'Было — 400 000 сумов.', 'Had — 400 000 sum.'),
      L('Go‘sht — 3 kg, 1 kg narxi 45 000 so‘m.', 'Мясо — 3 кг, цена 1 кг 45 000 сумов.', 'Meat — 3 kg at 45 000 sum per kg.'),
      L('Sabzavot — 5 kg, 1 kg narxi 8 000 so‘m.', 'Овощи — 5 кг, цена 1 кг 8 000 сумов.', 'Vegetables — 5 kg at 8 000 sum per kg.'),
      L('Qoldi — ? so‘m.', 'Осталось — ? сумов.', 'Left — ? sum.'),
      L('Reja: go‘sht narxi → sabzavot narxi → jami xarid → qolgan pul. Ifoda: 400 000 − 3 · 45 000 − 5 · 8 000.', 'План: стоимость мяса → стоимость овощей → вся покупка → остаток. Выражение: 400 000 − 3 · 45 000 − 5 · 8 000.', 'Plan: cost of meat → cost of vegetables → total → money left. Expression: 400 000 − 3 · 45 000 − 5 · 8 000.')
    ], after: [
      L('Hisob: 135 000 + 40 000 = 175 000; 400 000 − 175 000 = <b>225 000 so‘m</b>. Tekshiruv: 225 000 + 175 000 = 400 000 ✓.', 'Вычисление: 135 000 + 40 000 = 175 000; 400 000 − 175 000 = <b>225 000 сумов</b>. Проверка: 225 000 + 175 000 = 400 000 ✓.', 'Calculation: 135 000 + 40 000 = 175 000; 400 000 − 175 000 = <b>225 000 sum</b>. Check: 225 000 + 175 000 = 400 000 ✓.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('3 ta daftar 4 500 so‘m turadi. 5 ta shunday daftar qancha turadi?', '3 тетради стоят 4 500 сумов. Сколько стоят 5 таких тетрадей?', '3 notebooks cost 4 500 sum. How much do 5 such notebooks cost?'), s: L('Yordamchi savol: 1 ta daftar narxi? 4 500 : 3 = 1 500 so‘m. Asosiy savol: 1 500 · 5 = <b>7 500 so‘m</b>. Bu «birlikka keltirish» usuli.', 'Вспомогательный вопрос: цена 1 тетради? 4 500 : 3 = 1 500 сумов. Главный вопрос: 1 500 · 5 = <b>7 500 сумов</b>. Это способ «приведения к единице».', 'Helper question: price of 1 notebook? 4 500 : 3 = 1 500 sum. Main question: 1 500 · 5 = <b>7 500 sum</b>. This is the “unit method”.') },
      { q: L('Ikki shahar orasidagi masofa 360 km. Avtobus 4 soat yurgach, 80 km qoldi. Avtobus tezligi qancha?', 'Расстояние между городами 360 км. Автобус ехал 4 часа, и осталось 80 км. Какова скорость автобуса?', 'Two cities are 360 km apart. After 4 hours the bus has 80 km left. What is its speed?'), s: L('1) Bosib o‘tilgan yo‘l: 360 − 80 = 280 km. 2) Tezlik: 280 : 4 = <b>70 km/soat</b>. Tekshiruv: 70 · 4 + 80 = 360 ✓.', '1) Пройденный путь: 360 − 80 = 280 км. 2) Скорость: 280 : 4 = <b>70 км/ч</b>. Проверка: 70 · 4 + 80 = 360 ✓.', '1) Distance covered: 360 − 80 = 280 km. 2) Speed: 280 : 4 = <b>70 km/h</b>. Check: 70 · 4 + 80 = 360 ✓.') },
      { q: L('Bir ishchi soatiga 12 ta detal, ikkinchisi 15 ta detal yasaydi. Birga 8 soatda nechta detal yasaydi?', 'Один рабочий делает 12 деталей в час, второй — 15. Сколько деталей они сделают вместе за 8 часов?', 'One worker makes 12 parts an hour, another 15. How many parts do they make together in 8 hours?'), s: L('1-usul: 12 + 15 = 27 ta (soatiga birga); 27 · 8 = <b>216 ta</b>. 2-usul: 12 · 8 = 96; 15 · 8 = 120; 96 + 120 = 216. Ikki usul bir xil javob berdi — demak, to‘g‘ri.', 'Способ 1: 12 + 15 = 27 (вместе за час); 27 · 8 = <b>216</b>. Способ 2: 12 · 8 = 96; 15 · 8 = 120; 96 + 120 = 216. Оба способа дали одинаковый ответ — значит, верно.', 'Way 1: 12 + 15 = 27 (together per hour); 27 · 8 = <b>216</b>. Way 2: 12 · 8 = 96; 15 · 8 = 120; 96 + 120 = 216. Both ways agree, so it is right.') },
      { q: L('Ikki sonning yig‘indisi 75, ulardan biri ikkinchisidan 15 ta katta. Sonlarni toping.', 'Сумма двух чисел 75, одно больше другого на 15. Найдите числа.', 'Two numbers add up to 75; one is 15 more than the other. Find them.'), s: L('Kattasidan ortiqcha 15 ni olib tashlasak, ikki teng son qoladi: 75 − 15 = 60, 60 : 2 = 30 — kichik son. Katta son: 30 + 15 = 45. Javob: <b>30 va 45</b>. Tekshiruv: 30 + 45 = 75 ✓, 45 − 30 = 15 ✓.', 'Если убрать лишние 15 у большего, получим два равных числа: 75 − 15 = 60, 60 : 2 = 30 — меньшее. Большее: 30 + 15 = 45. Ответ: <b>30 и 45</b>. Проверка: 30 + 45 = 75 ✓, 45 − 30 = 15 ✓.', 'Remove the extra 15 from the bigger one and two equal numbers remain: 75 − 15 = 60, 60 : 2 = 30, the smaller. The bigger: 30 + 15 = 45. Answer: <b>30 and 45</b>. Check: 30 + 45 = 75 ✓, 45 − 30 = 15 ✓.') }
    ] },
    { kind: 'table', h: L('Asosiy bog‘lanishlar', 'Основные зависимости', 'Key relationships'), table: { head: [L('Mavzu', 'Тема', 'Topic'), L('Formula', 'Формула', 'Formula'), L('Noma’lumni topish', 'Нахождение неизвестного', 'Finding the unknown')], rows: [
      [L('Xarid', 'Покупка', 'Shopping'), L('qiymat = narx · miqdor', 'стоимость = цена · количество', 'cost = price · quantity'), L('narx = qiymat : miqdor', 'цена = стоимость : количество', 'price = cost : quantity')],
      [L('Harakat', 'Движение', 'Motion'), L('masofa = tezlik · vaqt', 'расстояние = скорость · время', 'distance = speed · time'), L('vaqt = masofa : tezlik', 'время = расстояние : скорость', 'time = distance : speed')],
      [L('Ish', 'Работа', 'Work'), L('ish = unumdorlik · vaqt', 'работа = производительность · время', 'work = rate · time'), L('unumdorlik = ish : vaqt', 'производительность = работа : время', 'rate = work : time')],
      [L('Qadoqlash', 'Упаковка', 'Packing'), L('jami = bir qutidagi · qutilar', 'всего = в одной коробке · коробки', 'total = per box · boxes'), L('qutilar = jami : bir qutidagi', 'коробки = всего : в одной', 'boxes = total : per box')]
    ] }, after: [
      L('Har bir qatorda uchta miqdor bor: ikkitasi ma’lum bo‘lsa, uchinchisi topiladi. Ko‘paytma noma’lum bo‘lsa — ko‘paytiramiz, ko‘paytuvchi noma’lum bo‘lsa — bo‘lamiz.', 'В каждой строке три величины: если две известны, третью можно найти. Неизвестно произведение — умножаем, неизвестен множитель — делим.', 'Each row links three quantities: know two and you can find the third. Unknown product — multiply; unknown factor — divide.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Masalani oxirigacha o‘qimaslik.</b> «Qancha pul qoldi?» deb so‘ralganda faqat xarid narxini topib to‘xtash — yarim yechim.', '<b>Не дочитывают задачу.</b> Если спрашивают «сколько денег осталось?», а вы нашли только стоимость покупки, — это лишь половина решения.', '<b>Not reading to the end.</b> If asked “how much is left?”, stopping at the cost of the shopping is only half a solution.'),
      L('<b>«Ko‘p» so‘zi = qo‘shish deb o‘ylash.</b> «Ali 5 ta ko‘p oldi» — bu Alinikini topish uchun qo‘shish, lekin «Alida Validan 5 ta ko‘p, Alida 20 ta» bo‘lsa, Valinikini topish uchun ayiramiz. Kalit so‘zlarga emas, ma’noga qarang.', '<b>Думают, что «больше» = сложение.</b> «У Али на 5 больше» — для поиска Али прибавляем, но если «у Али на 5 больше, чем у Вали, у Али 20», для поиска Вали вычитаем. Смотрите на смысл, а не на слова-подсказки.', '<b>Thinking “more” always means add.</b> “Ali has 5 more” — to find Ali’s, add; but if “Ali has 5 more than Vali and Ali has 20”, to find Vali’s, subtract. Follow the meaning, not the key words.'),
      L('<b>Birliklarni aralashtirish.</b> Bir joyda km, boshqasida m bo‘lsa, avval bir xil birlikka keltiring.', '<b>Смешивают единицы.</b> Если в одном месте км, а в другом м, сначала приведите к одной единице.', '<b>Mixing units.</b> If one number is in km and another in m, convert to the same unit first.'),
      L('<b>Javobni tekshirmaslik.</b> Qolgan pul boshlang‘ich puldan ko‘p chiqsa yoki tezlik soatiga 7 000 km bo‘lsa — xato bor.', '<b>Не проверяют ответ.</b> Если остаток больше начальной суммы или скорость автобуса 7 000 км/ч — где-то ошибка.', '<b>Not checking.</b> If the money left exceeds the starting amount, or a bus does 7 000 km/h — something is wrong.'),
      L('<b>Birliksiz javob.</b> «Javob: 225 000» — nimaning 225 000 tasi? To‘g‘ri: «225 000 so‘m».', '<b>Ответ без единиц.</b> «Ответ: 225 000» — 225 000 чего? Правильно: «225 000 сумов».', '<b>Answer without units.</b> “Answer: 225 000” — 225 000 of what? Correct: “225 000 sum”.')
    ] },
    { kind: 'life', h: L('Hayotdagi masalalar', 'Задачи из жизни', 'Problems from real life'), p: [
      L('<b>Sayohatni rejalashtirish.</b> Oila Toshkentdan Farg‘onaga (taxminan 320 km) mashinada bormoqchi. Soatiga 80 km tezlikda yo‘l 320 : 80 = 4 soat davom etadi. Agar ular soat 8:00 da chiqib, yo‘lda 30 daqiqa dam olsa, 12:30 da yetib boradi. Bu — haqiqiy murakkab masala!', '<b>Планирование поездки.</b> Семья хочет поехать на машине из Ташкента в Фергану (около 320 км). При скорости 80 км/ч дорога займёт 320 : 80 = 4 часа. Если выехать в 8:00 и отдохнуть в пути 30 минут, они приедут в 12:30. Это настоящая составная задача!', '<b>Planning a trip.</b> A family drives from Tashkent to Fergana (about 320 km). At 80 km/h the journey takes 320 : 80 = 4 hours. Leaving at 8:00 with a 30-minute rest, they arrive at 12:30. That is a real multi-step problem!'),
      L('<b>Tug‘ilgan kun.</b> 12 nafar mehmon uchun har biriga 2 ta pirojniy (3 000 so‘mdan) va 1 stakan sharbat (2 000 so‘mdan) kerak: 12 · (2 · 3 000 + 2 000) = 12 · 8 000 = 96 000 so‘m. Reja tuzib hisoblash ortiqcha sarfdan saqlaydi.', '<b>День рождения.</b> Для 12 гостей каждому нужно 2 пирожных (по 3 000 сумов) и стакан сока (по 2 000): 12 · (2 · 3 000 + 2 000) = 12 · 8 000 = 96 000 сумов. Расчёт по плану бережёт от лишних трат.', '<b>A birthday party.</b> Each of 12 guests needs 2 cakes (3 000 sum each) and a glass of juice (2 000 sum): 12 · (2 · 3 000 + 2 000) = 12 · 8 000 = 96 000 sum. Planning keeps you from overspending.'),
      L('<b>Uy vazifasi va vaqt.</b> Agar har kuni 25 daqiqa kitob o‘qisangiz, bir haftada 25 · 7 = 175 daqiqa — qariyb 3 soat bo‘ladi. 210 betlik kitobni kuniga 15 betdan o‘qib, 210 : 15 = 14 kunda tugatasiz.', '<b>Уроки и время.</b> Если читать каждый день по 25 минут, за неделю будет 25 · 7 = 175 минут — почти 3 часа. Книгу в 210 страниц по 15 страниц в день вы прочитаете за 210 : 15 = 14 дней.', '<b>Homework and time.</b> Reading 25 minutes a day gives 25 · 7 = 175 minutes a week — almost 3 hours. A 210-page book at 15 pages a day takes 210 : 15 = 14 days.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Rind papirusi uzunligi 5 metrdan ortiq bo‘lib, hozir Londondagi Britaniya muzeyida saqlanadi.', 'Папирус Ринда длиной более 5 метров хранится сейчас в Британском музее в Лондоне.', 'The Rhind Papyrus is over 5 metres long and is kept in the British Museum in London.'),
      L('Rind papirusining 79-masalasida 7 ta uy, har birida 7 ta mushuk, har bir mushuk 7 ta sichqon tutadi… va hokazo — bu dunyodagi eng qadimiy «zanjir» masalalardan biri.', 'В 79-й задаче папируса Ринда 7 домов, в каждом 7 кошек, каждая ловит 7 мышей… и так далее — одна из древнейших задач-«цепочек» в мире.', 'Problem 79 of the Rhind Papyrus has 7 houses, each with 7 cats, each cat catching 7 mice… and so on — one of the oldest “chain” problems in the world.'),
      L('Buyuk matematik Karl Gauss maktabda 1 dan 100 gacha sonlar yig‘indisini bir necha daqiqada topgan: 50 juftlik, har biri 101 → 50 · 101 = 5 050.', 'Великий математик Карл Гаусс в школе за несколько минут нашёл сумму чисел от 1 до 100: 50 пар, каждая по 101 → 50 · 101 = 5 050.', 'The great mathematician Carl Gauss, as a schoolboy, found the sum of 1 to 100 in minutes: 50 pairs, each 101 → 50 · 101 = 5 050.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('Velosipedchi 3 soatda 45 km yurdi. Shu tezlikda 5 soatda necha km yuradi?', 'Велосипедист за 3 часа проехал 45 км. Сколько км он проедет за 5 часов с той же скоростью?', 'A cyclist rode 45 km in 3 hours. How far at the same speed in 5 hours?'),
      L('Sinfda 32 o‘quvchi. Qizlar o‘g‘il bolalardan 4 ta ko‘p. Nechta qiz bor?', 'В классе 32 ученика. Девочек на 4 больше, чем мальчиков. Сколько девочек?', 'A class has 32 pupils. There are 4 more girls than boys. How many girls?'),
      L('1 000 000 so‘mga 85 000 so‘mlik nechta kitob olish mumkin va qancha qaytim qoladi?', 'Сколько книг по 85 000 сумов можно купить на 1 000 000 сумов и какая будет сдача?', 'How many 85 000-sum books can 1 000 000 sum buy, and what change is left?')
    ], after: [
      L('Javoblar: 45 : 3 = 15 km/soat, 15 · 5 = 75 km; (32 + 4) : 2 = 18 qiz; 1 000 000 : 85 000 = 11 (qoldiq 65 000) — 11 ta kitob, 65 000 so‘m qaytim.', 'Ответы: 45 : 3 = 15 км/ч, 15 · 5 = 75 км; (32 + 4) : 2 = 18 девочек; 1 000 000 : 85 000 = 11 (ост. 65 000) — 11 книг и 65 000 сумов сдачи.', 'Answers: 45 : 3 = 15 km/h, 15 · 5 = 75 km; (32 + 4) : 2 = 18 girls; 1 000 000 : 85 000 = 11 rem. 65 000 — 11 books and 65 000 sum change.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Masala uch qismdan iborat: shart, savol, yechim; javob birlik bilan yoziladi.', 'Задача состоит из условия, вопроса и решения; ответ пишут с единицами.', 'A problem has a condition, a question and a solution; the answer comes with units.'),
      L('To‘rt bosqich: tushunish → reja → hisob → tekshiruv.', 'Четыре шага: понять → план → вычислить → проверить.', 'Four steps: understand → plan → calculate → check.'),
      L('Qisqa shart va chizma masalani tushunishga yordam beradi.', 'Краткое условие и рисунок помогают понять задачу.', 'A short summary and a sketch help you understand the problem.'),
      L('Murakkab masalada yordamchi savollar qo‘yiladi va oraliq natijalar yoziladi.', 'В составной задаче ставят вспомогательные вопросы и записывают промежуточные результаты.', 'In a multi-step problem, ask helper questions and record intermediate results.'),
      L('Asosiy bog‘lanishlar: narx · miqdor = qiymat, tezlik · vaqt = masofa, unumdorlik · vaqt = ish.', 'Главные связи: цена · количество = стоимость, скорость · время = расстояние, производительность · время = работа.', 'Key links: price · quantity = cost, speed · time = distance, rate · time = work.'),
      L('Kalit so‘zlarga emas, masalaning ma’nosiga tayaning va javobni doim tekshiring.', 'Опирайтесь на смысл задачи, а не на слова-подсказки, и всегда проверяйте ответ.', 'Rely on the meaning, not on key words, and always check the answer.')
    ] }
  ] });
})(this);
(function (root) { 'use strict'; var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '5-1';
  function F(a, b) { return '<sup>' + a + '</sup>/<sub>' + b + '</sub>'; }
  function M(w, a, b) { return w + F(a, b); }

  // ---------- t7. Bo'lishni kasr ko'rinishida ifodalash. Aralash sonlar ----------
  T.add(P, 't7', { sections: [
    { kind: 'intro', h: L('3 ta pitsa, 4 ta do‘st', '3 пиццы, 4 друга', '3 pizzas, 4 friends'), p: [
      L('To‘rt do‘st 3 ta pitsa buyurtma qildi. Har biriga qancha tegadi? Butun pitsa hammaga yetmaydi: 3 ni 4 ga butun songa bo‘lib bo‘lmaydi. Lekin pitsalarni bo‘laklarga kessak, adolatli taqsimlash mumkin: har bir pitsani 4 bo‘lakka kesamiz, jami 12 bo‘lak, har kimga 3 bo‘lakdan. Har bir bo‘lak — pitsaning to‘rtdan biri, demak har kimga ' + F(3, 4) + ' pitsa tegadi.', 'Четверо друзей заказали 3 пиццы. Сколько достанется каждому? Целой пиццы на всех не хватит: 3 не делится на 4 нацело. Но если разрезать пиццы на куски, можно поделить честно: каждую пиццу режем на 4 куска, всего 12 кусков, каждому по 3. Каждый кусок — четверть пиццы, значит, каждому достанется ' + F(3, 4) + ' пиццы.', 'Four friends ordered 3 pizzas. How much does each get? Not everyone can have a whole pizza: 3 does not divide by 4 exactly. But if we cut the pizzas, we can share fairly: cut each pizza into 4 slices, 12 slices in all, 3 for each friend. Each slice is a quarter, so each friend gets ' + F(3, 4) + ' of a pizza.'),
      L('Demak, <b>bo‘lishni kasr ko‘rinishida yozish mumkin</b>: 3 : 4 = ' + F(3, 4) + '. Kasr chizig‘i — bu bo‘lish belgisining boshqa ko‘rinishi! Bu oddiy g‘oya kasrlar haqidagi barcha bilimlarning poydevoridir.', 'Значит, <b>деление можно записать дробью</b>: 3 : 4 = ' + F(3, 4) + '. Дробная черта — это другой вид знака деления! Эта простая идея — фундамент всех знаний о дробях.', 'So <b>division can be written as a fraction</b>: 3 : 4 = ' + F(3, 4) + '. The fraction bar is just another form of the division sign! This simple idea is the foundation of everything about fractions.'),
      L('Agar pitsa ko‘p, odam kam bo‘lsa-chi? 7 ta pitsani 3 kishiga bo‘lsak, har kimga 2 tadan butun pitsa va yana bir bo‘lak tegadi. Bunday miqdorlarni yozish uchun <b>aralash sonlar</b> kerak bo‘ladi — ular ham shu mavzuda.', 'А если пицц много, а людей мало? Разделив 7 пицц на троих, каждый получит по 2 целых пиццы и ещё кусочек. Для записи таких величин нужны <b>смешанные числа</b> — они тоже в этой теме.', 'And if there are many pizzas and few people? Sharing 7 pizzas among 3, each gets 2 whole pizzas and a bit more. To write such amounts we need <b>mixed numbers</b> — also in this topic.')
    ] },
    { kind: 'def', h: L('Kasr, surat, maxraj', 'Дробь, числитель, знаменатель', 'Fraction, numerator, denominator'), p: [
      L('<b>Oddiy kasr</b> — ' + F('a', 'b') + ' ko‘rinishidagi yozuv, bunda a va b — natural sonlar. Chiziq ostidagi son — <b>maxraj</b>: butun nechta teng bo‘lakka bo‘linganini ko‘rsatadi. Chiziq ustidagi son — <b>surat</b>: shunday bo‘laklardan nechtasi olinganini ko‘rsatadi. ' + F(3, 4) + ' da maxraj 4, surat 3.', '<b>Обыкновенная дробь</b> — запись вида ' + F('a', 'b') + ', где a и b — натуральные числа. Число под чертой — <b>знаменатель</b>: показывает, на сколько равных частей разделили целое. Число над чертой — <b>числитель</b>: показывает, сколько таких частей взяли. В ' + F(3, 4) + ' знаменатель 4, числитель 3.', 'A <b>fraction</b> is written ' + F('a', 'b') + ', where a and b are whole numbers. The number below the bar is the <b>denominator</b>: how many equal parts the whole is cut into. The number above is the <b>numerator</b>: how many of those parts are taken. In ' + F(3, 4) + ' the denominator is 4, the numerator 3.'),
      L('<b>Asosiy xossa:</b> a : b = ' + F('a', 'b') + '. Har qanday bo‘lishni kasr ko‘rinishida, har qanday kasrni bo‘lish ko‘rinishida yozish mumkin. Maxraj hech qachon 0 bo‘lmaydi — chunki nolga bo‘lish mumkin emas.', '<b>Главное свойство:</b> a : b = ' + F('a', 'b') + '. Любое деление можно записать дробью, любую дробь — делением. Знаменатель никогда не бывает 0 — ведь на нуль делить нельзя.', '<b>Key fact:</b> a : b = ' + F('a', 'b') + '. Any division can be written as a fraction and any fraction as a division. The denominator is never 0, because we cannot divide by zero.'),
      L('<b>To‘g‘ri kasr</b> — surati maxrajidan kichik kasr: ' + F(3, 4) + ', ' + F(5, 8) + '. U har doim 1 dan kichik. <b>Noto‘g‘ri kasr</b> — surati maxrajiga teng yoki undan katta kasr: ' + F(7, 3) + ', ' + F(5, 5) + '. U 1 ga teng yoki 1 dan katta. <b>Aralash son</b> — butun qism va to‘g‘ri kasrdan iborat son: ' + M(2, 1, 3) + ' («ikki butun uchdan bir»), bu 2 + ' + F(1, 3) + ' degani.', '<b>Правильная дробь</b> — числитель меньше знаменателя: ' + F(3, 4) + ', ' + F(5, 8) + '. Она всегда меньше 1. <b>Неправильная дробь</b> — числитель равен знаменателю или больше его: ' + F(7, 3) + ', ' + F(5, 5) + '. Она равна 1 или больше 1. <b>Смешанное число</b> состоит из целой части и правильной дроби: ' + M(2, 1, 3) + ' («две целых одна третья»), это значит 2 + ' + F(1, 3) + '.', 'A <b>proper fraction</b> has a numerator smaller than its denominator: ' + F(3, 4) + ', ' + F(5, 8) + '. It is always less than 1. An <b>improper fraction</b> has a numerator equal to or larger than its denominator: ' + F(7, 3) + ', ' + F(5, 5) + '. It is 1 or more. A <b>mixed number</b> has a whole part and a proper fraction: ' + M(2, 1, 3) + ' (“two and one third”), meaning 2 + ' + F(1, 3) + '.')
    ] },
    { kind: 'history', h: L('Kasrlar tarixi', 'История дробей', 'The history of fractions'), p: [
      L('<b>Qadimgi Misr</b>da (4 000 yil oldin) kasrlar asosan surati 1 ga teng bo‘lgan — ' + F(1, 2) + ', ' + F(1, 3) + ', ' + F(1, 4) + ' kabi. Ular <b>birlik kasrlar</b> deyiladi. ' + F(3, 4) + ' ni misrliklar ' + F(1, 2) + ' + ' + F(1, 4) + ' deb yozgan. Faqat ' + F(2, 3) + ' uchun alohida belgi bo‘lgan. Rind papirusida 2 ni har xil sonlarga bo‘lishning katta jadvali bor.', 'В <b>Древнем Египте</b> (4 000 лет назад) дроби в основном имели числитель 1 — ' + F(1, 2) + ', ' + F(1, 3) + ', ' + F(1, 4) + '. Их называют <b>единичными дробями</b>. ' + F(3, 4) + ' египтяне записывали как ' + F(1, 2) + ' + ' + F(1, 4) + '. Отдельный знак был только для ' + F(2, 3) + '. В папирусе Ринда есть большая таблица деления 2 на разные числа.', 'In <b>Ancient Egypt</b> (4 000 years ago) fractions mostly had numerator 1 — ' + F(1, 2) + ', ' + F(1, 3) + ', ' + F(1, 4) + '. These are <b>unit fractions</b>. The Egyptians wrote ' + F(3, 4) + ' as ' + F(1, 2) + ' + ' + F(1, 4) + '. Only ' + F(2, 3) + ' had its own sign. The Rhind Papyrus has a big table of 2 divided by various numbers.'),
      L('<b>Hindiston</b>da VII asrda olim Braxmagupta kasrlarni bugungidek yozgan: surat tepada, maxraj pastda — lekin chiziqsiz. Kasr chizig‘ini XII asrda Shimoliy Afrikalik arab matematigi <b>al-Hassor</b> qo‘llay boshlagan. Hind va arab olimlarining ishlari <b>al-Xorazmiy</b> kitoblari orqali Yevropaga yetib borgan.', 'В <b>Индии</b> в VII веке учёный Брахмагупта записывал дроби почти как сегодня: числитель сверху, знаменатель снизу — но без черты. Дробную черту в XII веке стал использовать арабский математик из Северной Африки <b>аль-Хассар</b>. Работы индийских и арабских учёных дошли до Европы через книги <b>аль-Хорезми</b>.', 'In <b>India</b> in the 7th century the scholar Brahmagupta wrote fractions almost as we do: numerator on top, denominator below — but without a bar. The fraction bar was introduced in the 12th century by the North African Arab mathematician <b>al-Hassar</b>. Indian and Arab work reached Europe through the books of <b>al-Khwarizmi</b>.'),
      L('Rus tilida kasr «drob» — «sindirmoq» so‘zidan, lotincha «fractio» ham «sindirish» degani. O‘zbekcha «kasr» arabcha «kasr» — «sinish, bo‘lak» so‘zidan olingan. Hamma tillarda kasr — butunning «singan» bo‘lagi!', 'Русское «дробь» — от «дробить», латинское «fractio» тоже значит «ломание». Узбекское «kasr» — от арабского «kasr» — «излом, часть». Во всех языках дробь — «сломанная» часть целого!', 'The English “fraction” comes from Latin “fractio”, “a breaking”. The Russian “drob” comes from “to crush”, and the Uzbek “kasr” from the Arabic “kasr”, “a break, a piece”. In every language a fraction is a “broken” piece of a whole!')
    ] },
    { kind: 'rule', h: L('Aralash son va noto‘g‘ri kasr', 'Смешанное число и неправильная дробь', 'Mixed numbers and improper fractions'), p: [
      L('<b>Noto‘g‘ri kasrdan aralash songa.</b> Suratni maxrajga qoldiqli bo‘lamiz. To‘liqsiz bo‘linma — butun qism, qoldiq — yangi surat, maxraj o‘zgarmaydi: ' + F(7, 3) + ' → 7 : 3 = 2 (qoldiq 1) → ' + M(2, 1, 3) + '. Agar qoldiq 0 bo‘lsa, kasr natural songa teng: ' + F(12, 4) + ' = 3.', '<b>Из неправильной дроби в смешанное число.</b> Делим числитель на знаменатель с остатком. Неполное частное — целая часть, остаток — новый числитель, знаменатель не меняется: ' + F(7, 3) + ' → 7 : 3 = 2 (ост. 1) → ' + M(2, 1, 3) + '. Если остаток 0, дробь равна натуральному числу: ' + F(12, 4) + ' = 3.', '<b>Improper fraction to mixed number.</b> Divide the numerator by the denominator with remainder. The quotient is the whole part, the remainder the new numerator, the denominator stays: ' + F(7, 3) + ' → 7 : 3 = 2 rem. 1 → ' + M(2, 1, 3) + '. If the remainder is 0, the fraction is a whole number: ' + F(12, 4) + ' = 3.'),
      L('<b>Aralash sondan noto‘g‘ri kasrga.</b> Butun qismni maxrajga ko‘paytirib, suratni qo‘shamiz — bu yangi surat; maxraj o‘zgarmaydi: ' + M(2, 1, 3) + ' = ' + F('2 · 3 + 1', 3) + ' = ' + F(7, 3) + '. Ma’nosi: 2 butunda 6 ta uchdan bir bor, yana 1 ta qo‘shilsa — 7 ta.', '<b>Из смешанного числа в неправильную дробь.</b> Целую часть умножаем на знаменатель и прибавляем числитель — это новый числитель; знаменатель тот же: ' + M(2, 1, 3) + ' = ' + F('2 · 3 + 1', 3) + ' = ' + F(7, 3) + '. Смысл: в 2 целых 6 третей, и ещё 1 — всего 7.', '<b>Mixed number to improper fraction.</b> Multiply the whole part by the denominator and add the numerator — that is the new numerator; the denominator stays: ' + M(2, 1, 3) + ' = ' + F('2 · 3 + 1', 3) + ' = ' + F(7, 3) + '. Meaning: 2 wholes contain 6 thirds, plus 1 more makes 7.'),
      L('Har qanday natural sonni ham kasr ko‘rinishida yozish mumkin: 5 = ' + F(5, 1) + ' = ' + F(10, 2) + ' = ' + F(15, 3) + '. Butunni esa surati va maxraji teng kasr bilan: 1 = ' + F(4, 4) + ' = ' + F(9, 9) + '.', 'Любое натуральное число тоже можно записать дробью: 5 = ' + F(5, 1) + ' = ' + F(10, 2) + ' = ' + F(15, 3) + '. А единицу — дробью с равными числителем и знаменателем: 1 = ' + F(4, 4) + ' = ' + F(9, 9) + '.', 'Any whole number can be written as a fraction too: 5 = ' + F(5, 1) + ' = ' + F(10, 2) + ' = ' + F(15, 3) + '. And one whole as a fraction with equal top and bottom: 1 = ' + F(4, 4) + ' = ' + F(9, 9) + '.')
    ] },
    { kind: 'steps', h: L('Aylantirish bosqichlari', 'Шаги перевода', 'Conversion steps'), list: [
      L('<b>1.</b> Kasr to‘g‘rimi yoki noto‘g‘rimi — surat va maxrajni solishtiring. To‘g‘ri kasrni aylantirish kerak emas.', '<b>1.</b> Сравните числитель и знаменатель — правильная дробь или нет. Правильную дробь переводить не нужно.', '<b>1.</b> Compare numerator and denominator — proper or improper? A proper fraction needs no conversion.'),
      L('<b>2.</b> Noto‘g‘ri kasrda suratni maxrajga qoldiqli bo‘ling: ' + F(23, 5) + ' → 23 : 5 = 4 (qoldiq 3).', '<b>2.</b> В неправильной дроби разделите числитель на знаменатель с остатком: ' + F(23, 5) + ' → 23 : 5 = 4 (ост. 3).', '<b>2.</b> For an improper fraction, divide top by bottom with remainder: ' + F(23, 5) + ' → 23 : 5 = 4 rem. 3.'),
      L('<b>3.</b> Javobni yozing: butun qism 4, kasr ' + F(3, 5) + ' → ' + M(4, 3, 5) + '.', '<b>3.</b> Запишите ответ: целая часть 4, дробь ' + F(3, 5) + ' → ' + M(4, 3, 5) + '.', '<b>3.</b> Write the answer: whole part 4, fraction ' + F(3, 5) + ' → ' + M(4, 3, 5) + '.'),
      L('<b>4.</b> Tekshiring: 4 · 5 + 3 = 23 ✓ — teskari aylantirish asl kasrni berdi.', '<b>4.</b> Проверьте: 4 · 5 + 3 = 23 ✓ — обратный перевод дал исходную дробь.', '<b>4.</b> Check: 4 · 5 + 3 = 23 ✓ — converting back gives the original fraction.'),
      L('<b>5.</b> Qoldiq maxrajdan kichik ekanini tekshiring: aks holda bo‘lish xato bajarilgan.', '<b>5.</b> Убедитесь, что остаток меньше знаменателя: иначе деление выполнено неверно.', '<b>5.</b> Make sure the remainder is less than the denominator; otherwise the division was wrong.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('5 : 8 ni kasr ko‘rinishida yozing. Bu to‘g‘ri kasrmi?', 'Запишите 5 : 8 дробью. Это правильная дробь?', 'Write 5 : 8 as a fraction. Is it proper?'), s: L('5 : 8 = ' + F(5, 8) + '. Surat 5 maxraj 8 dan kichik — <b>to‘g‘ri kasr</b>, u 1 dan kichik. Ma’nosi: 5 ta tortni 8 kishiga bo‘lsak, har kimga tortning ' + F(5, 8) + ' qismi tegadi.', '5 : 8 = ' + F(5, 8) + '. Числитель 5 меньше знаменателя 8 — <b>правильная дробь</b>, меньше 1. Смысл: если 5 тортов разделить на 8 человек, каждому достанется ' + F(5, 8) + ' торта.', '5 : 8 = ' + F(5, 8) + '. The numerator 5 is less than the denominator 8 — a <b>proper fraction</b>, less than 1. Meaning: sharing 5 cakes among 8 people gives each ' + F(5, 8) + ' of a cake.') },
      { q: L(F(11, 4) + ' ni aralash son ko‘rinishida yozing.', 'Запишите ' + F(11, 4) + ' смешанным числом.', 'Write ' + F(11, 4) + ' as a mixed number.'), s: L('11 : 4 = 2 (qoldiq 3). Javob: <b>' + M(2, 3, 4) + '</b>. Tekshiruv: 2 · 4 + 3 = 11 ✓.', '11 : 4 = 2 (ост. 3). Ответ: <b>' + M(2, 3, 4) + '</b>. Проверка: 2 · 4 + 3 = 11 ✓.', '11 : 4 = 2 rem. 3. Answer: <b>' + M(2, 3, 4) + '</b>. Check: 2 · 4 + 3 = 11 ✓.') },
      { q: L(M(5, 2, 7) + ' ni noto‘g‘ri kasr ko‘rinishida yozing.', 'Запишите ' + M(5, 2, 7) + ' неправильной дробью.', 'Write ' + M(5, 2, 7) + ' as an improper fraction.'), s: L('5 · 7 + 2 = 37. Javob: <b>' + F(37, 7) + '</b>.', '5 · 7 + 2 = 37. Ответ: <b>' + F(37, 7) + '</b>.', '5 · 7 + 2 = 37. Answer: <b>' + F(37, 7) + '</b>.') },
      { q: L('17 m arqonni 5 ta teng bo‘lakka kesishdi. Har bir bo‘lak necha metr?', 'Верёвку 17 м разрезали на 5 равных частей. Сколько метров в каждой?', 'A 17 m rope is cut into 5 equal pieces. How long is each?'), s: L('17 : 5 = ' + F(17, 5) + ' m. Aralash son: 17 : 5 = 3 (qoldiq 2) → <b>' + M(3, 2, 5) + ' m</b>. Ya’ni har bir bo‘lak 3 m dan sal uzunroq.', '17 : 5 = ' + F(17, 5) + ' м. Смешанное число: 17 : 5 = 3 (ост. 2) → <b>' + M(3, 2, 5) + ' м</b>. То есть каждая часть чуть длиннее 3 м.', '17 : 5 = ' + F(17, 5) + ' m. As a mixed number: 17 : 5 = 3 rem. 2 → <b>' + M(3, 2, 5) + ' m</b>. So each piece is a little over 3 m.') }
    ] },
    { kind: 'table', h: L('Kasrlar turlari', 'Виды дробей', 'Kinds of fractions'), table: { head: [L('Turi', 'Вид', 'Kind'), L('Belgisi', 'Признак', 'Sign'), L('Misollar', 'Примеры', 'Examples'), L('1 bilan solishtirish', 'Сравнение с 1', 'Compared with 1')], rows: [
      [L('To‘g‘ri kasr', 'Правильная', 'Proper'), L('surat < maxraj', 'числитель < знаменатель', 'top < bottom'), F(1, 2) + ', ' + F(3, 7), '< 1'],
      [L('Noto‘g‘ri kasr', 'Неправильная', 'Improper'), L('surat ≥ maxraj', 'числитель ≥ знаменатель', 'top ≥ bottom'), F(9, 4) + ', ' + F(6, 6), '≥ 1'],
      [L('Aralash son', 'Смешанное число', 'Mixed number'), L('butun + to‘g‘ri kasr', 'целое + правильная дробь', 'whole + proper fraction'), M(1, 1, 2) + ', ' + M(4, 2, 5), '> 1'],
      [L('Natural son', 'Натуральное число', 'Whole number'), L('surat maxrajga bo‘linadi', 'числитель делится на знаменатель', 'top divisible by bottom'), F(8, 4) + ' = 2', '≥ 1']
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Surat va maxrajni almashtirib yozish.</b> 3 : 4 = ' + F(3, 4) + ', ' + F(4, 3) + ' emas. Bo‘linuvchi — tepada, bo‘luvchi — pastda.', '<b>Путают числитель и знаменатель.</b> 3 : 4 = ' + F(3, 4) + ', а не ' + F(4, 3) + '. Делимое — сверху, делитель — снизу.', '<b>Swapping top and bottom.</b> 3 : 4 = ' + F(3, 4) + ', not ' + F(4, 3) + '. The dividend goes on top, the divisor below.'),
      L('<b>Aralash sonda maxrajni o‘zgartirish.</b> ' + F(7, 3) + ' = ' + M(2, 1, 3) + ', ' + M(2, 1, 7) + ' emas. Maxraj o‘zgarmaydi.', '<b>Меняют знаменатель в смешанном числе.</b> ' + F(7, 3) + ' = ' + M(2, 1, 3) + ', а не ' + M(2, 1, 7) + '. Знаменатель не меняется.', '<b>Changing the denominator.</b> ' + F(7, 3) + ' = ' + M(2, 1, 3) + ', not ' + M(2, 1, 7) + '. The denominator stays.'),
      L('<b>Teskari aylantirishda qo‘shishni unutish.</b> ' + M(3, 2, 5) + ' = ' + F(17, 5) + ', ' + F(15, 5) + ' emas: 3 · 5 ga suratni qo‘shish kerak.', '<b>Забывают прибавить числитель.</b> ' + M(3, 2, 5) + ' = ' + F(17, 5) + ', а не ' + F(15, 5) + ': к 3 · 5 надо прибавить числитель.', '<b>Forgetting to add the numerator.</b> ' + M(3, 2, 5) + ' = ' + F(17, 5) + ', not ' + F(15, 5) + ': add the numerator to 3 · 5.'),
      L('<b>Butun qism va suratni ko‘paytirish.</b> ' + M(2, 1, 4) + ' — bu 2 + ' + F(1, 4) + ', 2 · ' + F(1, 4) + ' emas!', '<b>Умножают целую часть на дробь.</b> ' + M(2, 1, 4) + ' — это 2 + ' + F(1, 4) + ', а не 2 · ' + F(1, 4) + '!', '<b>Reading the mixed number as a product.</b> ' + M(2, 1, 4) + ' means 2 + ' + F(1, 4) + ', not 2 · ' + F(1, 4) + '!'),
      L('<b>Qoldiq maxrajdan katta.</b> ' + F(14, 4) + ' = ' + M(2, 6, 4) + ' — xato, chunki ' + F(6, 4) + ' noto‘g‘ri kasr. To‘g‘risi: ' + M(3, 2, 4) + '.', '<b>Остаток больше знаменателя.</b> ' + F(14, 4) + ' = ' + M(2, 6, 4) + ' — ошибка, ведь ' + F(6, 4) + ' — неправильная дробь. Правильно: ' + M(3, 2, 4) + '.', '<b>Remainder bigger than the denominator.</b> ' + F(14, 4) + ' = ' + M(2, 6, 4) + ' is wrong, since ' + F(6, 4) + ' is improper. Correct: ' + M(3, 2, 4) + '.')
    ] },
    { kind: 'life', h: L('Hayotda kasrlar', 'Дроби в жизни', 'Fractions in real life'), p: [
      L('<b>Oshxonada.</b> Retseptlarda «' + F(1, 2) + ' stakan shakar», «' + M(1, 1, 2) + ' qoshiq tuz» deb yoziladi. Agar retsept 4 kishiga mo‘ljallangan bo‘lsa-yu, siz 3 kishiga pishirsangiz, har bir mahsulotni ' + F(3, 4) + ' miqdorda olasiz.', '<b>На кухне.</b> В рецептах пишут «' + F(1, 2) + ' стакана сахара», «' + M(1, 1, 2) + ' ложки соли». Если рецепт на 4 человек, а вы готовите на 3, берёте каждого продукта ' + F(3, 4) + '.', '<b>In the kitchen.</b> Recipes say “' + F(1, 2) + ' cup of sugar” or “' + M(1, 1, 2) + ' spoons of salt”. If a recipe serves 4 and you cook for 3, use ' + F(3, 4) + ' of each ingredient.'),
      L('<b>Vaqt.</b> Chorak soat — ' + F(1, 4) + ' soat = 15 daqiqa; yarim soat — ' + F(1, 2) + ' soat = 30 daqiqa. «Bir yarim soat» — bu ' + M(1, 1, 2) + ' soat = 90 daqiqa. Futbol o‘yinining har bir taymi — o‘yinning ' + F(1, 2) + ' qismi.', '<b>Время.</b> Четверть часа — ' + F(1, 4) + ' часа = 15 минут; полчаса — ' + F(1, 2) + ' часа = 30 минут. «Полтора часа» — это ' + M(1, 1, 2) + ' часа = 90 минут. Каждый тайм футбольного матча — ' + F(1, 2) + ' игры.', '<b>Time.</b> A quarter of an hour is ' + F(1, 4) + ' h = 15 minutes; half an hour is ' + F(1, 2) + ' h = 30 minutes. “An hour and a half” is ' + M(1, 1, 2) + ' h = 90 minutes. Each half of a football match is ' + F(1, 2) + ' of the game.'),
      L('<b>Musiqa va do‘kon.</b> Musiqada notalar butun, ' + F(1, 2) + ', ' + F(1, 4) + ', ' + F(1, 8) + ' davomiylikka ega. Do‘konda esa «' + F(1, 2) + ' narxida» chegirma — narxning yarmi demak.', '<b>Музыка и магазин.</b> В музыке ноты бывают целые, ' + F(1, 2) + ', ' + F(1, 4) + ', ' + F(1, 8) + ' по длительности. А в магазине скидка «за ' + F(1, 2) + ' цены» — значит, за половину.', '<b>Music and shopping.</b> In music, notes last a whole, ' + F(1, 2) + ', ' + F(1, 4) + ' or ' + F(1, 8) + ' beat-length. In a shop, “' + F(1, 2) + ' price” means half the price.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Qadimgi Misrda «Horus ko‘zi» belgisining qismlari ' + F(1, 2) + ', ' + F(1, 4) + ', ' + F(1, 8) + ', ' + F(1, 16) + ', ' + F(1, 32) + ', ' + F(1, 64) + ' kasrlarini bildirgan. Ularning yig‘indisi ' + F(63, 64) + ' — 1 ga juda yaqin, lekin teng emas!', 'В Древнем Египте части знака «Око Гора» означали дроби ' + F(1, 2) + ', ' + F(1, 4) + ', ' + F(1, 8) + ', ' + F(1, 16) + ', ' + F(1, 32) + ', ' + F(1, 64) + '. Их сумма — ' + F(63, 64) + ': очень близко к 1, но не равно!', 'In Ancient Egypt the parts of the “Eye of Horus” sign stood for ' + F(1, 2) + ', ' + F(1, 4) + ', ' + F(1, 8) + ', ' + F(1, 16) + ', ' + F(1, 32) + ', ' + F(1, 64) + '. They add up to ' + F(63, 64) + ' — very close to 1, but not equal!'),
      L('Bobilliklar 60 lik kasrlardan foydalangan. Bugungi soat va daqiqalar ham shundan: 1 daqiqa — soatning ' + F(1, 60) + ' qismi.', 'Вавилоняне пользовались шестидесятеричными дробями. Отсюда и наши часы и минуты: 1 минута — это ' + F(1, 60) + ' часа.', 'The Babylonians used base-60 fractions. That is where our hours and minutes come from: 1 minute is ' + F(1, 60) + ' of an hour.'),
      L('Bir xil kasrni cheksiz ko‘p usulda yozish mumkin: ' + F(1, 2) + ' = ' + F(2, 4) + ' = ' + F(50, 100) + ' = ' + F(500, 1000) + '…', 'Одну и ту же дробь можно записать бесконечным числом способов: ' + F(1, 2) + ' = ' + F(2, 4) + ' = ' + F(50, 100) + ' = ' + F(500, 1000) + '…', 'The same fraction can be written in infinitely many ways: ' + F(1, 2) + ' = ' + F(2, 4) + ' = ' + F(50, 100) + ' = ' + F(500, 1000) + '…')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('Maxraji 5 bo‘lgan barcha to‘g‘ri kasrlarni yozing.', 'Запишите все правильные дроби со знаменателем 5.', 'Write all proper fractions with denominator 5.'),
      L(F(29, 6) + ' ni aralash songa, ' + M(7, 3, 8) + ' ni noto‘g‘ri kasrga aylantiring.', 'Переведите ' + F(29, 6) + ' в смешанное число, ' + M(7, 3, 8) + ' — в неправильную дробь.', 'Convert ' + F(29, 6) + ' to a mixed number and ' + M(7, 3, 8) + ' to an improper fraction.'),
      L(F('x', 9) + ' noto‘g‘ri kasr bo‘lishi uchun x eng kami bilan qanday bo‘lishi kerak?', 'Каким наименьшим должно быть x, чтобы ' + F('x', 9) + ' была неправильной дробью?', 'What is the smallest x making ' + F('x', 9) + ' improper?')
    ], after: [
      L('Javoblar: ' + F(1, 5) + ', ' + F(2, 5) + ', ' + F(3, 5) + ', ' + F(4, 5) + '; ' + M(4, 5, 6) + ' va ' + F(59, 8) + '; x = 9.', 'Ответы: ' + F(1, 5) + ', ' + F(2, 5) + ', ' + F(3, 5) + ', ' + F(4, 5) + '; ' + M(4, 5, 6) + ' и ' + F(59, 8) + '; x = 9.', 'Answers: ' + F(1, 5) + ', ' + F(2, 5) + ', ' + F(3, 5) + ', ' + F(4, 5) + '; ' + M(4, 5, 6) + ' and ' + F(59, 8) + '; x = 9.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Bo‘lishni kasr bilan yozish mumkin: a : b = ' + F('a', 'b') + '; maxraj 0 bo‘lmaydi.', 'Деление можно записать дробью: a : b = ' + F('a', 'b') + '; знаменатель не равен 0.', 'Division can be written as a fraction: a : b = ' + F('a', 'b') + '; the denominator is never 0.'),
      L('Maxraj — butun nechta bo‘lakka bo‘linganini, surat — nechta bo‘lak olinganini ko‘rsatadi.', 'Знаменатель — на сколько частей делят целое, числитель — сколько частей взяли.', 'The denominator is how many parts the whole is cut into; the numerator is how many are taken.'),
      L('To‘g‘ri kasr < 1, noto‘g‘ri kasr ≥ 1.', 'Правильная дробь < 1, неправильная ≥ 1.', 'A proper fraction is < 1; an improper one is ≥ 1.'),
      L('Noto‘g‘ri kasr → aralash son: suratni maxrajga qoldiqli bo‘lamiz.', 'Неправильная дробь → смешанное число: делим числитель на знаменатель с остатком.', 'Improper → mixed: divide the numerator by the denominator with remainder.'),
      L('Aralash son → noto‘g‘ri kasr: butun · maxraj + surat.', 'Смешанное число → неправильная дробь: целое · знаменатель + числитель.', 'Mixed → improper: whole · denominator + numerator.'),
      L('Har ikki aylantirishda ham maxraj o‘zgarmaydi.', 'При обоих переводах знаменатель не меняется.', 'In both conversions the denominator stays the same.')
    ] }
  ] });

  // ---------- t8. Oddiy kasrni o'nli kasrga aylantirish ----------
  T.add(P, 't8', { sections: [
    { kind: 'intro', h: L('Vergulli sonlar', 'Числа с запятой', 'Numbers with a decimal point'), p: [
      L('Do‘kondagi tarozida «0,75 kg» yozuvi, termometrda «36,6 °C», yugurish natijasida «12,4 soniya». Bu — <b>o‘nli kasrlar</b>. Ular oddiy kasrlarning maxsus ko‘rinishi: maxraji 10, 100, 1000 bo‘lgan kasrlar vergul yordamida qisqa yoziladi. ' + F(75, 100) + ' o‘rniga 0,75.', 'На весах в магазине «0,75 кг», на градуснике «36,6 °C», в результатах забега «12,4 секунды». Это <b>десятичные дроби</b>. Они — особый вид обыкновенных дробей: дроби со знаменателем 10, 100, 1000 коротко записывают с помощью запятой. Вместо ' + F(75, 100) + ' — 0,75.', 'A shop scale shows “0.75 kg”, a thermometer “36.6 °C”, a race result “12.4 seconds”. These are <b>decimals</b>. They are a special form of fractions: fractions with denominator 10, 100 or 1000 are written briefly with a decimal point. Instead of ' + F(75, 100) + ' we write 0.75.'),
      L('Nega bu kerak? Chunki o‘nli kasrlarni taqqoslash, qo‘shish va kalkulyatorga kiritish ancha oson. ' + F(3, 4) + ' va ' + F(7, 10) + ' — qaysi biri katta? O‘nli kasrda darhol ko‘rinadi: 0,75 > 0,7. Bu mavzuda oddiy kasrni o‘nli kasrga aylantirishning ikki usulini o‘rganamiz.', 'Зачем это нужно? Десятичные дроби гораздо проще сравнивать, складывать и вводить в калькулятор. ' + F(3, 4) + ' и ' + F(7, 10) + ' — что больше? В десятичном виде сразу видно: 0,75 > 0,7. В этой теме изучим два способа перевода обыкновенной дроби в десятичную.', 'Why bother? Decimals are much easier to compare, add and type into a calculator. ' + F(3, 4) + ' or ' + F(7, 10) + ' — which is bigger? As decimals it is obvious: 0.75 > 0.7. In this topic we learn two ways to turn a fraction into a decimal.'),
      L('Eslatma: O‘zbekiston va Rossiyada kasr qismi <b>vergul</b> bilan (0,75), ingliz tilida so‘zlashuvchi mamlakatlarda <b>nuqta</b> bilan (0.75) ajratiladi. Ma’nosi bir xil.', 'Заметка: в Узбекистане и России дробную часть отделяют <b>запятой</b> (0,75), в англоязычных странах — <b>точкой</b> (0.75). Смысл одинаков.', 'Note: in Uzbekistan and Russia the fractional part is separated by a <b>comma</b> (0,75), in English-speaking countries by a <b>point</b> (0.75). The meaning is the same.')
    ] },
    { kind: 'def', h: L('O‘nli kasr nima?', 'Что такое десятичная дробь?', 'What is a decimal?'), p: [
      L('<b>O‘nli kasr</b> — maxraji 10, 100, 1000 … bo‘lgan kasrning vergul bilan yozilishi. Verguldan chapda — <b>butun qism</b>, o‘ngda — <b>kasr qism</b>. Verguldan keyingi birinchi raqam — <b>o‘ndan birlar</b>, ikkinchisi — <b>yuzdan birlar</b>, uchinchisi — <b>mingdan birlar</b>.', '<b>Десятичная дробь</b> — запись с запятой дроби со знаменателем 10, 100, 1000 … Слева от запятой — <b>целая часть</b>, справа — <b>дробная часть</b>. Первая цифра после запятой — <b>десятые</b>, вторая — <b>сотые</b>, третья — <b>тысячные</b>.', 'A <b>decimal</b> is a fraction with denominator 10, 100, 1000 … written with a point. Left of the point is the <b>whole part</b>, right of it the <b>fractional part</b>. The first digit after the point is <b>tenths</b>, the second <b>hundredths</b>, the third <b>thousandths</b>.'),
      L('Asosiy qoida: <b>verguldan keyin nechta raqam bo‘lsa, maxrajda shuncha nol bo‘ladi</b>. 0,7 = ' + F(7, 10) + ' (bitta raqam — bitta nol); 0,75 = ' + F(75, 100) + ' (ikkita raqam — ikkita nol); 2,125 = ' + M(2, 125, 1000) + '.', 'Главное правило: <b>сколько цифр после запятой, столько нулей в знаменателе</b>. 0,7 = ' + F(7, 10) + ' (одна цифра — один нуль); 0,75 = ' + F(75, 100) + ' (две цифры — два нуля); 2,125 = ' + M(2, 125, 1000) + '.', 'Main rule: <b>as many digits after the point, as many zeros in the denominator</b>. 0.7 = ' + F(7, 10) + ' (one digit, one zero); 0.75 = ' + F(75, 100) + ' (two digits, two zeros); 2.125 = ' + M(2, 125, 1000) + '.'),
      L('<b>Kasrning asosiy xossasi:</b> kasrning surat va maxrajini bir xil natural songa ko‘paytirsak (yoki bo‘lsak), kasrning qiymati o‘zgarmaydi: ' + F(3, 4) + ' = ' + F('3 · 25', '4 · 25') + ' = ' + F(75, 100) + '. Aynan shu xossa oddiy kasrni o‘nli kasrga aylantirishga imkon beradi.', '<b>Основное свойство дроби:</b> если числитель и знаменатель умножить (или разделить) на одно и то же натуральное число, значение дроби не изменится: ' + F(3, 4) + ' = ' + F('3 · 25', '4 · 25') + ' = ' + F(75, 100) + '. Именно это свойство позволяет переводить обыкновенную дробь в десятичную.', '<b>The basic property of fractions:</b> multiplying (or dividing) the numerator and denominator by the same whole number does not change the value: ' + F(3, 4) + ' = ' + F('3 · 25', '4 · 25') + ' = ' + F(75, 100) + '. This is exactly what lets us turn a fraction into a decimal.')
    ] },
    { kind: 'history', h: L('O‘nli kasrlar tarixi', 'История десятичных дробей', 'The history of decimals'), p: [
      L('O‘nli kasrlarning g‘oyasi Xitoyda qadimdan ma’lum bo‘lgan. Ammo ularni to‘liq tizim sifatida bayon qilgan olim — <b>Jamshid al-Koshiy</b>. U 1427-yilda Samarqandda, Ulug‘bek rasadxonasida ishlab yurgan paytida «Arifmetika kaliti» kitobini yozdi va o‘nli kasrlar bilan barcha amallarni tushuntirdi. Al-Koshiy π sonini verguldan keyin 16 ta raqam aniqligida hisoblagan — bu rekord 150 yildan ortiq saqlangan!', 'Идея десятичных дробей давно была известна в Китае. Но учёный, изложивший их как полную систему, — <b>Джамшид аль-Каши</b>. В 1427 году, работая в Самарканде в обсерватории Улугбека, он написал книгу «Ключ арифметики» и объяснил все действия с десятичными дробями. Аль-Каши вычислил число π с точностью 16 знаков после запятой — этот рекорд держался более 150 лет!', 'The idea of decimals was known long ago in China. But the scholar who set them out as a complete system was <b>Jamshid al-Kashi</b>. In 1427, working in Samarkand at Ulugh Beg’s observatory, he wrote “The Key to Arithmetic” and explained every operation with decimals. Al-Kashi calculated π to 16 decimal places — a record that stood for more than 150 years!'),
      L('Yevropada o‘nli kasrlarni 1585-yilda gollandiyalik muhandis <b>Simon Stevin</b> ommalashtirdi. U «O‘ndan bir» degan kichik kitob yozib, savdogarlar va soliq yig‘uvchilarga o‘nli kasrlardan foydalanishni maslahat berdi. Vergul (yoki nuqta) esa XVII asrda, shotlandiyalik olim Jon Neper tufayli keng tarqaldi.', 'В Европе десятичные дроби в 1585 году популяризировал голландский инженер <b>Симон Стевин</b>. Он написал небольшую книгу «Десятая» и советовал торговцам и сборщикам налогов пользоваться десятичными дробями. А запятая (или точка) широко распространилась в XVII веке благодаря шотландскому учёному Джону Неперу.', 'In Europe decimals were popularised in 1585 by the Dutch engineer <b>Simon Stevin</b>. He wrote a little book, “The Tenth”, urging merchants and tax collectors to use decimals. The decimal point (or comma) spread widely in the 17th century thanks to the Scottish scholar John Napier.'),
      L('Shunday qilib, bugun har bir kalkulyatorda ko‘radigan vergulli sonlarning tarixi Samarqand bilan chambarchas bog‘liq!', 'Так что история чисел с запятой, которые мы видим сегодня на каждом калькуляторе, тесно связана с Самаркандом!', 'So the history of the decimal numbers we see on every calculator today is closely tied to Samarkand!')
    ] },
    { kind: 'rule', h: L('Ikki usul', 'Два способа', 'Two methods'), p: [
      L('<b>1-usul: maxrajni 10, 100, 1000 ga keltirish.</b> Maxrajni 10, 100 yoki 1000 ga aylantiradigan sonni topamiz va surat bilan maxrajni shunga ko‘paytiramiz: ' + F(2, 5) + ' = ' + F('2 · 2', '5 · 2') + ' = ' + F(4, 10) + ' = 0,4. ' + F(3, 4) + ' = ' + F('3 · 25', '4 · 25') + ' = ' + F(75, 100) + ' = 0,75. ' + F(7, 8) + ' = ' + F('7 · 125', '8 · 125') + ' = ' + F(875, 1000) + ' = 0,875.', '<b>Способ 1: приведение знаменателя к 10, 100, 1000.</b> Находим число, которое превращает знаменатель в 10, 100 или 1000, и умножаем на него числитель и знаменатель: ' + F(2, 5) + ' = ' + F('2 · 2', '5 · 2') + ' = ' + F(4, 10) + ' = 0,4. ' + F(3, 4) + ' = ' + F('3 · 25', '4 · 25') + ' = ' + F(75, 100) + ' = 0,75. ' + F(7, 8) + ' = ' + F('7 · 125', '8 · 125') + ' = ' + F(875, 1000) + ' = 0,875.', '<b>Method 1: make the denominator 10, 100 or 1000.</b> Find the number that turns the denominator into 10, 100 or 1000 and multiply top and bottom by it: ' + F(2, 5) + ' = ' + F('2 · 2', '5 · 2') + ' = ' + F(4, 10) + ' = 0.4. ' + F(3, 4) + ' = ' + F('3 · 25', '4 · 25') + ' = ' + F(75, 100) + ' = 0.75. ' + F(7, 8) + ' = ' + F('7 · 125', '8 · 125') + ' = ' + F(875, 1000) + ' = 0.875.'),
      L('<b>2-usul: suratni maxrajga bo‘lish.</b> Kasr — bu bo‘lish, shuning uchun 3 : 4 ni burchak usulida bo‘lamiz: 3 da 4 sig‘maydi → 0 butun, vergul qo‘yamiz; 30 : 4 = 7 (qoldiq 2); 20 : 4 = 5. Javob: 0,75.', '<b>Способ 2: деление числителя на знаменатель.</b> Дробь — это деление, поэтому делим 3 : 4 уголком: 3 не делится на 4 → 0 целых, ставим запятую; 30 : 4 = 7 (ост. 2); 20 : 4 = 5. Ответ: 0,75.', '<b>Method 2: divide the numerator by the denominator.</b> A fraction is a division, so do 3 : 4 by long division: 4 does not go into 3 → 0 wholes, put the point; 30 : 4 = 7 rem. 2; 20 : 4 = 5. Answer: 0.75.'),
      L('Qaysi kasrlar «chiroyli» o‘nli kasrga aylanadi? Maxraji faqat 2 va 5 ko‘paytuvchilaridan tuzilgan kasrlar: 2, 4, 5, 8, 10, 20, 25, 50… ' + F(1, 3) + ' esa 0,333… — cheksiz davom etadi. Bunday kasrlarni yuqori sinflarda o‘rganasiz.', 'Какие дроби превращаются в «красивую» десятичную? Те, у которых знаменатель состоит только из множителей 2 и 5: 2, 4, 5, 8, 10, 20, 25, 50… А ' + F(1, 3) + ' = 0,333… — продолжается бесконечно. Такие дроби вы изучите в старших классах.', 'Which fractions become “neat” decimals? Those whose denominator is built only from factors 2 and 5: 2, 4, 5, 8, 10, 20, 25, 50… But ' + F(1, 3) + ' is 0.333… going on forever. You will study such fractions in later grades.')
    ] },
    { kind: 'steps', h: L('1-usul bosqichlari', 'Шаги способа 1', 'Steps for method 1'), list: [
      L('<b>1.</b> Maxrajga qarang: 20.', '<b>1.</b> Посмотрите на знаменатель: 20.', '<b>1.</b> Look at the denominator: 20.'),
      L('<b>2.</b> Eng yaqin 10, 100 yoki 1000 ni tanlang, unga maxraj bo‘linishi kerak: 100 : 20 = 5.', '<b>2.</b> Выберите ближайшее 10, 100 или 1000, которое делится на знаменатель: 100 : 20 = 5.', '<b>2.</b> Choose the nearest 10, 100 or 1000 that the denominator divides: 100 : 20 = 5.'),
      L('<b>3.</b> Surat va maxrajni 5 ga ko‘paytiring: ' + F(7, 20) + ' = ' + F(35, 100) + '.', '<b>3.</b> Умножьте числитель и знаменатель на 5: ' + F(7, 20) + ' = ' + F(35, 100) + '.', '<b>3.</b> Multiply top and bottom by 5: ' + F(7, 20) + ' = ' + F(35, 100) + '.'),
      L('<b>4.</b> Vergul bilan yozing: maxrajda 2 ta nol — verguldan keyin 2 ta raqam: 0,35.', '<b>4.</b> Запишите с запятой: в знаменателе 2 нуля — после запятой 2 цифры: 0,35.', '<b>4.</b> Write with a point: 2 zeros in the denominator, 2 digits after the point: 0.35.'),
      L('<b>5.</b> Raqamlar yetmasa, oldiga nol qo‘ying: ' + F(3, 100) + ' = 0,03 (0,3 emas!).', '<b>5.</b> Если цифр не хватает, допишите нули впереди: ' + F(3, 100) + ' = 0,03 (а не 0,3!).', '<b>5.</b> If there are too few digits, add zeros in front: ' + F(3, 100) + ' = 0.03 (not 0.3!).')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L(F(1, 5) + ' ni o‘nli kasrga aylantiring.', 'Переведите ' + F(1, 5) + ' в десятичную дробь.', 'Convert ' + F(1, 5) + ' to a decimal.'), s: L('10 : 5 = 2. ' + F(1, 5) + ' = ' + F(2, 10) + ' = <b>0,2</b>.', '10 : 5 = 2. ' + F(1, 5) + ' = ' + F(2, 10) + ' = <b>0,2</b>.', '10 : 5 = 2. ' + F(1, 5) + ' = ' + F(2, 10) + ' = <b>0.2</b>.') },
      { q: L(F(9, 25) + ' ni o‘nli kasrga aylantiring.', 'Переведите ' + F(9, 25) + ' в десятичную дробь.', 'Convert ' + F(9, 25) + ' to a decimal.'), s: L('100 : 25 = 4. ' + F(9, 25) + ' = ' + F(36, 100) + ' = <b>0,36</b>.', '100 : 25 = 4. ' + F(9, 25) + ' = ' + F(36, 100) + ' = <b>0,36</b>.', '100 : 25 = 4. ' + F(9, 25) + ' = ' + F(36, 100) + ' = <b>0.36</b>.') },
      { q: L(M(3, 1, 4) + ' ni o‘nli kasrga aylantiring.', 'Переведите ' + M(3, 1, 4) + ' в десятичную дробь.', 'Convert ' + M(3, 1, 4) + ' to a decimal.'), s: L('Butun qism 3 o‘zgarmaydi. ' + F(1, 4) + ' = ' + F(25, 100) + ' = 0,25. Javob: <b>3,25</b>.', 'Целая часть 3 не меняется. ' + F(1, 4) + ' = ' + F(25, 100) + ' = 0,25. Ответ: <b>3,25</b>.', 'The whole part 3 stays. ' + F(1, 4) + ' = ' + F(25, 100) + ' = 0.25. Answer: <b>3.25</b>.') },
      { q: L(F(3, 8) + ' ni bo‘lish usulida o‘nli kasrga aylantiring.', 'Переведите ' + F(3, 8) + ' в десятичную дробь делением.', 'Convert ' + F(3, 8) + ' to a decimal by division.'), s: L('3 : 8 → 0 butun. 30 : 8 = 3 (qoldiq 6); 60 : 8 = 7 (qoldiq 4); 40 : 8 = 5. Javob: <b>0,375</b>. Tekshiruv: ' + F(375, 1000) + ' ni 125 ga qisqartirsak, ' + F(3, 8) + ' ✓.', '3 : 8 → 0 целых. 30 : 8 = 3 (ост. 6); 60 : 8 = 7 (ост. 4); 40 : 8 = 5. Ответ: <b>0,375</b>. Проверка: сократив ' + F(375, 1000) + ' на 125, получим ' + F(3, 8) + ' ✓.', '3 : 8 → 0 wholes. 30 : 8 = 3 rem. 6; 60 : 8 = 7 rem. 4; 40 : 8 = 5. Answer: <b>0.375</b>. Check: dividing ' + F(375, 1000) + ' by 125 top and bottom gives ' + F(3, 8) + ' ✓.') },
      { q: L('Qaysi biri katta: ' + F(3, 5) + ' yoki ' + F(13, 20) + '?', 'Что больше: ' + F(3, 5) + ' или ' + F(13, 20) + '?', 'Which is bigger: ' + F(3, 5) + ' or ' + F(13, 20) + '?'), s: L(F(3, 5) + ' = 0,6 = 0,60; ' + F(13, 20) + ' = ' + F(65, 100) + ' = 0,65. 0,65 > 0,60, demak <b>' + F(13, 20) + ' katta</b>.', F(3, 5) + ' = 0,6 = 0,60; ' + F(13, 20) + ' = ' + F(65, 100) + ' = 0,65. 0,65 > 0,60, значит <b>' + F(13, 20) + ' больше</b>.', F(3, 5) + ' = 0.6 = 0.60; ' + F(13, 20) + ' = ' + F(65, 100) + ' = 0.65. 0.65 > 0.60, so <b>' + F(13, 20) + ' is bigger</b>.') }
    ] },
    { kind: 'table', h: L('Yodlab olish foydali', 'Полезно запомнить', 'Worth memorising'), table: { head: [L('Oddiy kasr', 'Обыкновенная', 'Fraction'), L('O‘nli kasr', 'Десятичная', 'Decimal'), L('Oddiy kasr', 'Обыкновенная', 'Fraction'), L('O‘nli kasr', 'Десятичная', 'Decimal')], rows: [
      [F(1, 2), L('0,5', '0,5', '0.5'), F(1, 4), L('0,25', '0,25', '0.25')],
      [F(3, 4), L('0,75', '0,75', '0.75'), F(1, 5), L('0,2', '0,2', '0.2')],
      [F(2, 5), L('0,4', '0,4', '0.4'), F(1, 8), L('0,125', '0,125', '0.125')],
      [F(1, 10), L('0,1', '0,1', '0.1'), F(1, 20), L('0,05', '0,05', '0.05')],
      [F(1, 25), L('0,04', '0,04', '0.04'), F(1, 50), L('0,02', '0,02', '0.02')]
    ] }, after: [
      L('Bu jadvaldan foydalanib, boshqa kasrlarni ham tez topish mumkin: ' + F(3, 5) + ' = 3 · 0,2 = 0,6; ' + F(5, 8) + ' = 5 · 0,125 = 0,625.', 'С помощью этой таблицы легко находить и другие дроби: ' + F(3, 5) + ' = 3 · 0,2 = 0,6; ' + F(5, 8) + ' = 5 · 0,125 = 0,625.', 'Using this table you can quickly find others: ' + F(3, 5) + ' = 3 · 0.2 = 0.6; ' + F(5, 8) + ' = 5 · 0.125 = 0.625.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Surat va maxrajni vergul bilan yozish.</b> ' + F(3, 4) + ' ≠ 3,4! Bu eng ko‘p uchraydigan xato. ' + F(3, 4) + ' = 0,75.', '<b>Записывают числитель и знаменатель через запятую.</b> ' + F(3, 4) + ' ≠ 3,4! Это самая частая ошибка. ' + F(3, 4) + ' = 0,75.', '<b>Writing top and bottom with a point between.</b> ' + F(3, 4) + ' ≠ 3.4! The most common mistake. ' + F(3, 4) + ' = 0.75.'),
      L('<b>Nolni tushirib qoldirish.</b> ' + F(7, 100) + ' = 0,07, 0,7 emas. Maxrajda 2 ta nol — verguldan keyin 2 ta raqam.', '<b>Теряют нуль.</b> ' + F(7, 100) + ' = 0,07, а не 0,7. В знаменателе 2 нуля — после запятой 2 цифры.', '<b>Dropping a zero.</b> ' + F(7, 100) + ' = 0.07, not 0.7. Two zeros below, two digits after the point.'),
      L('<b>Faqat maxrajni ko‘paytirish.</b> ' + F(3, 4) + ' = ' + F(3, 100) + ' — xato! Surat ham 25 ga ko‘paytiriladi.', '<b>Умножают только знаменатель.</b> ' + F(3, 4) + ' = ' + F(3, 100) + ' — ошибка! Числитель тоже умножаем на 25.', '<b>Multiplying only the denominator.</b> ' + F(3, 4) + ' = ' + F(3, 100) + ' is wrong! Multiply the numerator by 25 too.'),
      L('<b>Uzun kasr katta deb o‘ylash.</b> 0,125 > 0,5 emas! Raqamlarni xona bo‘yicha solishtiring: 0,500 > 0,125.', '<b>Думают, что длинная дробь больше.</b> 0,125 не больше 0,5! Сравнивайте по разрядам: 0,500 > 0,125.', '<b>Thinking a longer decimal is bigger.</b> 0.125 is not bigger than 0.5! Compare place by place: 0.500 > 0.125.')
    ] },
    { kind: 'life', h: L('Hayotda o‘nli kasrlar', 'Десятичные дроби в жизни', 'Decimals in real life'), p: [
      L('<b>Narxlar va tarozi.</b> Bozorda «chorak kilo» (' + F(1, 4) + ' kg) so‘rasangiz, tarozida 0,25 kg ko‘rinadi. Yarim kilo — 0,5 kg. Elektron tarozilar, kassalar va bank dasturlari faqat o‘nli kasrlar bilan ishlaydi.', '<b>Цены и весы.</b> Если на базаре попросить «четверть кило» (' + F(1, 4) + ' кг), на весах будет 0,25 кг. Полкило — 0,5 кг. Электронные весы, кассы и банковские программы работают только с десятичными дробями.', '<b>Prices and scales.</b> Ask for “a quarter kilo” (' + F(1, 4) + ' kg) at the market and the scale shows 0.25 kg. Half a kilo is 0.5 kg. Electronic scales, tills and banking software work only with decimals.'),
      L('<b>Sport.</b> 100 metrga yugurishda vaqt soniyaning yuzdan bir ulushigacha o‘lchanadi: 9,58 soniya — Usain Boltning jahon rekordi (2009). Gimnastikada baholar 14,733 kabi mingdan birlargacha hisoblanadi.', '<b>Спорт.</b> В беге на 100 метров время измеряют до сотых секунды: 9,58 секунды — мировой рекорд Усэйна Болта (2009). В гимнастике оценки считают до тысячных, например 14,733.', '<b>Sport.</b> In the 100 metres, time is measured to hundredths of a second: 9.58 seconds is Usain Bolt’s world record (2009). Gymnastics scores go to thousandths, like 14.733.'),
      L('<b>Sog‘liq.</b> Sog‘lom odamning tana harorati taxminan 36,6 °C. Dorilar ko‘pincha 0,5 g yoki 0,25 g dozada bo‘ladi — ya’ni ' + F(1, 2) + ' va ' + F(1, 4) + ' gramm.', '<b>Здоровье.</b> Температура тела здорового человека — около 36,6 °C. Лекарства часто бывают в дозах 0,5 г или 0,25 г — то есть ' + F(1, 2) + ' и ' + F(1, 4) + ' грамма.', '<b>Health.</b> A healthy body temperature is about 36.6 °C. Medicines often come in 0.5 g or 0.25 g doses — that is ' + F(1, 2) + ' and ' + F(1, 4) + ' of a gram.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Al-Koshiy π ni 3,1415926535897932 deb hisoblagan — bu 16 ta to‘g‘ri raqam!', 'Аль-Каши вычислил π как 3,1415926535897932 — это 16 верных знаков!', 'Al-Kashi computed π as 3.1415926535897932 — 16 correct decimal places!'),
      L(F(1, 7) + ' = 0,142857142857… — oltita raqam «142857» cheksiz takrorlanadi. 142857 · 7 = 999 999!', F(1, 7) + ' = 0,142857142857… — шесть цифр «142857» повторяются бесконечно. 142857 · 7 = 999 999!', F(1, 7) + ' = 0.142857142857… — the six digits “142857” repeat forever. 142857 · 7 = 999 999!'),
      L('Pul tizimlarining ko‘pchiligi o‘nlik: 1 dollar = 100 sent, 1 rubl = 100 tiyin. O‘zbek so‘mi ham 100 tiyinga bo‘lingan.', 'Большинство денежных систем десятичные: 1 доллар = 100 центов, 1 рубль = 100 копеек. Узбекский сум тоже делится на 100 тийинов.', 'Most currencies are decimal: 1 dollar = 100 cents, 1 rouble = 100 kopecks. The Uzbek sum is also divided into 100 tiyin.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('O‘nli kasrga aylantiring: ' + F(4, 5) + ', ' + F(11, 20) + ', ' + F(17, 50) + '.', 'Переведите в десятичные: ' + F(4, 5) + ', ' + F(11, 20) + ', ' + F(17, 50) + '.', 'Convert to decimals: ' + F(4, 5) + ', ' + F(11, 20) + ', ' + F(17, 50) + '.'),
      L(M(2, 3, 8) + ' ni o‘nli kasrda yozing.', 'Запишите ' + M(2, 3, 8) + ' десятичной дробью.', 'Write ' + M(2, 3, 8) + ' as a decimal.'),
      L('0,45 ni oddiy kasr ko‘rinishida yozing va qisqartiring.', 'Запишите 0,45 обыкновенной дробью и сократите.', 'Write 0.45 as a fraction and simplify.')
    ], after: [
      L('Javoblar: 0,8; 0,55; 0,34. 2,375. 0,45 = ' + F(45, 100) + ' = ' + F(9, 20) + ' (5 ga qisqartirdik).', 'Ответы: 0,8; 0,55; 0,34. 2,375. 0,45 = ' + F(45, 100) + ' = ' + F(9, 20) + ' (сократили на 5).', 'Answers: 0.8; 0.55; 0.34. 2.375. 0.45 = ' + F(45, 100) + ' = ' + F(9, 20) + ' (divided by 5).')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('O‘nli kasr — maxraji 10, 100, 1000 bo‘lgan kasrning vergul bilan yozilishi.', 'Десятичная дробь — запись с запятой дроби со знаменателем 10, 100, 1000.', 'A decimal is a fraction with denominator 10, 100, 1000 written with a point.'),
      L('Verguldan keyingi raqamlar soni = maxrajdagi nollar soni.', 'Число цифр после запятой = число нулей в знаменателе.', 'Digits after the point = zeros in the denominator.'),
      L('1-usul: surat va maxrajni bir xil songa ko‘paytirib, maxrajni 10, 100, 1000 ga keltiramiz.', 'Способ 1: умножаем числитель и знаменатель на одно число, приводя знаменатель к 10, 100, 1000.', 'Method 1: multiply top and bottom by the same number to make the denominator 10, 100 or 1000.'),
      L('2-usul: suratni maxrajga bo‘lamiz.', 'Способ 2: делим числитель на знаменатель.', 'Method 2: divide the numerator by the denominator.'),
      L('Aralash sonda butun qism verguldan oldin qoladi: ' + M(3, 1, 4) + ' = 3,25.', 'В смешанном числе целая часть остаётся перед запятой: ' + M(3, 1, 4) + ' = 3,25.', 'In a mixed number the whole part stays before the point: ' + M(3, 1, 4) + ' = 3.25.'),
      L('O‘nli kasrlarni Samarqandda al-Koshiy tizimli bayon qilgan (1427).', 'Десятичные дроби систематически изложил аль-Каши в Самарканде (1427).', 'Decimals were set out systematically by al-Kashi in Samarkand (1427).')
    ] }
  ] });
})(this);
(function (root) { 'use strict'; var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '5-1';
  function F(a, b) { return '<sup>' + a + '</sup>/<sub>' + b + '</sub>'; }
  function M(w, a, b) { return w + F(a, b); }

  // ---------- t9. Aralash sonlarni qo'shish va ayirish ----------
  T.add(P, 't9', { sections: [
    { kind: 'intro', h: L('Butunlar va bo‘laklar', 'Целые и кусочки', 'Wholes and pieces'), p: [
      L('Oyim bozordan ' + M(2, 1, 5) + ' kg olma va ' + M(1, 3, 5) + ' kg nok olib keldi. Jami necha kilogramm meva? Aralash son — bu butun qism va kasr qismning yig‘indisi. Demak, ularni qo‘shish ham oson: butunlarni butunlarga, bo‘laklarni bo‘laklarga qo‘shamiz. 2 + 1 = 3 butun, ' + F(1, 5) + ' + ' + F(3, 5) + ' = ' + F(4, 5) + '. Javob: ' + M(3, 4, 5) + ' kg.', 'Мама принесла с базара ' + M(2, 1, 5) + ' кг яблок и ' + M(1, 3, 5) + ' кг груш. Сколько всего килограммов фруктов? Смешанное число — сумма целой и дробной частей. Значит, складывать их просто: целые с целыми, кусочки с кусочками. 2 + 1 = 3 целых, ' + F(1, 5) + ' + ' + F(3, 5) + ' = ' + F(4, 5) + '. Ответ: ' + M(3, 4, 5) + ' кг.', 'Mum brought ' + M(2, 1, 5) + ' kg of apples and ' + M(1, 3, 5) + ' kg of pears from the market. How many kilograms of fruit in all? A mixed number is a whole part plus a fraction part. So adding them is easy: wholes with wholes, pieces with pieces. 2 + 1 = 3 wholes, ' + F(1, 5) + ' + ' + F(3, 5) + ' = ' + F(4, 5) + '. Answer: ' + M(3, 4, 5) + ' kg.'),
      L('Lekin ba’zan qiziq holatlar bo‘ladi: bo‘laklar yig‘ilib, yangi butun hosil qiladi yoki ayirishda bo‘laklar yetmay qoladi. Bu mavzuda ana shunday holatlarni ham o‘rganamiz va maxrajlari bir xil bo‘lgan kasrlar va aralash sonlarni ishonch bilan qo‘shish va ayirishni o‘rganamiz.', 'Но иногда бывают интересные случаи: кусочки складываются в новое целое или при вычитании кусочков не хватает. В этой теме разберём и такие случаи и научимся уверенно складывать и вычитать дроби и смешанные числа с одинаковыми знаменателями.', 'But sometimes interesting things happen: the pieces add up to a new whole, or in subtraction there are not enough pieces. In this topic we deal with those cases too and learn to add and subtract fractions and mixed numbers with the same denominator confidently.'),
      L('Bu ko‘nikma oshxonada, ustaxonada va sport mashg‘ulotlarida doimo kerak: «' + M(1, 1, 2) + ' soat mashq + ' + F(3, 4) + ' soat dam», «' + M(2, 1, 4) + ' metr taxtadan ' + F(3, 4) + ' metr kesildi».', 'Это умение постоянно нужно на кухне, в мастерской и на тренировках: «' + M(1, 1, 2) + ' часа тренировки + ' + F(3, 4) + ' часа отдыха», «от доски ' + M(2, 1, 4) + ' метра отпилили ' + F(3, 4) + ' метра».', 'This skill is needed all the time in the kitchen, the workshop and at training: “' + M(1, 1, 2) + ' hours of practice + ' + F(3, 4) + ' hour of rest”, “' + F(3, 4) + ' m cut from a ' + M(2, 1, 4) + ' m plank”.')
    ] },
    { kind: 'def', h: L('Bir xil maxrajli kasrlar', 'Дроби с одинаковыми знаменателями', 'Fractions with the same denominator'), p: [
      L('Agar ikki kasrning maxraji bir xil bo‘lsa, ular <b>bir xil bo‘laklar</b>dan iborat. ' + F(1, 5) + ' va ' + F(3, 5) + ' — ikkalasi ham «beshdan bir»lar: bittasi 1 ta, ikkinchisi 3 ta. Ularni qo‘shsak, 4 ta «beshdan bir» bo‘ladi: ' + F(4, 5) + '. Xuddi 1 ta olma + 3 ta olma = 4 ta olma kabi.', 'Если у двух дробей одинаковый знаменатель, они состоят из <b>одинаковых долей</b>. ' + F(1, 5) + ' и ' + F(3, 5) + ' — это «пятые доли»: в одной 1, в другой 3. Вместе — 4 «пятых»: ' + F(4, 5) + '. Как 1 яблоко + 3 яблока = 4 яблока.', 'If two fractions have the same denominator they are made of <b>the same kind of piece</b>. ' + F(1, 5) + ' and ' + F(3, 5) + ' are both “fifths”: one has 1, the other 3. Together they make 4 fifths: ' + F(4, 5) + '. Just like 1 apple + 3 apples = 4 apples.'),
      L('<b>Qoida:</b> maxrajlari bir xil kasrlarni qo‘shish (ayirish) uchun suratlarini qo‘shamiz (ayiramiz), maxrajni o‘zgarishsiz qoldiramiz: ' + F('a', 'c') + ' + ' + F('b', 'c') + ' = ' + F('a + b', 'c') + '; ' + F('a', 'c') + ' − ' + F('b', 'c') + ' = ' + F('a − b', 'c') + '.', '<b>Правило:</b> чтобы сложить (вычесть) дроби с одинаковыми знаменателями, складываем (вычитаем) числители, а знаменатель оставляем прежним: ' + F('a', 'c') + ' + ' + F('b', 'c') + ' = ' + F('a + b', 'c') + '; ' + F('a', 'c') + ' − ' + F('b', 'c') + ' = ' + F('a − b', 'c') + '.', '<b>Rule:</b> to add (subtract) fractions with the same denominator, add (subtract) the numerators and keep the denominator: ' + F('a', 'c') + ' + ' + F('b', 'c') + ' = ' + F('a + b', 'c') + '; ' + F('a', 'c') + ' − ' + F('b', 'c') + ' = ' + F('a − b', 'c') + '.'),
      L('Nega maxraj qo‘shilmaydi? Chunki maxraj — bo‘lak <b>turi</b>ning nomi (beshdan bir, sakkizdan bir), son emas. «3 ta olma + 1 ta olma» da «olma» so‘zi ham qo‘shilmaydi-ku!', 'Почему знаменатель не складывают? Потому что знаменатель — <b>название</b> доли (пятые, восьмые), а не количество. В «3 яблока + 1 яблоко» слово «яблоко» ведь тоже не складывают!', 'Why not add the denominators? Because the denominator is the <b>name</b> of the piece (fifths, eighths), not a count. In “3 apples + 1 apple” we don’t add the word “apple” either!')
    ] },
    { kind: 'history', h: L('Tarixdan', 'Из истории', 'From history'), p: [
      L('Misrliklar faqat birlik kasrlar bilan ishlagani uchun qo‘shish ular uchun juda murakkab edi: ' + F(2, 5) + ' ni ' + F(1, 3) + ' + ' + F(1, 15) + ' deb yozib, so‘ng yig‘indilarni jadvallardan qidirishgan. Kotiblar yillar davomida maxsus jadvallarni yodlashgan.', 'Египтяне работали только с единичными дробями, поэтому сложение было для них очень сложным: ' + F(2, 5) + ' записывали как ' + F(1, 3) + ' + ' + F(1, 15) + ', а суммы искали в таблицах. Писцы годами заучивали специальные таблицы.', 'The Egyptians worked only with unit fractions, so addition was very hard for them: ' + F(2, 5) + ' was written as ' + F(1, 3) + ' + ' + F(1, 15) + ', and sums were looked up in tables. Scribes spent years memorising special tables.'),
      L('Hind matematiklari, xususan VII asrda <b>Braxmagupta</b>, kasrlarni qo‘shish va ayirishning umumiy qoidalarini yozib qoldirgan. <b>Al-Xorazmiy</b> esa meros taqsimlash masalalarida aralash sonlar bilan keng ishlagan: masalan, merosning ' + F(1, 8) + ' qismi xotinga, qolgan qismi farzandlarga — bularni hisoblash uchun kasrlarni qo‘shish va ayirish zarur edi.', 'Индийские математики, особенно <b>Брахмагупта</b> в VII веке, записали общие правила сложения и вычитания дробей. <b>Аль-Хорезми</b> много работал со смешанными числами в задачах о разделе наследства: например, ' + F(1, 8) + ' наследства — жене, остальное — детям; для таких расчётов нужно было складывать и вычитать дроби.', 'Indian mathematicians, especially <b>Brahmagupta</b> in the 7th century, wrote down general rules for adding and subtracting fractions. <b>Al-Khwarizmi</b> worked a lot with mixed numbers in inheritance problems: for example, ' + F(1, 8) + ' of the estate to the wife and the rest to the children — such sums required adding and subtracting fractions.'),
      L('O‘rta asrlarda Yevropada kasrlar shunchalik qiyin hisoblanganki, nemislarda «kasrlarga tushib qolmoq» iborasi «qiyin ahvolga tushmoq» degan ma’noni bildirgan. Bugun esa buni har bir beshinchi sinf o‘quvchisi bajara oladi!', 'В средневековой Европе дроби считались настолько трудными, что у немцев выражение «попасть в дроби» означало «попасть в трудное положение». А сегодня с ними справляется каждый пятиклассник!', 'In medieval Europe fractions were thought so hard that the German phrase “to get into fractions” meant “to get into trouble”. Today every fifth-grader can handle them!')
    ] },
    { kind: 'rule', h: L('Aralash sonlar bilan amallar', 'Действия со смешанными числами', 'Working with mixed numbers'), p: [
      L('<b>Qo‘shish.</b> Butun qismlarni alohida, kasr qismlarni alohida qo‘shamiz: ' + M(2, 1, 5) + ' + ' + M(1, 3, 5) + ' = (2 + 1) + (' + F(1, 5) + ' + ' + F(3, 5) + ') = ' + M(3, 4, 5) + '. Agar kasr qismlar yig‘indisi noto‘g‘ri kasr bo‘lsa, undan butun ajratib, butun qismga qo‘shamiz: ' + M(1, 4, 5) + ' + ' + M(1, 3, 5) + ' = ' + M(2, 7, 5) + ' = 2 + ' + M(1, 2, 5) + ' = ' + M(3, 2, 5) + '.', '<b>Сложение.</b> Целые части складываем отдельно, дробные — отдельно: ' + M(2, 1, 5) + ' + ' + M(1, 3, 5) + ' = (2 + 1) + (' + F(1, 5) + ' + ' + F(3, 5) + ') = ' + M(3, 4, 5) + '. Если сумма дробных частей — неправильная дробь, выделяем из неё целое и прибавляем к целой части: ' + M(1, 4, 5) + ' + ' + M(1, 3, 5) + ' = ' + M(2, 7, 5) + ' = 2 + ' + M(1, 2, 5) + ' = ' + M(3, 2, 5) + '.', '<b>Adding.</b> Add the whole parts and the fraction parts separately: ' + M(2, 1, 5) + ' + ' + M(1, 3, 5) + ' = (2 + 1) + (' + F(1, 5) + ' + ' + F(3, 5) + ') = ' + M(3, 4, 5) + '. If the fraction parts add to an improper fraction, take out a whole and add it to the whole part: ' + M(1, 4, 5) + ' + ' + M(1, 3, 5) + ' = ' + M(2, 7, 5) + ' = 2 + ' + M(1, 2, 5) + ' = ' + M(3, 2, 5) + '.'),
      L('<b>Ayirish.</b> Butundan butunni, kasrdan kasrni ayiramiz: ' + M(4, 5, 7) + ' − ' + M(1, 2, 7) + ' = ' + M(3, 3, 7) + '. Agar kamayuvchining kasr qismi ayriluvchinikidan kichik bo‘lsa, kamayuvchining butun qismidan 1 ni «qarz olib», kasrga aylantiramiz: ' + M(5, 1, 6) + ' − ' + M(2, 5, 6) + ' = ' + M(4, 7, 6) + ' − ' + M(2, 5, 6) + ' = ' + M(2, 2, 6) + '.', '<b>Вычитание.</b> Из целых вычитаем целые, из дробей — дроби: ' + M(4, 5, 7) + ' − ' + M(1, 2, 7) + ' = ' + M(3, 3, 7) + '. Если дробная часть уменьшаемого меньше, чем у вычитаемого, «занимаем» 1 у целой части уменьшаемого и превращаем её в дробь: ' + M(5, 1, 6) + ' − ' + M(2, 5, 6) + ' = ' + M(4, 7, 6) + ' − ' + M(2, 5, 6) + ' = ' + M(2, 2, 6) + '.', '<b>Subtracting.</b> Wholes from wholes, fractions from fractions: ' + M(4, 5, 7) + ' − ' + M(1, 2, 7) + ' = ' + M(3, 3, 7) + '. If the first number’s fraction part is smaller, “borrow” 1 from its whole part and turn it into a fraction: ' + M(5, 1, 6) + ' − ' + M(2, 5, 6) + ' = ' + M(4, 7, 6) + ' − ' + M(2, 5, 6) + ' = ' + M(2, 2, 6) + '.'),
      L('<b>Butundan kasrni ayirish.</b> 1 = ' + F(5, 5) + ', demak 1 − ' + F(2, 5) + ' = ' + F(3, 5) + '. 4 − ' + F(2, 5) + ' = ' + M(3, 5, 5) + ' − ' + F(2, 5) + ' = ' + M(3, 3, 5) + '.', '<b>Вычитание дроби из целого.</b> 1 = ' + F(5, 5) + ', значит 1 − ' + F(2, 5) + ' = ' + F(3, 5) + '. 4 − ' + F(2, 5) + ' = ' + M(3, 5, 5) + ' − ' + F(2, 5) + ' = ' + M(3, 3, 5) + '.', '<b>Subtracting a fraction from a whole.</b> 1 = ' + F(5, 5) + ', so 1 − ' + F(2, 5) + ' = ' + F(3, 5) + '. 4 − ' + F(2, 5) + ' = ' + M(3, 5, 5) + ' − ' + F(2, 5) + ' = ' + M(3, 3, 5) + '.')
    ] },
    { kind: 'steps', h: L('Ayirish: «qarz olish» bosqichlari', 'Вычитание с «займом»: шаги', 'Subtracting with borrowing: steps'), list: [
      L('<b>1.</b> Kasr qismlarni solishtiring: ' + M(6, 2, 9) + ' − ' + M(3, 7, 9) + ' → ' + F(2, 9) + ' < ' + F(7, 9) + ', qarz olish kerak.', '<b>1.</b> Сравните дробные части: ' + M(6, 2, 9) + ' − ' + M(3, 7, 9) + ' → ' + F(2, 9) + ' < ' + F(7, 9) + ', нужен заём.', '<b>1.</b> Compare the fraction parts: ' + M(6, 2, 9) + ' − ' + M(3, 7, 9) + ' → ' + F(2, 9) + ' < ' + F(7, 9) + ', so borrow.'),
      L('<b>2.</b> Butun qismdan 1 ni oling: 6 → 5, va uni ' + F(9, 9) + ' ga aylantiring.', '<b>2.</b> Возьмите 1 у целой части: 6 → 5, и превратите её в ' + F(9, 9) + '.', '<b>2.</b> Take 1 from the whole part: 6 → 5, and turn it into ' + F(9, 9) + '.'),
      L('<b>3.</b> Kasrga qo‘shing: ' + F(2, 9) + ' + ' + F(9, 9) + ' = ' + F(11, 9) + '. Endi kamayuvchi ' + M(5, 11, 9) + '.', '<b>3.</b> Прибавьте к дроби: ' + F(2, 9) + ' + ' + F(9, 9) + ' = ' + F(11, 9) + '. Теперь уменьшаемое ' + M(5, 11, 9) + '.', '<b>3.</b> Add it to the fraction: ' + F(2, 9) + ' + ' + F(9, 9) + ' = ' + F(11, 9) + '. The first number is now ' + M(5, 11, 9) + '.'),
      L('<b>4.</b> Ayiring: (5 − 3) + (' + F(11, 9) + ' − ' + F(7, 9) + ') = ' + M(2, 4, 9) + '.', '<b>4.</b> Вычтите: (5 − 3) + (' + F(11, 9) + ' − ' + F(7, 9) + ') = ' + M(2, 4, 9) + '.', '<b>4.</b> Subtract: (5 − 3) + (' + F(11, 9) + ' − ' + F(7, 9) + ') = ' + M(2, 4, 9) + '.'),
      L('<b>5.</b> Tekshiring: ' + M(2, 4, 9) + ' + ' + M(3, 7, 9) + ' = ' + M(5, 11, 9) + ' = ' + M(6, 2, 9) + ' ✓.', '<b>5.</b> Проверьте: ' + M(2, 4, 9) + ' + ' + M(3, 7, 9) + ' = ' + M(5, 11, 9) + ' = ' + M(6, 2, 9) + ' ✓.', '<b>5.</b> Check: ' + M(2, 4, 9) + ' + ' + M(3, 7, 9) + ' = ' + M(5, 11, 9) + ' = ' + M(6, 2, 9) + ' ✓.')
    ], after: [
      L('Boshqa usul: ikkala sonni noto‘g‘ri kasrga aylantirish: ' + F(56, 9) + ' − ' + F(34, 9) + ' = ' + F(22, 9) + ' = ' + M(2, 4, 9) + '. Natija bir xil!', 'Другой способ: перевести оба числа в неправильные дроби: ' + F(56, 9) + ' − ' + F(34, 9) + ' = ' + F(22, 9) + ' = ' + M(2, 4, 9) + '. Результат тот же!', 'Another way: turn both into improper fractions: ' + F(56, 9) + ' − ' + F(34, 9) + ' = ' + F(22, 9) + ' = ' + M(2, 4, 9) + '. Same result!')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L(F(3, 8) + ' + ' + F(4, 8) + ' = ?', F(3, 8) + ' + ' + F(4, 8) + ' = ?', F(3, 8) + ' + ' + F(4, 8) + ' = ?'), s: L('Maxraj bir xil: 3 + 4 = 7. Javob: <b>' + F(7, 8) + '</b>.', 'Знаменатель одинаковый: 3 + 4 = 7. Ответ: <b>' + F(7, 8) + '</b>.', 'Same denominator: 3 + 4 = 7. Answer: <b>' + F(7, 8) + '</b>.') },
      { q: L(M(3, 5, 6) + ' + ' + M(2, 4, 6) + ' = ?', M(3, 5, 6) + ' + ' + M(2, 4, 6) + ' = ?', M(3, 5, 6) + ' + ' + M(2, 4, 6) + ' = ?'), s: L('Butunlar: 3 + 2 = 5. Kasrlar: ' + F(5, 6) + ' + ' + F(4, 6) + ' = ' + F(9, 6) + ' = ' + M(1, 3, 6) + '. Jami: 5 + ' + M(1, 3, 6) + ' = <b>' + M(6, 3, 6) + '</b>. (Keyinroq ' + F(3, 6) + ' ni ' + F(1, 2) + ' ga qisqartirishni o‘rganasiz.)', 'Целые: 3 + 2 = 5. Дроби: ' + F(5, 6) + ' + ' + F(4, 6) + ' = ' + F(9, 6) + ' = ' + M(1, 3, 6) + '. Всего: 5 + ' + M(1, 3, 6) + ' = <b>' + M(6, 3, 6) + '</b>. (Позже вы научитесь сокращать ' + F(3, 6) + ' до ' + F(1, 2) + '.)', 'Wholes: 3 + 2 = 5. Fractions: ' + F(5, 6) + ' + ' + F(4, 6) + ' = ' + F(9, 6) + ' = ' + M(1, 3, 6) + '. Total: 5 + ' + M(1, 3, 6) + ' = <b>' + M(6, 3, 6) + '</b>. (Later you will simplify ' + F(3, 6) + ' to ' + F(1, 2) + '.)') },
      { q: L('7 − ' + M(2, 3, 4) + ' = ?', '7 − ' + M(2, 3, 4) + ' = ?', '7 − ' + M(2, 3, 4) + ' = ?'), s: L('7 = ' + M(6, 4, 4) + '. ' + M(6, 4, 4) + ' − ' + M(2, 3, 4) + ' = <b>' + M(4, 1, 4) + '</b>. Tekshiruv: ' + M(4, 1, 4) + ' + ' + M(2, 3, 4) + ' = ' + M(6, 4, 4) + ' = 7 ✓.', '7 = ' + M(6, 4, 4) + '. ' + M(6, 4, 4) + ' − ' + M(2, 3, 4) + ' = <b>' + M(4, 1, 4) + '</b>. Проверка: ' + M(4, 1, 4) + ' + ' + M(2, 3, 4) + ' = ' + M(6, 4, 4) + ' = 7 ✓.', '7 = ' + M(6, 4, 4) + '. ' + M(6, 4, 4) + ' − ' + M(2, 3, 4) + ' = <b>' + M(4, 1, 4) + '</b>. Check: ' + M(4, 1, 4) + ' + ' + M(2, 3, 4) + ' = ' + M(6, 4, 4) + ' = 7 ✓.') },
      { q: L('Lenta ' + M(5, 1, 3) + ' m edi. Undan ' + M(1, 2, 3) + ' m va yana ' + M(2, 1, 3) + ' m kesildi. Necha metr qoldi?', 'Лента была ' + M(5, 1, 3) + ' м. От неё отрезали ' + M(1, 2, 3) + ' м и ещё ' + M(2, 1, 3) + ' м. Сколько метров осталось?', 'A ribbon was ' + M(5, 1, 3) + ' m long. ' + M(1, 2, 3) + ' m and then ' + M(2, 1, 3) + ' m were cut off. How much is left?'), s: L('1) Kesilgan: ' + M(1, 2, 3) + ' + ' + M(2, 1, 3) + ' = ' + M(3, 3, 3) + ' = 4 m. 2) Qoldi: ' + M(5, 1, 3) + ' − 4 = <b>' + M(1, 1, 3) + ' m</b>.', '1) Отрезали: ' + M(1, 2, 3) + ' + ' + M(2, 1, 3) + ' = ' + M(3, 3, 3) + ' = 4 м. 2) Осталось: ' + M(5, 1, 3) + ' − 4 = <b>' + M(1, 1, 3) + ' м</b>.', '1) Cut off: ' + M(1, 2, 3) + ' + ' + M(2, 1, 3) + ' = ' + M(3, 3, 3) + ' = 4 m. 2) Left: ' + M(5, 1, 3) + ' − 4 = <b>' + M(1, 1, 3) + ' m</b>.') }
    ] },
    { kind: 'table', h: L('Uch holat', 'Три случая', 'Three cases'), table: { head: [L('Holat', 'Случай', 'Case'), L('Misol', 'Пример', 'Example'), L('Nima qilamiz', 'Что делаем', 'What to do')], rows: [
      [L('Oddiy qo‘shish', 'Простое сложение', 'Plain addition'), M(2, 1, 5) + ' + ' + M(1, 3, 5) + ' = ' + M(3, 4, 5), L('butun + butun, kasr + kasr', 'целые + целые, дроби + дроби', 'wholes + wholes, fractions + fractions')],
      [L('Kasr 1 dan oshdi', 'Дробь больше 1', 'Fraction goes over 1'), M(1, 4, 5) + ' + ' + M(1, 3, 5) + ' = ' + M(3, 2, 5), L('butun ajratamiz', 'выделяем целое', 'take out a whole')],
      [L('Oddiy ayirish', 'Простое вычитание', 'Plain subtraction'), M(4, 5, 7) + ' − ' + M(1, 2, 7) + ' = ' + M(3, 3, 7), L('butun − butun, kasr − kasr', 'целые − целые, дроби − дроби', 'wholes − wholes, fractions − fractions')],
      [L('Kasr yetmaydi', 'Дроби не хватает', 'Not enough fraction'), M(5, 1, 6) + ' − ' + M(2, 5, 6) + ' = ' + M(2, 2, 6), L('1 butunni qarz olamiz', 'занимаем 1 целое', 'borrow 1 whole')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Maxrajlarni qo‘shish.</b> ' + F(1, 5) + ' + ' + F(3, 5) + ' = ' + F(4, 10) + ' — xato! Maxraj o‘zgarmaydi: ' + F(4, 5) + '.', '<b>Складывают знаменатели.</b> ' + F(1, 5) + ' + ' + F(3, 5) + ' = ' + F(4, 10) + ' — ошибка! Знаменатель не меняется: ' + F(4, 5) + '.', '<b>Adding the denominators.</b> ' + F(1, 5) + ' + ' + F(3, 5) + ' = ' + F(4, 10) + ' is wrong! The denominator stays: ' + F(4, 5) + '.'),
      L('<b>Noto‘g‘ri kasrni javobda qoldirish.</b> ' + M(2, 7, 5) + ' — tugallanmagan javob. ' + M(3, 2, 5) + ' deb yozing.', '<b>Оставляют неправильную дробь в ответе.</b> ' + M(2, 7, 5) + ' — незаконченный ответ. Пишите ' + M(3, 2, 5) + '.', '<b>Leaving an improper fraction in the answer.</b> ' + M(2, 7, 5) + ' is unfinished. Write ' + M(3, 2, 5) + '.'),
      L('<b>Kichikdan kattani ayirish.</b> ' + M(5, 1, 6) + ' − ' + M(2, 5, 6) + ' da ' + F(5, 6) + ' − ' + F(1, 6) + ' = ' + F(4, 6) + ' deb, «teskari» ayirish — katta xato. Qarz oling!', '<b>Вычитают «наоборот».</b> В ' + M(5, 1, 6) + ' − ' + M(2, 5, 6) + ' считать ' + F(5, 6) + ' − ' + F(1, 6) + ' = ' + F(4, 6) + ' — грубая ошибка. Займите единицу!', '<b>Subtracting “backwards”.</b> In ' + M(5, 1, 6) + ' − ' + M(2, 5, 6) + ', doing ' + F(5, 6) + ' − ' + F(1, 6) + ' = ' + F(4, 6) + ' is a big mistake. Borrow!'),
      L('<b>Qarz olgandan keyin butunni kamaytirmaslik.</b> ' + M(5, 1, 6) + ' = ' + M(4, 7, 6) + ', ' + M(5, 7, 6) + ' emas.', '<b>Не уменьшают целое после займа.</b> ' + M(5, 1, 6) + ' = ' + M(4, 7, 6) + ', а не ' + M(5, 7, 6) + '.', '<b>Not reducing the whole after borrowing.</b> ' + M(5, 1, 6) + ' = ' + M(4, 7, 6) + ', not ' + M(5, 7, 6) + '.'),
      L('<b>Butundan kasrni ayirishda butunni yo‘qotish.</b> 4 − ' + F(2, 5) + ' = ' + F(2, 5) + ' yoki ' + M(4, 2, 5) + ' emas, ' + M(3, 3, 5) + '.', '<b>Теряют целое при вычитании дроби из числа.</b> 4 − ' + F(2, 5) + ' — не ' + F(2, 5) + ' и не ' + M(4, 2, 5) + ', а ' + M(3, 3, 5) + '.', '<b>Losing the whole when subtracting from a whole number.</b> 4 − ' + F(2, 5) + ' is not ' + F(2, 5) + ' or ' + M(4, 2, 5) + ' but ' + M(3, 3, 5) + '.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Uses in everyday life'), p: [
      L('<b>Vaqt.</b> Ali ' + M(1, 1, 4) + ' soat uy vazifasi qildi va ' + F(3, 4) + ' soat kitob o‘qidi: ' + M(1, 1, 4) + ' + ' + F(3, 4) + ' = ' + M(1, 4, 4) + ' = 2 soat. Kino ' + M(2, 1, 4) + ' soat davom etadi, siz ' + F(3, 4) + ' soat ko‘rdingiz — yana ' + M(1, 2, 4) + ' soat (1 soat 30 daqiqa) qoldi.', '<b>Время.</b> Али делал уроки ' + M(1, 1, 4) + ' часа и читал ' + F(3, 4) + ' часа: ' + M(1, 1, 4) + ' + ' + F(3, 4) + ' = ' + M(1, 4, 4) + ' = 2 часа. Фильм длится ' + M(2, 1, 4) + ' часа, вы посмотрели ' + F(3, 4) + ' часа — осталось ' + M(1, 2, 4) + ' часа (1 час 30 минут).', '<b>Time.</b> Ali did homework for ' + M(1, 1, 4) + ' h and read for ' + F(3, 4) + ' h: ' + M(1, 1, 4) + ' + ' + F(3, 4) + ' = ' + M(1, 4, 4) + ' = 2 hours. A film lasts ' + M(2, 1, 4) + ' h; you have watched ' + F(3, 4) + ' h — ' + M(1, 2, 4) + ' h (1 h 30 min) is left.'),
      L('<b>Oshxona.</b> Palov uchun ' + M(1, 1, 2) + ' kg guruch kerak, uyda ' + F(3, 4) + ' kg bor... maxrajlar har xil! Lekin ' + F(1, 2) + ' = ' + F(2, 4) + ', demak ' + M(1, 2, 4) + ' − ' + F(3, 4) + ' = ' + F(3, 4) + ' kg sotib olish kerak.', '<b>Кухня.</b> Для плова нужно ' + M(1, 1, 2) + ' кг риса, дома есть ' + F(3, 4) + ' кг... знаменатели разные! Но ' + F(1, 2) + ' = ' + F(2, 4) + ', значит, ' + M(1, 2, 4) + ' − ' + F(3, 4) + ' = ' + F(3, 4) + ' кг нужно докупить.', '<b>Kitchen.</b> Plov needs ' + M(1, 1, 2) + ' kg of rice and there is ' + F(3, 4) + ' kg at home... different denominators! But ' + F(1, 2) + ' = ' + F(2, 4) + ', so ' + M(1, 2, 4) + ' − ' + F(3, 4) + ' = ' + F(3, 4) + ' kg must be bought.'),
      L('<b>Duradgorlik.</b> Usta ' + M(3, 1, 8) + ' m taxtadan ' + M(1, 5, 8) + ' m kesib oldi. Qolgan bo‘lak: ' + M(2, 9, 8) + ' − ' + M(1, 5, 8) + ' = ' + M(1, 4, 8) + ' m. Usta bu hisobni xayolda bajaradi — aks holda qimmatbaho yog‘och isrof bo‘ladi.', '<b>Столярное дело.</b> Мастер отпилил от доски ' + M(3, 1, 8) + ' м кусок ' + M(1, 5, 8) + ' м. Осталось: ' + M(2, 9, 8) + ' − ' + M(1, 5, 8) + ' = ' + M(1, 4, 8) + ' м. Мастер считает это в уме — иначе дорогое дерево пропадёт зря.', '<b>Carpentry.</b> A carpenter cuts ' + M(1, 5, 8) + ' m from a ' + M(3, 1, 8) + ' m plank. Left: ' + M(2, 9, 8) + ' − ' + M(1, 5, 8) + ' = ' + M(1, 4, 8) + ' m. Carpenters work this out in their heads — otherwise expensive wood is wasted.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L(F(1, 2) + ' + ' + F(1, 4) + ' + ' + F(1, 8) + ' + ' + F(1, 16) + ' + … — har safar qolgan yo‘lning yarmini qo‘shsak, yig‘indi 1 ga cheksiz yaqinlashadi, lekin hech qachon oshmaydi.', F(1, 2) + ' + ' + F(1, 4) + ' + ' + F(1, 8) + ' + ' + F(1, 16) + ' + … — если каждый раз прибавлять половину оставшегося, сумма бесконечно приближается к 1, но никогда её не превышает.', F(1, 2) + ' + ' + F(1, 4) + ' + ' + F(1, 8) + ' + ' + F(1, 16) + ' + … — adding half of what is left each time, the sum gets ever closer to 1 but never passes it.'),
      L('Musiqada bir taktdagi notalar davomiyligi yig‘indisi doim bir xil: masalan, ' + F(4, 4) + ' o‘lchovda ' + F(1, 2) + ' + ' + F(1, 4) + ' + ' + F(1, 4) + ' = 1.', 'В музыке сумма длительностей нот в такте всегда одинакова: например, в размере ' + F(4, 4) + ': ' + F(1, 2) + ' + ' + F(1, 4) + ' + ' + F(1, 4) + ' = 1.', 'In music the note lengths in a bar always add up to the same amount: in ' + F(4, 4) + ' time, ' + F(1, 2) + ' + ' + F(1, 4) + ' + ' + F(1, 4) + ' = 1.'),
      L('Fond birjalarida 2001-yilgacha aksiya narxlari ' + F(1, 8) + ' va ' + F(1, 16) + ' dollarlarda yozilgan, keyin o‘nli kasrlarga o‘tilgan.', 'На американских биржах до 2001 года цены акций записывали в долях ' + F(1, 8) + ' и ' + F(1, 16) + ' доллара, потом перешли на десятичные дроби.', 'Until 2001 US stock prices were quoted in ' + F(1, 8) + ' and ' + F(1, 16) + ' of a dollar; then they switched to decimals.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L(M(4, 2, 9) + ' + ' + M(3, 8, 9) + ' = ?', M(4, 2, 9) + ' + ' + M(3, 8, 9) + ' = ?', M(4, 2, 9) + ' + ' + M(3, 8, 9) + ' = ?'),
      L('10 − ' + M(6, 5, 12) + ' = ?', '10 − ' + M(6, 5, 12) + ' = ?', '10 − ' + M(6, 5, 12) + ' = ?'),
      L('Qanday kasrni ' + F(3, 10) + ' ga qo‘shsak, 1 hosil bo‘ladi?', 'Какую дробь нужно прибавить к ' + F(3, 10) + ', чтобы получить 1?', 'What fraction must be added to ' + F(3, 10) + ' to make 1?')
    ], after: [
      L('Javoblar: ' + M(7, 10, 9) + ' = ' + M(8, 1, 9) + '; ' + M(9, 12, 12) + ' − ' + M(6, 5, 12) + ' = ' + M(3, 7, 12) + '; ' + F(7, 10) + '.', 'Ответы: ' + M(7, 10, 9) + ' = ' + M(8, 1, 9) + '; ' + M(9, 12, 12) + ' − ' + M(6, 5, 12) + ' = ' + M(3, 7, 12) + '; ' + F(7, 10) + '.', 'Answers: ' + M(7, 10, 9) + ' = ' + M(8, 1, 9) + '; ' + M(9, 12, 12) + ' − ' + M(6, 5, 12) + ' = ' + M(3, 7, 12) + '; ' + F(7, 10) + '.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Maxrajlari bir xil kasrlarda suratlar qo‘shiladi (ayiriladi), maxraj o‘zgarmaydi.', 'У дробей с одинаковыми знаменателями складывают (вычитают) числители, знаменатель не меняется.', 'With equal denominators, add (subtract) the numerators; the denominator stays.'),
      L('Aralash sonlarda butunlar alohida, kasrlar alohida hisoblanadi.', 'В смешанных числах целые и дробные части считают отдельно.', 'With mixed numbers, wholes and fractions are handled separately.'),
      L('Kasr qism noto‘g‘ri kasr bo‘lsa, butun ajratiladi.', 'Если дробная часть неправильная, выделяют целое.', 'If the fraction part is improper, take out a whole.'),
      L('Ayirishda kasr yetmasa, butundan 1 «qarz» olinadi.', 'Если при вычитании дроби не хватает, «занимают» 1 у целых.', 'If the fraction is too small when subtracting, borrow 1 from the wholes.'),
      L('Har doim qo‘shish bilan tekshirish mumkin.', 'Вычитание всегда можно проверить сложением.', 'Subtraction can always be checked by addition.')
    ] }
  ] });

  // ---------- t10. Kasrni natural songa ko'paytirish ----------
  T.add(P, 't10', { sections: [
    { kind: 'intro', h: L('Bir xil bo‘laklarni ko‘p marta olish', 'Много одинаковых кусочков', 'Taking the same piece many times'), p: [
      L('Har kuni nonushtada ' + F(1, 4) + ' non yeysiz. Bir haftada qancha non yeysiz? ' + F(1, 4) + ' + ' + F(1, 4) + ' + … (7 marta) = ' + F(7, 4) + ' = ' + M(1, 3, 4) + ' non. Ko‘paytirish — bir xil qo‘shiluvchilarni qo‘shishning qisqa yo‘li. Demak, ' + F(1, 4) + ' · 7 = ' + F(7, 4) + '.', 'Каждый день на завтрак вы съедаете ' + F(1, 4) + ' лепёшки. Сколько за неделю? ' + F(1, 4) + ' + ' + F(1, 4) + ' + … (7 раз) = ' + F(7, 4) + ' = ' + M(1, 3, 4) + ' лепёшки. Умножение — короткий способ сложить одинаковые слагаемые. Значит, ' + F(1, 4) + ' · 7 = ' + F(7, 4) + '.', 'Every day at breakfast you eat ' + F(1, 4) + ' of a loaf. How much in a week? ' + F(1, 4) + ' + ' + F(1, 4) + ' + … (7 times) = ' + F(7, 4) + ' = ' + M(1, 3, 4) + ' loaves. Multiplication is a short way of adding equal terms. So ' + F(1, 4) + ' · 7 = ' + F(7, 4) + '.'),
      L('Bu mavzuda ikki muhim narsani o‘rganamiz: kasrni natural songa ko‘paytirish va <b>sonning kasr qismini topish</b>. Ikkinchisi hayotda juda ko‘p uchraydi: «sinfning ' + F(3, 4) + ' qismi», «pulning ' + F(1, 3) + ' qismi», «yo‘lning ' + F(2, 5) + ' qismi».', 'В этой теме изучим две важные вещи: умножение дроби на натуральное число и <b>нахождение дроби от числа</b>. Второе очень часто встречается в жизни: «' + F(3, 4) + ' класса», «' + F(1, 3) + ' денег», «' + F(2, 5) + ' пути».', 'In this topic we learn two important things: multiplying a fraction by a whole number and <b>finding a fraction of a number</b>. The second comes up all the time: “' + F(3, 4) + ' of the class”, “' + F(1, 3) + ' of the money”, “' + F(2, 5) + ' of the way”.'),
      L('Ikkalasi ham bitta g‘oyaga asoslanadi va bir-biriga juda o‘xshaydi — buni mavzu oxirida o‘zingiz ko‘rasiz.', 'Оба основаны на одной идее и очень похожи друг на друга — вы сами увидите это к концу темы.', 'Both rest on one idea and are very alike — you will see this yourself by the end of the topic.')
    ] },
    { kind: 'def', h: L('Ta’riflar', 'Определения', 'Definitions'), p: [
      L('<b>Kasrni natural songa ko‘paytirish</b> — kasrni shu son marta qo‘shiluvchi qilib qo‘shish. ' + F(2, 7) + ' · 3 = ' + F(2, 7) + ' + ' + F(2, 7) + ' + ' + F(2, 7) + ' = ' + F(6, 7) + '. Ko‘rinib turibdiki, bo‘lak turi (yettidan bir) o‘zgarmadi, faqat bo‘laklar soni 3 marta ko‘paydi.', '<b>Умножить дробь на натуральное число</b> — значит сложить эту дробь столько раз, каково число. ' + F(2, 7) + ' · 3 = ' + F(2, 7) + ' + ' + F(2, 7) + ' + ' + F(2, 7) + ' = ' + F(6, 7) + '. Видно, что вид долей (седьмые) не изменился, только их количество стало в 3 раза больше.', '<b>Multiplying a fraction by a whole number</b> means adding the fraction that many times. ' + F(2, 7) + ' · 3 = ' + F(2, 7) + ' + ' + F(2, 7) + ' + ' + F(2, 7) + ' = ' + F(6, 7) + '. The kind of piece (sevenths) did not change; only the number of pieces tripled.'),
      L('<b>Sonning kasr qismi</b> — masalan, 24 ning ' + F(3, 4) + ' qismi — 24 ni 4 ta teng bo‘lakka bo‘lib, shulardan 3 tasini olish. 24 : 4 = 6 (bitta bo‘lak), 6 · 3 = 18. Bu amal ham ko‘paytirish bilan yoziladi: 24 · ' + F(3, 4) + ' = 18.', '<b>Дробь от числа</b> — например, ' + F(3, 4) + ' от 24 — значит разделить 24 на 4 равные части и взять 3 из них. 24 : 4 = 6 (одна часть), 6 · 3 = 18. Это действие тоже записывают умножением: 24 · ' + F(3, 4) + ' = 18.', '<b>A fraction of a number</b> — say ' + F(3, 4) + ' of 24 — means splitting 24 into 4 equal parts and taking 3 of them. 24 : 4 = 6 (one part), 6 · 3 = 18. This is also written as multiplication: 24 · ' + F(3, 4) + ' = 18.'),
      L('<b>Qisqartirish</b> — kasrning surat va maxrajini bir xil songa bo‘lish: ' + F(6, 8) + ' = ' + F(3, 4) + '. Qiymat o‘zgarmaydi, lekin kasr soddaroq ko‘rinadi.', '<b>Сокращение</b> — деление числителя и знаменателя на одно и то же число: ' + F(6, 8) + ' = ' + F(3, 4) + '. Значение не меняется, но дробь выглядит проще.', '<b>Simplifying</b> means dividing top and bottom by the same number: ' + F(6, 8) + ' = ' + F(3, 4) + '. The value is unchanged but the fraction looks simpler.')
    ] },
    { kind: 'history', h: L('Tarixdan', 'Из истории', 'From history'), p: [
      L('Rind papirusida «sonning qismini topish» masalalari ko‘p: masalan, «100 ta nonni 10 kishiga shunday bo‘lingki…». Misrlik kotiblar ' + F(2, 3) + ' ni topishni alohida yaxshi bilishgan: avval sonni 3 ga bo‘lishgan, so‘ng ikki barobarga oshirishgan — xuddi biz kabi!', 'В папирусе Ринда много задач на «нахождение части числа»: например, «разделите 100 хлебов между 10 людьми так, чтобы…». Египетские писцы особенно хорошо умели находить ' + F(2, 3) + ': сначала делили на 3, потом удваивали — совсем как мы!', 'The Rhind Papyrus has many “part of a number” problems, such as “share 100 loaves among 10 men so that…”. Egyptian scribes were especially good at finding ' + F(2, 3) + ': first divide by 3, then double — just as we do!'),
      L('<b>Abu Rayhon Beruniy</b> «Hindiston» kitobida hind olimlarining kasrlar bilan ishlash usullarini batafsil tasvirlagan. U o‘zi ham astronomik hisoblarda yil va oyning qismlarini topgan: masalan, Oy oyini 29 butun va kunning yarmidan sal ko‘proq deb hisoblagan. Bunday aniq hisoblar kasrlarsiz mumkin emas edi.', '<b>Абу Райхан Беруни</b> в книге «Индия» подробно описал, как индийские учёные работали с дробями. Он и сам в астрономических расчётах находил части года и месяца: например, считал лунный месяц равным 29 суткам и чуть больше половины суток. Такие точные расчёты были невозможны без дробей.', '<b>Abu Rayhan Biruni</b> described in detail, in his book “India”, how Indian scholars worked with fractions. In his own astronomy he found parts of years and months: for example, he took the lunar month as 29 days and a little over half a day. Such precise work was impossible without fractions.'),
      L('O‘rta Osiyo bozorlarida savdogarlar «molning uchdan bir qismi», «foydaning to‘rtdan bir qismi» kabi hisoblarni har kuni bajarishgan — sherikchilik shartnomalari ham kasrlarga asoslangan.', 'На базарах Средней Азии торговцы каждый день считали «треть товара», «четверть прибыли» — даже договоры компаньонов были основаны на дробях.', 'In Central Asian bazaars merchants worked out “a third of the goods” or “a quarter of the profit” every day — even partnership agreements were based on fractions.')
    ] },
    { kind: 'rule', h: L('Qoidalar', 'Правила', 'The rules'), p: [
      L('<b>1-qoida.</b> Kasrni natural songa ko‘paytirish uchun uning suratini shu songa ko‘paytiramiz, maxrajni o‘zgarishsiz qoldiramiz: ' + F('a', 'b') + ' · n = ' + F('a · n', 'b') + '. Masalan, ' + F(2, 7) + ' · 3 = ' + F(6, 7) + '; ' + F(3, 5) + ' · 4 = ' + F(12, 5) + ' = ' + M(2, 2, 5) + '.', '<b>Правило 1.</b> Чтобы умножить дробь на натуральное число, умножаем на это число числитель, а знаменатель оставляем: ' + F('a', 'b') + ' · n = ' + F('a · n', 'b') + '. Например, ' + F(2, 7) + ' · 3 = ' + F(6, 7) + '; ' + F(3, 5) + ' · 4 = ' + F(12, 5) + ' = ' + M(2, 2, 5) + '.', '<b>Rule 1.</b> To multiply a fraction by a whole number, multiply the numerator by it and keep the denominator: ' + F('a', 'b') + ' · n = ' + F('a · n', 'b') + '. E.g. ' + F(2, 7) + ' · 3 = ' + F(6, 7) + '; ' + F(3, 5) + ' · 4 = ' + F(12, 5) + ' = ' + M(2, 2, 5) + '.'),
      L('<b>2-qoida.</b> Sonning ' + F('a', 'b') + ' qismini topish uchun sonni maxrajga bo‘lib, suratga ko‘paytiramiz: n ning ' + F('a', 'b') + ' qismi = n : b · a. Masalan, 24 ning ' + F(3, 4) + ' qismi = 24 : 4 · 3 = 18.', '<b>Правило 2.</b> Чтобы найти ' + F('a', 'b') + ' от числа, делим число на знаменатель и умножаем на числитель: ' + F('a', 'b') + ' от n = n : b · a. Например, ' + F(3, 4) + ' от 24 = 24 : 4 · 3 = 18.', '<b>Rule 2.</b> To find ' + F('a', 'b') + ' of a number, divide the number by the denominator and multiply by the numerator: ' + F('a', 'b') + ' of n = n : b · a. E.g. ' + F(3, 4) + ' of 24 = 24 : 4 · 3 = 18.'),
      L('Ikki qoida aslida bir xil: 24 · ' + F(3, 4) + ' = ' + F('24 · 3', 4) + ' = ' + F(72, 4) + ' = 18. Natija oxirida noto‘g‘ri kasr chiqsa — aralash songa aylantiring, iloji bo‘lsa — qisqartiring. Hisoblashni osonlashtirish uchun ko‘paytirishdan oldin qisqartirish mumkin: ' + F(5, 12) + ' · 4 = ' + F('5 · 4', 12) + ' = ' + F(5, 3) + '.', 'Оба правила на самом деле одинаковы: 24 · ' + F(3, 4) + ' = ' + F('24 · 3', 4) + ' = ' + F(72, 4) + ' = 18. Если в итоге получилась неправильная дробь — переведите в смешанное число, если можно — сократите. Для удобства можно сокращать до умножения: ' + F(5, 12) + ' · 4 = ' + F('5 · 4', 12) + ' = ' + F(5, 3) + '.', 'The two rules are really the same: 24 · ' + F(3, 4) + ' = ' + F('24 · 3', 4) + ' = ' + F(72, 4) + ' = 18. If the result is improper, turn it into a mixed number; simplify where you can. To make it easier, simplify before multiplying: ' + F(5, 12) + ' · 4 = ' + F('5 · 4', 12) + ' = ' + F(5, 3) + '.')
    ] },
    { kind: 'steps', h: L('Sonning qismini topish', 'Нахождение дроби от числа', 'Finding a fraction of a number'), list: [
      L('<b>1.</b> Butunni aniqlang — qaysi sonning qismi so‘ralmoqda? «Sinfdagi 30 o‘quvchining ' + F(2, 5) + ' qismi» → butun 30.', '<b>1.</b> Определите целое — от какого числа берётся часть? «' + F(2, 5) + ' от 30 учеников класса» → целое 30.', '<b>1.</b> Identify the whole — a part of which number? “' + F(2, 5) + ' of the 30 pupils” → the whole is 30.'),
      L('<b>2.</b> Butunni maxrajga bo‘ling — bitta bo‘lakni toping: 30 : 5 = 6.', '<b>2.</b> Разделите целое на знаменатель — найдите одну долю: 30 : 5 = 6.', '<b>2.</b> Divide the whole by the denominator — find one part: 30 : 5 = 6.'),
      L('<b>3.</b> Bo‘lakni suratga ko‘paytiring: 6 · 2 = 12.', '<b>3.</b> Умножьте долю на числитель: 6 · 2 = 12.', '<b>3.</b> Multiply the part by the numerator: 6 · 2 = 12.'),
      L('<b>4.</b> Javobni birlik bilan yozing: 12 nafar o‘quvchi.', '<b>4.</b> Запишите ответ с единицами: 12 учеников.', '<b>4.</b> Write the answer with units: 12 pupils.'),
      L('<b>5.</b> Mantiqni tekshiring: to‘g‘ri kasr bo‘lsa, javob butundan kichik bo‘lishi kerak (12 < 30 ✓).', '<b>5.</b> Проверьте логику: для правильной дроби ответ должен быть меньше целого (12 < 30 ✓).', '<b>5.</b> Sanity check: for a proper fraction the answer must be less than the whole (12 < 30 ✓).')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L(F(4, 9) + ' · 2 = ?', F(4, 9) + ' · 2 = ?', F(4, 9) + ' · 2 = ?'), s: L('Suratni 2 ga ko‘paytiramiz: ' + F('4 · 2', 9) + ' = <b>' + F(8, 9) + '</b>.', 'Умножаем числитель на 2: ' + F('4 · 2', 9) + ' = <b>' + F(8, 9) + '</b>.', 'Multiply the numerator by 2: ' + F('4 · 2', 9) + ' = <b>' + F(8, 9) + '</b>.') },
      { q: L(F(5, 6) + ' · 9 = ?', F(5, 6) + ' · 9 = ?', F(5, 6) + ' · 9 = ?'), s: L(F('5 · 9', 6) + ' = ' + F(45, 6) + ' = ' + M(7, 3, 6) + ' = <b>' + M(7, 1, 2) + '</b>. Yoki avval qisqartiramiz: 9 va 6 ni 3 ga: ' + F('5 · 3', 2) + ' = ' + F(15, 2) + ' = ' + M(7, 1, 2) + '.', F('5 · 9', 6) + ' = ' + F(45, 6) + ' = ' + M(7, 3, 6) + ' = <b>' + M(7, 1, 2) + '</b>. Или сначала сократим 9 и 6 на 3: ' + F('5 · 3', 2) + ' = ' + F(15, 2) + ' = ' + M(7, 1, 2) + '.', F('5 · 9', 6) + ' = ' + F(45, 6) + ' = ' + M(7, 3, 6) + ' = <b>' + M(7, 1, 2) + '</b>. Or simplify first, 9 and 6 by 3: ' + F('5 · 3', 2) + ' = ' + F(15, 2) + ' = ' + M(7, 1, 2) + '.') },
      { q: L('Kitob 240 betli. Salim kitobning ' + F(5, 8) + ' qismini o‘qidi. Necha bet o‘qidi va necha bet qoldi?', 'В книге 240 страниц. Салим прочитал ' + F(5, 8) + ' книги. Сколько страниц он прочитал и сколько осталось?', 'A book has 240 pages. Salim has read ' + F(5, 8) + ' of it. How many pages has he read and how many are left?'), s: L('1) 240 : 8 = 30 bet — bitta bo‘lak. 2) 30 · 5 = <b>150 bet</b> o‘qidi. 3) 240 − 150 = <b>90 bet</b> qoldi. Tekshiruv: qolgani ' + F(3, 8) + ' qism: 30 · 3 = 90 ✓.', '1) 240 : 8 = 30 страниц — одна доля. 2) 30 · 5 = <b>150 страниц</b> прочитал. 3) 240 − 150 = <b>90 страниц</b> осталось. Проверка: осталось ' + F(3, 8) + ': 30 · 3 = 90 ✓.', '1) 240 : 8 = 30 pages — one part. 2) 30 · 5 = <b>150 pages</b> read. 3) 240 − 150 = <b>90 pages</b> left. Check: the rest is ' + F(3, 8) + ': 30 · 3 = 90 ✓.') },
      { q: L('1 soatning ' + F(2, 3) + ' qismi necha daqiqa?', 'Сколько минут в ' + F(2, 3) + ' часа?', 'How many minutes are ' + F(2, 3) + ' of an hour?'), s: L('1 soat = 60 daqiqa. 60 : 3 · 2 = 20 · 2 = <b>40 daqiqa</b>.', '1 час = 60 минут. 60 : 3 · 2 = 20 · 2 = <b>40 минут</b>.', '1 hour = 60 minutes. 60 : 3 · 2 = 20 · 2 = <b>40 minutes</b>.') }
    ] },
    { kind: 'table', h: L('Tez-tez uchraydigan qismlar', 'Часто встречающиеся доли', 'Common fractions of things'), table: { head: [L('Butun', 'Целое', 'Whole'), F(1, 2), F(1, 4), F(3, 4), F(1, 3)], rows: [
      [L('1 soat = 60 daqiqa', '1 час = 60 минут', '1 hour = 60 min'), '30', '15', '45', '20'],
      [L('1 kg = 1000 g', '1 кг = 1000 г', '1 kg = 1000 g'), '500', '250', '750', '—'],
      [L('1 m = 100 cm', '1 м = 100 см', '1 m = 100 cm'), '50', '25', '75', '—'],
      [L('1 yil = 12 oy', '1 год = 12 месяцев', '1 year = 12 months'), '6', '3', '9', '4'],
      [L('1 sutka = 24 soat', '1 сутки = 24 часа', '1 day = 24 hours'), '12', '6', '18', '8']
    ] }, after: [
      L('«—» belgisi: 1000 va 100 ni 3 ga butun bo‘lib bo‘lmaydi, javob kasr son bo‘ladi.', 'Знак «—»: 1000 и 100 не делятся на 3 нацело, ответ получится дробным.', 'The “—” means 1000 and 100 do not divide exactly by 3; the answer would be a fraction.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Maxrajni ham ko‘paytirish.</b> ' + F(2, 7) + ' · 3 = ' + F(6, 21) + ' — xato! ' + F(6, 21) + ' = ' + F(2, 7) + ', ya’ni hech narsa o‘zgarmay qoldi. To‘g‘ri: ' + F(6, 7) + '.', '<b>Умножают и знаменатель.</b> ' + F(2, 7) + ' · 3 = ' + F(6, 21) + ' — ошибка! Ведь ' + F(6, 21) + ' = ' + F(2, 7) + ', то есть ничего не изменилось. Правильно: ' + F(6, 7) + '.', '<b>Multiplying the denominator too.</b> ' + F(2, 7) + ' · 3 = ' + F(6, 21) + ' is wrong! ' + F(6, 21) + ' = ' + F(2, 7) + ', so nothing changed. Correct: ' + F(6, 7) + '.'),
      L('<b>Qismni topishda amallarni almashtirish.</b> 24 ning ' + F(3, 4) + ' qismi: 24 : 3 · 4 = 32 — xato (javob butundan katta chiqdi!). Maxrajga bo‘lamiz, suratga ko‘paytiramiz.', '<b>Путают действия при нахождении части.</b> ' + F(3, 4) + ' от 24: 24 : 3 · 4 = 32 — ошибка (ответ больше целого!). Делим на знаменатель, умножаем на числитель.', '<b>Swapping the steps.</b> ' + F(3, 4) + ' of 24: 24 : 3 · 4 = 32 is wrong (bigger than the whole!). Divide by the denominator, multiply by the numerator.'),
      L('<b>Noto‘g‘ri kasrni qoldirish.</b> ' + F(12, 5) + ' javobini ' + M(2, 2, 5) + ' ga aylantiring — shunda qiymatni tasavvur qilish oson.', '<b>Оставляют неправильную дробь.</b> Ответ ' + F(12, 5) + ' переведите в ' + M(2, 2, 5) + ' — так легче представить величину.', '<b>Leaving it improper.</b> Turn ' + F(12, 5) + ' into ' + M(2, 2, 5) + ' — it is easier to picture.'),
      L('<b>Butunni noto‘g‘ri tanlash.</b> «Qolganining ' + F(1, 2) + ' qismi» — bu boshlang‘ich sonning emas, qolgan sonning yarmi. Bu haqida keyingi mavzularda batafsil.', '<b>Неверно выбирают целое.</b> «' + F(1, 2) + ' остатка» — половина остатка, а не исходного числа. Подробнее — в следующих темах.', '<b>Choosing the wrong whole.</b> “' + F(1, 2) + ' of the rest” is half of what remains, not of the starting number. More on this in later topics.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Uses in everyday life'), p: [
      L('<b>Chegirmalar.</b> 120 000 so‘mlik krossovkaga «' + F(1, 4) + ' chegirma» berildi. Chegirma: 120 000 : 4 = 30 000 so‘m. Yangi narx: 90 000 so‘m — bu eski narxning ' + F(3, 4) + ' qismi.', '<b>Скидки.</b> На кроссовки за 120 000 сумов дали скидку «' + F(1, 4) + '». Скидка: 120 000 : 4 = 30 000 сумов. Новая цена: 90 000 сумов — это ' + F(3, 4) + ' старой цены.', '<b>Discounts.</b> Trainers costing 120 000 sum get a “' + F(1, 4) + ' off” discount. Discount: 120 000 : 4 = 30 000 sum. New price: 90 000 sum — ' + F(3, 4) + ' of the old price.'),
      L('<b>Sinf va maktab.</b> Sinfda 36 o‘quvchi, ularning ' + F(2, 3) + ' qismi to‘garakka qatnashadi: 36 : 3 · 2 = 24 nafar. Maktab hovlisining ' + F(1, 5) + ' qismi gulzor: maydon 2 000 m² bo‘lsa, gulzor 400 m².', '<b>Класс и школа.</b> В классе 36 учеников, ' + F(2, 3) + ' из них ходят в кружки: 36 : 3 · 2 = 24 ученика. ' + F(1, 5) + ' школьного двора — клумбы: при площади 2 000 м² клумбы занимают 400 м².', '<b>Class and school.</b> A class has 36 pupils and ' + F(2, 3) + ' go to clubs: 36 : 3 · 2 = 24 pupils. ' + F(1, 5) + ' of the school yard is flowerbeds: with an area of 2 000 m², that is 400 m².'),
      L('<b>Tabiat.</b> Inson tanasining taxminan ' + F(3, 5) + ' qismi suvdan iborat. 40 kg vaznli bolada taxminan 40 : 5 · 3 = 24 kg suv bor! Yer yuzasining esa qariyb ' + F(7, 10) + ' qismini okeanlar egallaydi.', '<b>Природа.</b> Тело человека примерно на ' + F(3, 5) + ' состоит из воды. В ребёнке весом 40 кг около 40 : 5 · 3 = 24 кг воды! А почти ' + F(7, 10) + ' поверхности Земли занимают океаны.', '<b>Nature.</b> About ' + F(3, 5) + ' of the human body is water. A 40 kg child holds about 40 : 5 · 3 = 24 kg of water! And oceans cover nearly ' + F(7, 10) + ' of the Earth’s surface.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Inson umrining taxminan ' + F(1, 3) + ' qismi uyquda o‘tadi: 75 yil yashagan odam qariyb 25 yil uxlaydi!', 'Примерно ' + F(1, 3) + ' жизни человек проводит во сне: проживший 75 лет спит около 25 лет!', 'People spend about ' + F(1, 3) + ' of their lives asleep: someone who lives 75 years sleeps for about 25!'),
      L('Oyning faqat ' + F(1, 2) + ' qismini (taxminan) biz Yerdan doim ko‘ramiz — uning orqa tomoni hech qachon ko‘rinmaydi.', 'С Земли мы всегда видим лишь (примерно) ' + F(1, 2) + ' Луны — её обратная сторона никогда не видна.', 'From Earth we only ever see (about) ' + F(1, 2) + ' of the Moon — its far side is never visible.'),
      L('Qadimgi Rimda meros solig‘i ' + F(1, 20) + ' qismni tashkil qilgan — bu «yigirmadan bir» deb atalgan.', 'В Древнем Риме налог на наследство составлял ' + F(1, 20) + ' — его так и называли «двадцатая».', 'In Ancient Rome the inheritance tax was ' + F(1, 20) + ' — it was simply called “the twentieth”.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L(F(3, 10) + ' · 7 = ?   ' + F(4, 15) + ' · 5 = ?', F(3, 10) + ' · 7 = ?   ' + F(4, 15) + ' · 5 = ?', F(3, 10) + ' · 7 = ?   ' + F(4, 15) + ' · 5 = ?'),
      L('72 ning ' + F(5, 9) + ' qismini toping.', 'Найдите ' + F(5, 9) + ' от 72.', 'Find ' + F(5, 9) + ' of 72.'),
      L('Qaysi biri ko‘p: 40 ning ' + F(3, 4) + ' qismi yoki 45 ning ' + F(2, 3) + ' qismi?', 'Что больше: ' + F(3, 4) + ' от 40 или ' + F(2, 3) + ' от 45?', 'Which is more: ' + F(3, 4) + ' of 40 or ' + F(2, 3) + ' of 45?')
    ], after: [
      L('Javoblar: ' + F(21, 10) + ' = ' + M(2, 1, 10) + '; ' + F(20, 15) + ' = ' + M(1, 1, 3) + '; 72 : 9 · 5 = 40; 30 va 30 — teng!', 'Ответы: ' + F(21, 10) + ' = ' + M(2, 1, 10) + '; ' + F(20, 15) + ' = ' + M(1, 1, 3) + '; 72 : 9 · 5 = 40; 30 и 30 — поровну!', 'Answers: ' + F(21, 10) + ' = ' + M(2, 1, 10) + '; ' + F(20, 15) + ' = ' + M(1, 1, 3) + '; 72 : 9 · 5 = 40; 30 and 30 — equal!')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Kasrni natural songa ko‘paytirish — bir xil kasrlarni qo‘shishning qisqa yozuvi.', 'Умножение дроби на натуральное число — краткая запись сложения одинаковых дробей.', 'Multiplying a fraction by a whole number is a short way of adding equal fractions.'),
      L(F('a', 'b') + ' · n = ' + F('a · n', 'b') + ': surat ko‘paytiriladi, maxraj o‘zgarmaydi.', F('a', 'b') + ' · n = ' + F('a · n', 'b') + ': умножаем числитель, знаменатель не меняется.', F('a', 'b') + ' · n = ' + F('a · n', 'b') + ': multiply the numerator; the denominator stays.'),
      L('Sonning ' + F('a', 'b') + ' qismi = son : b · a.', F('a', 'b') + ' от числа = число : b · a.', F('a', 'b') + ' of a number = number : b · a.'),
      L('Javobni qisqartiring va noto‘g‘ri kasrni aralash songa aylantiring.', 'Сокращайте ответ и переводите неправильную дробь в смешанное число.', 'Simplify the answer and turn improper fractions into mixed numbers.'),
      L('To‘g‘ri kasr qismi har doim butundan kichik — bu bilan javobni tekshiring.', 'Часть по правильной дроби всегда меньше целого — проверяйте этим ответ.', 'A proper fraction of a number is always less than the number — use this to check.')
    ] }
  ] });
})(this);
